def normalize_environment(environment: str) -> str:
    value = (environment or "STAGING").upper()
    if value not in {"STAGING", "PRODUCTION"}:
        raise HTTPException(status_code=400, detail="Environment must be STAGING or PRODUCTION")
    return value


