def normalize_payment_text(value, max_length: int = 500) -> str:
    text = "" if value is None else str(value)
    text = text.replace("\x00", "")
    text = re.sub(r"[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]", "", text)
    return text.strip()[:max_length]


def normalize_payment_base_url(value) -> str:
    url = normalize_payment_text(value or PAYMENT_GATEWAY_DEFAULT_SETTINGS["api_base_url"], 300).rstrip("/")
    parsed = urlparse(url)
    if parsed.scheme != "https" or not parsed.netloc:
        raise HTTPException(status_code=400, detail="Payment API base URL must be a valid https URL")
    return url


def normalize_payment_mode(value) -> str:
    mode = normalize_payment_text(value or "TEST", 20).upper()
    if mode not in PAYMENT_MODE_OPTIONS:
        raise HTTPException(status_code=400, detail="Payment mode must be TEST or LIVE")
    return mode


def normalize_payment_provider(value) -> str:
    provider = normalize_payment_text(value or "PAYMONGO", 40).upper()
    if provider not in PAYMENT_PROVIDER_OPTIONS:
        raise HTTPException(status_code=400, detail="Unsupported payment provider")
    return provider


def normalize_payment_currency(value) -> str:
    currency = normalize_payment_text(value or "PHP", 10).upper()
    if not re.fullmatch(r"[A-Z]{3}", currency):
        raise HTTPException(status_code=400, detail="Currency must be a 3-letter code such as PHP")
    return currency


def normalize_payment_methods(value) -> list[str]:
    raw_items = value if isinstance(value, list) else []
    methods = []
    seen = set()
    for item in raw_items:
        method = normalize_payment_text(item, 40).lower()
        method = PAYMENT_METHOD_ALIASES.get(method, method)
        if method not in PAYMENT_METHOD_OPTIONS or method in seen:
            continue
        seen.add(method)
        methods.append(method)
    return methods or ["gcash"]


def payment_enabled_checkout_methods(store: dict) -> list[str]:
    return normalize_payment_methods(store.get("enabled_payment_methods"))


def normalize_payment_url(value, fallback: str) -> str:
    url = normalize_payment_text(value or fallback, 500)
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise HTTPException(status_code=400, detail="Payment redirect URL must be a valid http or https URL")
    return url


def normalize_upload_image_url(value: Optional[str]) -> Optional[str]:
    text = normalize_payment_text(value, 500)
    if not text:
        return None
    if text.startswith("/api/uploads/"):
        return text
    parsed = urlparse(text)
    if parsed.scheme in {"http", "https"} and parsed.netloc:
        return text
    raise HTTPException(status_code=400, detail="Image URL must be an uploaded /api/uploads path or a valid http/https URL")


def mask_payment_secret(value: Optional[str]) -> Optional[str]:
    text = normalize_payment_text(value)
    if not text:
        return None
    if len(text) <= 12:
        return f"{text[:4]}..."
    return f"{text[:8]}...{text[-4:]}"


def normalize_payment_credentials(store: dict) -> dict:
    raw_credentials = store.get("credentials") if isinstance(store.get("credentials"), dict) else {}
    credentials = {}
    for mode in PAYMENT_MODE_OPTIONS:
        raw_mode = raw_credentials.get(mode) if isinstance(raw_credentials.get(mode), dict) else {}
        credentials[mode] = {
            "public_key": normalize_payment_text(raw_mode.get("public_key"), 500),
            "secret_key_encrypted": normalize_payment_text(raw_mode.get("secret_key_encrypted"), 2000),
            "webhook_secret_encrypted": normalize_payment_text(raw_mode.get("webhook_secret_encrypted"), 2000),
        }
    legacy_mode = normalize_payment_mode(store.get("mode"))
    if store.get("public_key") and not credentials[legacy_mode].get("public_key"):
        credentials[legacy_mode]["public_key"] = normalize_payment_text(store.get("public_key"), 500)
    if store.get("secret_key_encrypted") and not credentials[legacy_mode].get("secret_key_encrypted"):
        credentials[legacy_mode]["secret_key_encrypted"] = normalize_payment_text(store.get("secret_key_encrypted"), 2000)
    if store.get("webhook_secret_encrypted") and not credentials[legacy_mode].get("webhook_secret_encrypted"):
        credentials[legacy_mode]["webhook_secret_encrypted"] = normalize_payment_text(store.get("webhook_secret_encrypted"), 2000)
    return credentials


def public_payment_credential_payload(credentials: dict, mode: str) -> dict:
    mode_credentials = credentials.get(mode, {})
    public_key = normalize_payment_text(mode_credentials.get("public_key"), 500)
    secret_key = decrypt_secret(mode_credentials.get("secret_key_encrypted"))
    webhook_secret = decrypt_secret(mode_credentials.get("webhook_secret_encrypted"))
    return {
        "public_key": public_key,
        "public_key_configured": bool(public_key),
        "public_key_hint": mask_payment_secret(public_key),
        "secret_key_configured": bool(secret_key),
        "secret_key_hint": mask_payment_secret(secret_key),
        "webhook_secret_configured": bool(webhook_secret),
        "webhook_secret_hint": mask_payment_secret(webhook_secret),
    }


def public_paymongo_telegram_settings(store: dict) -> dict:
    token = decrypt_secret(store.get("telegram_bot_token_encrypted"))
    return {
        "enabled": bool(store.get("telegram_enabled")),
        "bot_token_configured": bool(token),
        "bot_token_hint": mask_payment_secret(token),
        "chat_id": store.get("telegram_chat_id") or "",
        "last_status": store.get("telegram_last_status") or "",
        "last_error": store.get("telegram_last_error") or "",
        "last_sent_at": store.get("telegram_last_sent_at"),
    }


def payment_gateway_store() -> dict:
    row = fetch_one("SELECT value FROM app_settings WHERE key = 'payment_gateway'")
    value = row["value"] if row and isinstance(row["value"], dict) else {}
    store = {**PAYMENT_GATEWAY_DEFAULT_SETTINGS, **value}
    store["enabled"] = bool(store.get("enabled"))
    store["provider"] = normalize_payment_provider(store.get("provider"))
    store["mode"] = normalize_payment_mode(store.get("mode"))
    store["api_base_url"] = normalize_payment_base_url(store.get("api_base_url"))
    store["currency"] = normalize_payment_currency(store.get("currency"))
    store["enabled_payment_methods"] = normalize_payment_methods(store.get("enabled_payment_methods"))
    store["success_url"] = normalize_payment_url(store.get("success_url"), PAYMENT_GATEWAY_DEFAULT_SETTINGS["success_url"])
    store["cancel_url"] = normalize_payment_url(store.get("cancel_url"), PAYMENT_GATEWAY_DEFAULT_SETTINGS["cancel_url"])
    store["telegram_enabled"] = bool(store.get("telegram_enabled"))
    store["telegram_bot_token_encrypted"] = normalize_payment_text(store.get("telegram_bot_token_encrypted"), 2000)
    store["telegram_chat_id"] = normalize_payment_text(store.get("telegram_chat_id"), 120)
    store["telegram_last_status"] = normalize_payment_text(store.get("telegram_last_status"), 80)
    store["telegram_last_error"] = normalize_payment_text(store.get("telegram_last_error"), 1000)
    store["notes"] = normalize_payment_text(store.get("notes"), 1000)
    store["credentials"] = normalize_payment_credentials(store)
    return store


def save_payment_gateway_store(store: dict):
    credentials = normalize_payment_credentials(store)
    clean = {
        "enabled": bool(store.get("enabled")),
        "provider": normalize_payment_provider(store.get("provider")),
        "mode": normalize_payment_mode(store.get("mode")),
        "api_base_url": normalize_payment_base_url(store.get("api_base_url")),
        "credentials": credentials,
        "currency": normalize_payment_currency(store.get("currency")),
        "enabled_payment_methods": normalize_payment_methods(store.get("enabled_payment_methods")),
        "success_url": normalize_payment_url(store.get("success_url"), PAYMENT_GATEWAY_DEFAULT_SETTINGS["success_url"]),
        "cancel_url": normalize_payment_url(store.get("cancel_url"), PAYMENT_GATEWAY_DEFAULT_SETTINGS["cancel_url"]),
        "telegram_enabled": bool(store.get("telegram_enabled")),
        "telegram_bot_token_encrypted": normalize_payment_text(store.get("telegram_bot_token_encrypted"), 2000),
        "telegram_chat_id": normalize_payment_text(store.get("telegram_chat_id"), 120),
        "telegram_last_status": normalize_payment_text(store.get("telegram_last_status"), 80),
        "telegram_last_error": normalize_payment_text(store.get("telegram_last_error"), 1000),
        "telegram_last_sent_at": store.get("telegram_last_sent_at"),
        "notes": normalize_payment_text(store.get("notes"), 1000),
    }
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO app_settings(key, value, updated_at)
                VALUES ('payment_gateway', %s, now())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
                """,
                (Json(clean),),
            )


def public_payment_gateway_settings() -> dict:
    store = payment_gateway_store()
    credentials = store.get("credentials") or {}
    credential_payloads = {mode: public_payment_credential_payload(credentials, mode) for mode in PAYMENT_MODE_OPTIONS}
    active_mode = normalize_payment_mode(store.get("mode"))
    active_credentials = credential_payloads[active_mode]
    enabled_methods = store.get("enabled_payment_methods") or []
    ready_for_checkout = bool(active_credentials["public_key_configured"] and active_credentials["secret_key_configured"] and enabled_methods)
    ready_for_webhooks = bool(active_credentials["webhook_secret_configured"])
    return {
        "enabled": bool(store.get("enabled")),
        "provider": store.get("provider"),
        "mode": store.get("mode"),
        "api_base_url": store.get("api_base_url"),
        "credentials": credential_payloads,
        "public_key": active_credentials["public_key"],
        "public_key_configured": active_credentials["public_key_configured"],
        "public_key_hint": active_credentials["public_key_hint"],
        "secret_key_configured": active_credentials["secret_key_configured"],
        "secret_key_hint": active_credentials["secret_key_hint"],
        "webhook_secret_configured": active_credentials["webhook_secret_configured"],
        "webhook_secret_hint": active_credentials["webhook_secret_hint"],
        "currency": store.get("currency"),
        "enabled_payment_methods": enabled_methods,
        "payment_method_options": [{"id": key, "label": label} for key, label in PAYMENT_METHOD_OPTIONS.items()],
        "success_url": store.get("success_url"),
        "cancel_url": store.get("cancel_url"),
        "telegram": public_paymongo_telegram_settings(store),
        "notes": store.get("notes"),
        "phase": "PHASE_2_CHECKOUT_FOUNDATION",
        "ready_for_gcash": ready_for_checkout,
        "ready_for_checkout": ready_for_checkout,
        "ready_for_webhooks": ready_for_webhooks,
        "webhook_endpoint_path": "/api/payments/paymongo/webhook",
        "requirements": {
            "public_key": active_credentials["public_key_configured"],
            "secret_key": active_credentials["secret_key_configured"],
            "webhook_secret": active_credentials["webhook_secret_configured"],
            "checkout_method_enabled": bool(enabled_methods),
            "gcash_enabled": "gcash" in enabled_methods,
            "payments_enabled": bool(store.get("enabled")),
        },
        "next_phase": "Verify a PayMongo webhook in test mode before enabling live customer checkout.",
    }


PAYMONGO_WEBHOOK_TOLERANCE_SECONDS = 30 * 60


def payment_gateway_active_credentials(store: Optional[dict] = None, mode: Optional[str] = None) -> dict:
    store = store or payment_gateway_store()
    active_mode = normalize_payment_mode(mode or store.get("mode"))
    mode_credentials = (store.get("credentials") or {}).get(active_mode, {})
    return {
        "mode": active_mode,
        "public_key": normalize_payment_text(mode_credentials.get("public_key"), 500),
        "secret_key": decrypt_secret(mode_credentials.get("secret_key_encrypted")),
        "webhook_secret": decrypt_secret(mode_credentials.get("webhook_secret_encrypted")),
    }


def public_payment_gateway_portal_status() -> dict:
    store = payment_gateway_store()
    active = payment_gateway_active_credentials(store)
    enabled_methods = store.get("enabled_payment_methods") or []
    checkout_ready = bool(
        store.get("enabled")
        and active.get("public_key")
        and active.get("secret_key")
        and enabled_methods
    )
    return {
        "enabled": bool(store.get("enabled")),
        "provider": store.get("provider"),
        "mode": active["mode"],
        "currency": store.get("currency"),
        "enabled_payment_methods": enabled_methods,
        "payment_method_options": [{"id": key, "label": label} for key, label in PAYMENT_METHOD_OPTIONS.items()],
        "ready_for_checkout": checkout_ready,
        "ready_for_webhooks": bool(active.get("webhook_secret")),
        "public_key_configured": bool(active.get("public_key")),
        "secret_key_configured": bool(active.get("secret_key")),
        "webhook_secret_configured": bool(active.get("webhook_secret")),
    }


def payment_amount_centavos(price) -> int:
    try:
        amount = Decimal(str(price or "0")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        raise HTTPException(status_code=400, detail="Invalid payment amount")
    centavos = int((amount * 100).to_integral_value(rounding=ROUND_HALF_UP))
    if centavos <= 0:
        raise HTTPException(status_code=400, detail="Product price must be greater than zero for online checkout")
    return centavos


def append_url_params(url: str, params: dict) -> str:
    parsed = urlparse(url)
    query = dict(parse_qsl(parsed.query, keep_blank_values=True))
    for key, value in params.items():
        if value is not None:
            query[key] = str(value)
    return urlunparse(parsed._replace(query=urlencode(query)))


def generate_payment_order_public_id() -> str:
    return f"PMO-{secrets.token_urlsafe(12).replace('_', '').replace('-', '').upper()[:16]}"


def paymongo_api_url(store: dict, path: str) -> str:
    base_url = normalize_payment_base_url(store.get("api_base_url")).rstrip("/")
    return f"{base_url}/{path.lstrip('/')}"


def paymongo_request(store: dict, secret_key: str, method: str, path: str, payload: Optional[dict] = None) -> dict:
    if not secret_key:
        raise HTTPException(status_code=400, detail="PayMongo secret key is not configured for the active mode")
    try:
        response = requests.request(
            method,
            paymongo_api_url(store, path),
            auth=(secret_key, ""),
            headers={"accept": "application/json", "content-type": "application/json"},
            json=payload,
            timeout=25,
        )
        data = response.json() if response.content else {}
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"PayMongo request failed: {exc}")
    except ValueError:
        data = {"raw_response": response.text}
    if response.status_code >= 400:
        message = "PayMongo rejected the checkout request"
        errors = data.get("errors") if isinstance(data, dict) else None
        if isinstance(errors, list) and errors:
            first = errors[0] if isinstance(errors[0], dict) else {}
            raw_message = first.get("detail") or first.get("message") or message
            code = first.get("code") or first.get("sub_code") or first.get("subCode") or first.get("status")
            message = paymongo_customer_failure_message(code, raw_message)
        raise HTTPException(status_code=502, detail=message)
    return data if isinstance(data, dict) else {}


def paymongo_checkout_phone(value: Optional[str]) -> Optional[str]:
    original = normalize_payment_text(value, 32)
    digits = re.sub(r"\D", "", original)
    if not digits:
        return None
    if digits.startswith("63") and len(digits) == 12:
        return digits[2:]
    if digits.startswith("9") and len(digits) == 10:
        return digits
    if digits.startswith("09") and len(digits) == 11:
        return digits[1:]
    return None


def paymongo_checkout_billing(order: dict) -> dict:
    billing = {}
    name = normalize_payment_text(order.get("customer_name"), 120)
    email = normalize_payment_text(order.get("customer_email"), 255)
    phone = paymongo_checkout_phone(order.get("customer_contact_number"))
    if name:
        billing["name"] = name
    if email:
        billing["email"] = email
    if phone:
        billing["phone"] = phone
    return billing


def paymongo_create_checkout_session(store: dict, secret_key: str, order: dict, session: dict) -> dict:
    payment_method_types = payment_enabled_checkout_methods(store)
    if not payment_method_types:
        raise HTTPException(status_code=400, detail="Enable at least one PayMongo checkout method before accepting online payments")
    purchase_quantity = max(1, int(order.get("purchase_quantity") or 1))
    discount_amount = int(order.get("discount_amount_centavos") or 0)
    quantity_label = f" x{purchase_quantity}" if purchase_quantity > 1 else ""
    discount_label = f" Discount applied: PHP {discount_amount / 100:.2f}." if discount_amount > 0 else ""
    default_product_description = f"{order['duration_seconds']} seconds WiFi access for one device.{discount_label}"
    success_url = append_url_params(store.get("success_url"), {
        "payment": "success",
        "payment_order_id": order["public_order_id"],
        "handoff": create_portal_handoff_token(session.get("public_session_id"), ttl_seconds=1800),
    })
    cancel_url = append_url_params(store.get("cancel_url"), {
        "payment": "cancelled",
        "payment_order_id": order["public_order_id"],
    })
    attributes = {
        "cancel_url": cancel_url,
        "success_url": success_url,
        "description": f"{order['product_name']}{quantity_label} WiFi access",
        "line_items": [
            {
                "currency": order["currency"],
                "amount": int(order["amount_centavos"]),
                "name": f"{order['product_name']}{quantity_label}",
                "description": order.get("product_description") or default_product_description,
                "quantity": 1,
            }
        ],
        "payment_method_types": payment_method_types,
        "reference_number": order["public_order_id"],
        "send_email_receipt": False,
        "show_description": True,
        "show_line_items": True,
        "metadata": {
            "payment_order_id": order["public_order_id"],
            "portal_session_id": session["public_session_id"],
            "product_item_id": str(order["product_item_id"]) if order.get("product_item_id") else "",
            "product_category_id": str(order["product_category_id"]) if order.get("product_category_id") else "",
            "product_category_name": order.get("product_category_name") or "",
            "product_category_access_scope": order.get("product_category_access_scope") or "ALL_LOCATIONS",
            "product_category_barangay": order.get("product_category_barangay") or "",
            "customer_name": order.get("customer_name") or "",
            "customer_email": order.get("customer_email") or "",
            "customer_contact_number": order.get("customer_contact_number") or "",
            "outside_network_purchase": "true" if order.get("outside_network_purchase") else "false",
            "purchase_quantity": str(purchase_quantity),
            "base_amount_centavos": str(order.get("base_amount_centavos") or order.get("amount_centavos") or ""),
            "discount_amount_centavos": str(discount_amount),
            "discount_type": order.get("discount_type") or "",
            "discount_value": str(order.get("discount_value") or ""),
        },
    }
    billing = paymongo_checkout_billing(order)
    if billing:
        attributes["billing"] = billing
    payload = {
        "data": {
            "attributes": attributes
        }
    }
    return paymongo_request(store, secret_key, "POST", "/checkout_sessions", payload)


def paymongo_expire_checkout_session(store: dict, secret_key: str, checkout_session_id: str) -> dict:
    session_id = normalize_payment_text(checkout_session_id, 120)
    if not session_id:
        return {}
    return paymongo_request(store, secret_key, "POST", f"/checkout_sessions/{session_id}/expire")


def parse_paymongo_signature(header: str) -> dict:
    parts = {}
    for raw_part in (header or "").split(","):
        if "=" not in raw_part:
            continue
        key, value = raw_part.split("=", 1)
        parts[key.strip()] = value.strip()
    return parts


def verify_paymongo_webhook_signature(raw_body: bytes, header: str) -> dict:
    parts = parse_paymongo_signature(header)
    timestamp = parts.get("t")
    if not timestamp:
        raise HTTPException(status_code=400, detail="Missing PayMongo webhook timestamp")
    try:
        sent_at = int(timestamp)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid PayMongo webhook timestamp")
    if abs(int(time.time()) - sent_at) > PAYMONGO_WEBHOOK_TOLERANCE_SECONDS:
        raise HTTPException(status_code=400, detail="PayMongo webhook timestamp is outside the accepted window")
    store = payment_gateway_store()
    signed_payload = timestamp.encode("utf-8") + b"." + raw_body
    for mode, signature_key in (("TEST", "te"), ("LIVE", "li")):
        provided = parts.get(signature_key)
        credentials = payment_gateway_active_credentials(store, mode)
        secret = credentials.get("webhook_secret")
        if not provided or not secret:
            continue
        expected = hmac.new(secret.encode("utf-8"), signed_payload, sha256).hexdigest()
        if hmac.compare_digest(expected, provided):
            return {"mode": mode, "timestamp": sent_at}
    raise HTTPException(status_code=400, detail="Invalid PayMongo webhook signature or missing webhook secret")


def nested_value(payload: dict, path: list[str]):
    current = payload
    for key in path:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def recursive_find_value(payload, keys: set[str]):
    if isinstance(payload, dict):
        for key, value in payload.items():
            if key in keys and value not in (None, ""):
                return value
        for value in payload.values():
            found = recursive_find_value(value, keys)
            if found not in (None, ""):
                return found
    if isinstance(payload, list):
        for value in payload:
            found = recursive_find_value(value, keys)
            if found not in (None, ""):
                return found
    return None


def paymongo_event_type(payload: dict) -> str:
    return (
        nested_value(payload, ["data", "attributes", "type"])
        or nested_value(payload, ["data", "type"])
        or ""
    )


def paymongo_event_id(payload: dict) -> str:
    return normalize_payment_text(nested_value(payload, ["data", "id"]) or f"evt_local_{secrets.token_urlsafe(18)}", 120)


def paymongo_event_resource(payload: dict) -> dict:
    resource = nested_value(payload, ["data", "attributes", "data"])
    return resource if isinstance(resource, dict) else {}


def paymongo_checkout_session_id(payload: dict) -> Optional[str]:
    value = (
        nested_value(payload, ["data", "attributes", "data", "id"])
        or nested_value(payload, ["data", "attributes", "data", "attributes", "checkout_session_id"])
        or recursive_find_value(payload, {"checkout_session_id", "checkoutSessionId"})
    )
    text = normalize_payment_text(value, 120)
    return text or None


def paymongo_event_is_paid(event_type: str) -> bool:
    return normalize_payment_text(event_type, 120).lower() in {
        "payment.paid",
        "link.payment.paid",
        "checkout_session.payment.paid",
        "checkout_session.paid",
    }


def paymongo_event_is_failed(event_type: str) -> bool:
    return normalize_payment_text(event_type, 120).lower() in {
        "payment.failed",
        "checkout_session.payment.failed",
        "checkout_session.failed",
        "checkout_session.expired",
    }


def paymongo_payment_reference(payload: dict) -> Optional[str]:
    def find_order_id(value):
        if isinstance(value, dict):
            for key, item in value.items():
                if key in {"payment_order_id", "public_order_id", "reference_number"}:
                    text = normalize_payment_text(item, 120)
                    if text.startswith("PMO-"):
                        return text
            for item in value.values():
                found = find_order_id(item)
                if found:
                    return found
        if isinstance(value, list):
            for item in value:
                found = find_order_id(item)
                if found:
                    return found
        return None

    return find_order_id(payload)


def paymongo_provider_payment_id(payload: dict) -> Optional[str]:
    value = nested_value(payload, ["data", "attributes", "data", "id"]) or recursive_find_value(payload, {"payment_id", "paymentId"})
    return normalize_payment_text(value, 120) or None


PAYMONGO_FAILURE_MESSAGES = {
    "CLOSED": "GCash payment was closed before it was completed. No WiFi pass was activated.",
    "CANCELLED": "Payment was cancelled before completion. No WiFi pass was activated.",
    "CANCELED": "Payment was cancelled before completion. No WiFi pass was activated.",
    "EXPIRED": "Payment session expired. Please start checkout again.",
    "AMOUNT_EXCEED_LIMIT": "GCash declined the payment because it exceeded a transaction or wallet limit. Try a smaller package or another payment method.",
    "AMOUNT_EXCEEDS_LIMIT": "GCash declined the payment because it exceeded a transaction or wallet limit. Try a smaller package or another payment method.",
    "SYSTEM_ERROR": "GCash or PayMongo had a temporary system issue. Please try again in a few minutes.",
    "PAYMENT_FAILED": "GCash payment failed. No WiFi pass was activated.",
    "FAILED": "Payment failed. No WiFi pass was activated.",
    "INSUFFICIENT_FUNDS": "GCash reported insufficient balance. Please top up GCash or choose another payment method.",
    "PROCESSOR_ERROR": "The payment processor could not complete the transaction. Please try again.",
}


def paymongo_customer_failure_message(code: Optional[str], fallback: str = "Payment was not completed.") -> str:
    clean_code = normalize_payment_text(code, 80).upper().replace(" ", "_").replace("-", "_")
    if clean_code in PAYMONGO_FAILURE_MESSAGES:
        return PAYMONGO_FAILURE_MESSAGES[clean_code]
    if fallback:
        return normalize_payment_text(fallback, 500) or "Payment was not completed."
    return ""


def paymongo_failure_code(payload: dict) -> str:
    value = (
        recursive_find_value(payload, {"failure_code", "failed_code", "error_code", "errorCode", "code", "reason", "status"})
        or ""
    )
    return normalize_payment_text(value, 80).upper().replace(" ", "_").replace("-", "_")


def paymongo_failure_message(payload: dict, fallback: str = "PayMongo reported payment failed.") -> str:
    code = paymongo_failure_code(payload)
    if code:
        mapped = paymongo_customer_failure_message(code, "")
        if mapped:
            return mapped
    detail = recursive_find_value(payload, {"failure_message", "failed_message", "error_message", "message", "detail", "description"})
    detail_text = normalize_payment_text(detail, 500)
    if detail_text:
        return detail_text
    return fallback


def paymongo_payload_amount(payload: dict) -> Optional[int]:
    value = (
        nested_value(payload, ["data", "attributes", "data", "attributes", "amount"])
        or nested_value(payload, ["data", "attributes", "amount"])
        or recursive_find_value(payload, {"amount", "paid_amount"})
    )
    try:
        return int(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def paymongo_checkout_attributes(payload: dict) -> dict:
    data = payload.get("data") if isinstance(payload, dict) else {}
    attributes = data.get("attributes") if isinstance(data, dict) else {}
    return attributes if isinstance(attributes, dict) else {}


def paymongo_checkout_payments(payload: dict) -> list[dict]:
    attributes = paymongo_checkout_attributes(payload)
    payments = attributes.get("payments")
    if not isinstance(payments, list):
        payments = []
    intent = attributes.get("payment_intent") if isinstance(attributes.get("payment_intent"), dict) else {}
    intent_attributes = intent.get("attributes") if isinstance(intent.get("attributes"), dict) else {}
    intent_payments = intent_attributes.get("payments")
    if isinstance(intent_payments, list):
        payments = [*payments, *intent_payments]

    seen = set()
    unique_payments = []
    for payment in payments:
        if not isinstance(payment, dict):
            continue
        payment_id = payment.get("id") or json.dumps(sanitize_summary(payment), sort_keys=True)
        if payment_id in seen:
            continue
        seen.add(payment_id)
        unique_payments.append(payment)
    return unique_payments


def paymongo_paid_payment_from_checkout(payload: dict) -> Optional[dict]:
    for payment in paymongo_checkout_payments(payload):
        attributes = payment.get("attributes") if isinstance(payment.get("attributes"), dict) else {}
        status = normalize_payment_text(attributes.get("status"), 40).lower()
        if status == "paid" or attributes.get("paid_at"):
            return payment
    return None


def paymongo_checkout_is_paid(payload: dict) -> bool:
    attributes = paymongo_checkout_attributes(payload)
    if attributes.get("paid_at") or paymongo_paid_payment_from_checkout(payload):
        return True
    intent = attributes.get("payment_intent") if isinstance(attributes.get("payment_intent"), dict) else {}
    intent_attributes = intent.get("attributes") if isinstance(intent.get("attributes"), dict) else {}
    return normalize_payment_text(intent_attributes.get("status"), 40).lower() in {"succeeded", "paid"}


def paymongo_checkout_is_expired(payload: dict) -> bool:
    attributes = paymongo_checkout_attributes(payload)
    status = normalize_payment_text(attributes.get("status"), 40).lower()
    if status == "expired":
        return True
    expires_at = attributes.get("expires_at") or attributes.get("expiresAt")
    try:
        return expires_at is not None and int(expires_at) <= int(datetime.now(timezone.utc).timestamp())
    except (TypeError, ValueError, OSError):
        return False


def paymongo_checkout_paid_amount(payload: dict) -> Optional[int]:
    payment = paymongo_paid_payment_from_checkout(payload)
    payment_attributes = payment.get("attributes") if isinstance(payment, dict) and isinstance(payment.get("attributes"), dict) else {}
    value = payment_attributes.get("amount")
    if value is None:
        attributes = paymongo_checkout_attributes(payload)
        intent = attributes.get("payment_intent") if isinstance(attributes.get("payment_intent"), dict) else {}
        intent_attributes = intent.get("attributes") if isinstance(intent.get("attributes"), dict) else {}
        value = intent_attributes.get("amount")
    try:
        return int(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def paymongo_checkout_payment_id(payload: dict) -> Optional[str]:
    payment = paymongo_paid_payment_from_checkout(payload)
    if isinstance(payment, dict):
        return normalize_payment_text(payment.get("id"), 120) or None
    return None


def paymongo_checkout_paid_at(payload: dict) -> Optional[datetime]:
    attributes = paymongo_checkout_attributes(payload)
    paid_at = attributes.get("paid_at")
    payment = paymongo_paid_payment_from_checkout(payload)
    payment_attributes = payment.get("attributes") if isinstance(payment, dict) and isinstance(payment.get("attributes"), dict) else {}
    paid_at = payment_attributes.get("paid_at") or paid_at
    try:
        return datetime.fromtimestamp(int(paid_at), timezone.utc) if paid_at is not None else None
    except (TypeError, ValueError, OSError):
        return None


def sync_paymongo_checkout_status(cur, order: dict, request: Request) -> dict:
    if not order or order.get("provider") != "PAYMONGO" or not order.get("checkout_session_id"):
        return order
    if order.get("status") == "PAID" and order.get("fulfillment_status") == "FULFILLED":
        return order

    store = payment_gateway_store()
    credentials = payment_gateway_active_credentials(store, order.get("provider_mode") or store.get("mode"))
    checkout = paymongo_request(store, credentials.get("secret_key"), "GET", f"/checkout_sessions/{order['checkout_session_id']}")
    paid = paymongo_checkout_is_paid(checkout)
    provider_payment_id = paymongo_checkout_payment_id(checkout)

    if not paid:
        if paymongo_checkout_is_expired(checkout):
            cur.execute(
                """
                UPDATE payment_orders
                SET status = 'EXPIRED',
                    fulfillment_status = 'NOT_REQUIRED',
                    provider_response_json = %s,
                    last_error = 'Payment session expired. Please start checkout again.',
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (Json(sanitize_summary(checkout)), order["id"]),
            )
            order = cur.fetchone()
            finalize_omada_payment_auth_free_grants_for_order(cur, order, final_status="CANCELLED")
            if order.get("portal_session_id"):
                create_portal_event(
                    cur,
                    order["portal_session_id"],
                    "PAYMENT_EXPIRED",
                    request,
                    "PayMongo checkout session expired.",
                    raw_context={"payment_order_id": order["public_order_id"], "source": "checkout_status_reconciliation"},
                )
            return order
        cur.execute(
            """
            UPDATE payment_orders
            SET provider_response_json = %s,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (Json(sanitize_summary(checkout)), order["id"]),
        )
        return cur.fetchone()

    paid_amount = paymongo_checkout_paid_amount(checkout)
    if paid_amount is None:
        raise RuntimeError("PayMongo checkout is paid, but the paid amount could not be verified.")
    if int(paid_amount) != int(order["amount_centavos"]):
        raise RuntimeError(f"Paid amount mismatch. Expected {order['amount_centavos']} centavos, got {paid_amount}.")

    paid_at = paymongo_checkout_paid_at(checkout)
    sync_event_id = f"checkout_sync:{order['checkout_session_id']}:{provider_payment_id or int((paid_at or datetime.now(timezone.utc)).timestamp())}"
    cur.execute(
        """
        UPDATE payment_orders
        SET status = 'PAID',
            provider_payment_id = COALESCE(%s, provider_payment_id),
            provider_event_id = COALESCE(provider_event_id, %s),
            provider_response_json = %s,
            paid_at = COALESCE(paid_at, %s, now()),
            last_error = NULL,
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (provider_payment_id, sync_event_id, Json(sanitize_summary(checkout)), paid_at, order["id"]),
    )
    order = cur.fetchone()
    if order.get("portal_session_id"):
        create_portal_event(
            cur,
            order["portal_session_id"],
            "PAYMENT_PAID",
            request,
            "PayMongo payment marked paid by checkout status check",
            raw_context={"payment_order_id": order["public_order_id"], "source": "checkout_status_reconciliation", "payment_id": provider_payment_id},
        )

    try:
        fulfillment = fulfill_paid_payment_order(cur, order, request)
        schedule_omada_payment_auth_free_paid_cleanup_for_order(cur, fulfillment.get("order") or order, reason="CHECKOUT_STATUS_PAID")
        return fulfillment.get("order") or order
    except Exception as exc:
        message = str(exc)
        cur.execute(
            """
            UPDATE payment_orders
            SET fulfillment_status = 'FAILED',
                last_error = %s,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (message, order["id"]),
        )
        order = cur.fetchone()
        if order.get("portal_session_id"):
            create_portal_event(cur, order["portal_session_id"], "PAYMENT_FULFILLMENT_FAILED", request, message, raw_context={"payment_order_id": order["public_order_id"], "source": "checkout_status_reconciliation"})
        return order


def process_paymongo_checkout_reconciliation_once(limit: int = 20) -> int:
    reconciled = 0
    request_context = InternalRequestContext("3J PayMongo checkout reconciliation worker")
    with get_conn() as conn:
        with conn.cursor() as cur:
            cleanup_expired_omada_payment_auth_free_grants(cur, limit=50)
            cur.execute(
                """
                SELECT *
                FROM payment_orders
                WHERE provider = 'PAYMONGO'
                  AND checkout_session_id IS NOT NULL
                  AND status IN ('PENDING', 'CHECKOUT_CREATED')
                  AND created_at >= now() - interval '3 days'
                  AND updated_at <= now() - interval '20 seconds'
                ORDER BY created_at ASC
                LIMIT %s
                FOR UPDATE SKIP LOCKED
                """,
                (limit,),
            )
            orders = cur.fetchall()
            for order in orders:
                try:
                    synced = sync_paymongo_checkout_status(cur, order, request_context)
                    if synced and synced.get("status") != order.get("status"):
                        reconciled += 1
                except Exception as exc:
                    cur.execute(
                        """
                        UPDATE payment_orders
                        SET last_error = %s,
                            updated_at = now()
                        WHERE id = %s
                        """,
                        (f"PayMongo reconciliation failed: {exc}", order["id"]),
                    )
                    if order.get("portal_session_id"):
                        create_portal_event(
                            cur,
                            order["portal_session_id"],
                            "PAYMENT_RECONCILIATION_FAILED",
                            request_context,
                            str(exc),
                            raw_context={"payment_order_id": order["public_order_id"], "source": "background_paymongo_reconciliation"},
                        )
    return reconciled


def start_paymongo_checkout_reconciliation_worker():
    global PAYMONGO_RECONCILIATION_THREAD_STARTED
    if PAYMONGO_RECONCILIATION_THREAD_STARTED:
        return
    PAYMONGO_RECONCILIATION_THREAD_STARTED = True

    def worker():
        while True:
            try:
                process_paymongo_checkout_reconciliation_once()
            except Exception as exc:
                print(f"PayMongo reconciliation worker failed: {exc}")
            time.sleep(20)

    threading.Thread(target=worker, daemon=True).start()


def payment_order_status_payload(order: Optional[dict]) -> dict:
    if not order:
        return {"found": False, "status": "NOT_FOUND"}
    bag_item = order.get("_bag_item")
    payment_access_grant = order.get("_payment_access_grant")
    return {
        "found": True,
        "payment_order_id": order["public_order_id"],
        "status": order["status"],
        "fulfillment_status": order["fulfillment_status"],
        "provider": order["provider"],
        "mode": order["provider_mode"],
        "payment_method": order["payment_method"],
        "amount_centavos": order["amount_centavos"],
        "currency": order["currency"],
        "product_name": order["product_name"],
        "product_kind": order.get("product_kind") or "WIFI",
        "product_kind_label": product_kind_label(order.get("product_kind")),
        "iptv_enabled": product_kind_requires_iptv(order.get("product_kind")),
        "iptv_package_label": order.get("iptv_package_label"),
        "iptv_xui_package_id": order.get("iptv_xui_package_id"),
        "product_category_name": order.get("product_category_name"),
        "product_category_access_scope": order.get("product_category_access_scope") or "ALL_LOCATIONS",
        "product_category_barangay": order.get("product_category_barangay"),
        "duration_seconds": order["duration_seconds"],
        "customer_name": order.get("customer_name"),
        "customer_email": order.get("customer_email"),
        "customer_contact_number": order.get("customer_contact_number"),
        "outside_network_purchase": bool(order.get("outside_network_purchase")),
        "checkout_url": order.get("checkout_url"),
        "payment_access_grant": payment_access_grant,
        "payment_window_expires_at": payment_access_grant.get("expires_at") if payment_access_grant else None,
        "last_error": order.get("last_error"),
        "portal_session_id": order.get("_portal_session_public_id"),
        "portal_handoff_url": order.get("_portal_handoff_url"),
        "device_token": order.get("_device_token"),
        "paid_at": order.get("paid_at"),
        "fulfilled_at": order.get("fulfilled_at"),
        "voucher_id": str(order["voucher_id"]) if order.get("voucher_id") else None,
        "bag_item": bag_item_public(bag_item) if bag_item else None,
        "bag_item_status": bag_item.get("status") if bag_item else None,
        "created_at": order.get("created_at"),
        "updated_at": order.get("updated_at"),
    }


def a2p_join_url(base_url: str, path: str) -> str:
    return f"{base_url.rstrip('/')}/{path.lstrip('/')}"


def normalize_a2p_destination(value: str) -> str:
    original = normalize_a2p_text(value, 32)
    digits = re.sub(r"\D", "", original)
    if digits.startswith("09") and len(digits) == 11:
        digits = f"63{digits[1:]}"
    if not re.fullmatch(r"\d{8,15}", digits or ""):
        raise HTTPException(status_code=400, detail="Destination must be an international-format mobile number, for example 639171234567")
    return digits


def mask_a2p_destination(destination: str) -> str:
    digits = normalize_a2p_text(destination, 32)
    if len(digits) <= 6:
        return "***"
    return f"{digits[:4]}...{digits[-3:]}"


def safe_mask_a2p_destination(destination: Optional[str]) -> str:
    digits = re.sub(r"\D", "", normalize_a2p_text(destination, 32))
    if not digits:
        return ""
    if len(digits) <= 6:
        return "***"
    return f"{digits[:4]}...{digits[-3:]}"


def a2p_auth_parts(store: dict):
    headers = {"User-Agent": "3JCentralPisowifi/0.1 a2p-messaging"}
    auth = None
    extra_params = {}
    api_key = decrypt_secret(store.get("api_key_encrypted"))
    username = normalize_a2p_text(store.get("username"), 200)
    password = decrypt_secret(store.get("password_encrypted"))
    auth_method = store.get("auth_method")
    if auth_method == "API_KEY_HEADERS":
        if not store.get("api_id") or not api_key:
            raise HTTPException(status_code=400, detail="Save API ID and API key first")
        headers["X-MEMS-API-ID"] = store["api_id"]
        headers["X-MEMS-API-KEY"] = api_key
    elif auth_method == "BASIC_AUTH":
        if not username or not password:
            raise HTTPException(status_code=400, detail="Save username and password first")
        auth = (username, password)
    else:
        if not username or not password:
            raise HTTPException(status_code=400, detail="Save username and password first")
        extra_params["username"] = username
        extra_params["password"] = password
    return headers, auth, extra_params


def create_admin_notification(
    category: str,
    severity: str,
    title: str,
    message: str = "",
    target_page: str = "",
    target_url: str = "",
    related_table: str = "",
    related_id: str = "",
    metadata: Optional[dict] = None,
):
    try:
        with get_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO admin_notifications(
                        category, severity, title, message, target_page, target_url,
                        related_table, related_id, metadata_json
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    RETURNING id
                    """,
                    (
                        normalize_payment_text(category, 80).upper() or "SYSTEM",
                        normalize_payment_text(severity, 20).upper() or "INFO",
                        normalize_payment_text(title, 200) or "System notification",
                        normalize_payment_text(message, 1000),
                        normalize_payment_text(target_page, 80),
                        normalize_payment_text(target_url, 300),
                        normalize_payment_text(related_table, 80),
                        normalize_payment_text(related_id, 120),
                        Json(sanitize_summary(metadata or {})),
                    ),
                )
                row = cur.fetchone()
                return str(row["id"]) if row else None
    except Exception as exc:
        print(f"admin notification log failed: {exc}")
        return None


def update_payment_gateway_telegram_status(status: str, error: str = "", sent_at: Optional[datetime] = None):
    try:
        store = payment_gateway_store()
        store["telegram_last_status"] = normalize_payment_text(status, 80)
        store["telegram_last_error"] = normalize_payment_text(error, 1000)
        if sent_at:
            store["telegram_last_sent_at"] = sent_at.isoformat()
        save_payment_gateway_store(store)
    except Exception as exc:
        print(f"PayMongo Telegram status update failed: {exc}")


def send_paymongo_telegram_alert(title: str, message: str, metadata: Optional[dict] = None) -> Optional[dict]:
    store = payment_gateway_store()
    if not store.get("telegram_enabled"):
        return None
    token = decrypt_secret(store.get("telegram_bot_token_encrypted"))
    chat_id = normalize_payment_text(store.get("telegram_chat_id"), 120)
    if not token or not chat_id:
        update_payment_gateway_telegram_status("FAILED", "Telegram bot token or chat id is missing.")
        return None
    lines = [
        f"3J PayMongo Alert",
        f"{normalize_payment_text(title, 200)}",
        normalize_payment_text(message, 1000),
    ]
    metadata = sanitize_summary(metadata or {})
    if metadata:
        for key, value in list(metadata.items())[:8]:
            lines.append(f"{key}: {normalize_payment_text(value, 160)}")
    try:
        response = requests.post(
            f"https://api.telegram.org/bot{token}/sendMessage",
            json={"chat_id": chat_id, "text": "\n".join([line for line in lines if line])},
            timeout=12,
        )
        if response.status_code >= 400:
            raise RuntimeError(f"HTTP {response.status_code} {response.text[:300]}")
        update_payment_gateway_telegram_status("SUCCESS", "", datetime.now(timezone.utc))
        try:
            return response.json()
        except ValueError:
            return {"ok": True}
    except Exception as exc:
        update_payment_gateway_telegram_status("FAILED", str(exc))
        return None


def create_paymongo_admin_notification(
    title: str,
    message: str,
    *,
    severity: str = "DANGER",
    related_id: str = "",
    metadata: Optional[dict] = None,
    telegram: bool = True,
) -> Optional[str]:
    clean_related_id = normalize_payment_text(related_id or title, 120)
    try:
        existing = fetch_one(
            """
            SELECT id
            FROM admin_notifications
            WHERE category = 'PAYMONGO_ALERT'
              AND related_id = %s
              AND created_at > now() - interval '5 minutes'
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (clean_related_id,),
        )
        if existing:
            return str(existing["id"])
    except Exception:
        pass
    try:
        notification_id = create_admin_notification(
            "PAYMONGO_ALERT",
            severity,
            title,
            message,
            "PayMongo",
            "/admin/paymongo",
            "payment_orders",
            clean_related_id,
            metadata or {},
        )
    except Exception as exc:
        print(f"PayMongo admin notification failed: {exc}")
        notification_id = None
    if telegram:
        try:
            send_paymongo_telegram_alert(title, message, metadata)
        except Exception as exc:
            print(f"PayMongo Telegram alert failed: {exc}")
    return notification_id


def create_iptv_login_failure_notification(
    *,
    token: Optional[str] = None,
    stage: str = "TOKEN_HANDOFF",
    reason_code: str = "IPTV_LOGIN_FAILED",
    message: str = "",
    source_url: str = "",
    checked_urls: Optional[list[str]] = None,
    metadata: Optional[dict] = None,
    request: Optional[Request] = None,
    severity: str = "DANGER",
) -> Optional[str]:
    clean_stage = normalize_payment_text(stage, 80).upper() or "TOKEN_HANDOFF"
    clean_reason = normalize_payment_text(reason_code, 80).upper() or "IPTV_LOGIN_FAILED"
    clean_message = normalize_payment_text(message, 1000) or "Customer IPTV login could not be completed."
    token_hash = iptv_token_hash(token) if token else ""
    fingerprint = normalize_payment_text(f"{clean_stage}:{clean_reason}:{token_hash[:24] or 'NO_TOKEN'}", 120)
    try:
        existing = fetch_one(
            """
            SELECT id
            FROM admin_notifications
            WHERE category = 'IPTV_LOGIN_FAILED'
              AND related_id = %s
              AND created_at > now() - interval '5 minutes'
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (fingerprint,),
        )
        if existing:
            return str(existing["id"])
    except Exception:
        pass

    request_ip = ""
    request_user_agent = ""
    if request is not None:
        try:
            request_ip = request.client.host if request.client else ""
            request_user_agent = request.headers.get("user-agent", "")
        except Exception:
            request_ip = ""
            request_user_agent = ""

    return create_admin_notification(
        "IPTV_LOGIN_FAILED",
        severity,
        "IPTV customer login failed",
        clean_message,
        "IPTV",
        "/admin/iptv?tab=Logs",
        "iptv_login_tokens",
        fingerprint,
        {
            "stage": clean_stage,
            "reason_code": clean_reason,
            "source_url": normalize_payment_text(source_url, 500),
            "checked_urls": sanitize_summary(checked_urls or []),
            "token_hash_prefix": token_hash[:16] if token_hash else "",
            "request_ip": request_ip,
            "user_agent": normalize_payment_text(request_user_agent, 500),
            **sanitize_summary(metadata or {}),
        },
    )


def record_a2p_message_log(
    *,
    status: str,
    destination: Optional[str],
    source: Optional[str],
    message_text: Optional[str],
    purpose: str = "GENERAL",
    provider: str = "SMART_MESSAGING_SUITE",
    smart_status: Optional[str] = None,
    http_status: Optional[int] = None,
    message_id: Optional[str] = None,
    response_summary: Optional[str] = None,
    error_message: Optional[str] = None,
    request_context: Optional[dict] = None,
    created_by_admin_id: Optional[str] = None,
):
    normalized_status = normalize_payment_text(status, 20).upper() or "FAILED"
    if normalized_status not in {"PENDING", "SUCCESS", "FAILED"}:
        normalized_status = "FAILED"
    clean_destination = normalize_a2p_text(destination, 32)
    clean_message = normalize_a2p_text(message_text, 1000)
    row_id = None
    try:
        with get_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO a2p_message_logs(
                        provider, purpose, destination, destination_masked, source, message_text,
                        message_preview, status, smart_status, http_status, message_id,
                        response_summary, error_message, request_context_json, created_by_admin_id
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    RETURNING id
                    """,
                    (
                        normalize_payment_text(provider, 80) or "SMART_MESSAGING_SUITE",
                        normalize_payment_text(purpose, 80) or "GENERAL",
                        clean_destination,
                        safe_mask_a2p_destination(clean_destination),
                        normalize_a2p_text(source, 80),
                        clean_message,
                        clean_message[:160],
                        normalized_status,
                        normalize_payment_text(smart_status, 80),
                        http_status,
                        normalize_payment_text(message_id, 120),
                        normalize_payment_text(response_summary, 1000),
                        normalize_payment_text(error_message, 1000),
                        Json(sanitize_summary(request_context or {})),
                        created_by_admin_id,
                    ),
                )
                row = cur.fetchone()
                row_id = str(row["id"]) if row else None
    except Exception as exc:
        print(f"A2P message log failed: {exc}")
        return None

    if normalized_status == "FAILED":
        masked = safe_mask_a2p_destination(clean_destination)
        create_admin_notification(
            "A2P_SMS_FAILED",
            "DANGER",
            "A2P SMS failed",
            f"{normalize_payment_text(purpose, 80) or 'SMS'} to {masked or 'destination'} failed: {normalize_payment_text(error_message or response_summary, 500)}",
            "System Settings",
            "/admin/system-settings?tab=A2P%20Messaging&subtab=Messages",
            "a2p_message_logs",
            row_id or "",
            {
                "purpose": purpose,
                "destination": masked,
                "http_status": http_status,
                "smart_status": smart_status,
            },
        )
    return row_id


def send_a2p_sms_message(
    destination: str,
    message_text: str,
    source: Optional[str] = None,
    *,
    purpose: str = "GENERAL",
    request_context: Optional[dict] = None,
    created_by_admin_id: Optional[str] = None,
    registered_delivery: Optional[bool] = None,
) -> dict:
    raw_destination = normalize_a2p_text(destination, 32)
    raw_message = normalize_a2p_text(message_text, 1000)
    clean_source = ""
    store = a2p_messaging_store()
    try:
        if not store.get("enabled"):
            raise HTTPException(status_code=400, detail="A2P Messaging is disabled in System Settings.")
        clean_message = normalize_a2p_text(message_text, 500)
        if not clean_message:
            raise HTTPException(status_code=400, detail="SMS message text is required.")
        clean_destination = normalize_a2p_destination(destination)
        clean_source = normalize_a2p_text(source if source is not None else store.get("default_source"), 80)
        url = a2p_join_url(store["base_url"], store["send_path"])
        headers, auth, extra_params = a2p_auth_parts(store)
        headers["Accept"] = "text/plain"
        delivery_requested = store.get("registered_delivery") if registered_delivery is None else bool(registered_delivery)
        form_data = {
            **extra_params,
            "destination": clean_destination,
            "text": clean_message,
            "registered": "1" if delivery_requested else "0",
        }
        if clean_source:
            form_data["source"] = clean_source
        response = requests.post(url, headers=headers, auth=auth, data=form_data, timeout=30)
        text = normalize_a2p_text(response.text, 1000)
        message_id_match = re.search(r"Message[- ]ID\s*:\s*([^\s]+)", text, re.IGNORECASE)
        message_id = message_id_match.group(1) if message_id_match else None
        if response.status_code >= 400:
            error = f"Smart SMS send failed: HTTP {response.status_code} {text[:240]}"
            record_a2p_message_log(
                status="FAILED",
                destination=clean_destination,
                source=clean_source,
                message_text=clean_message,
                purpose=purpose,
                http_status=response.status_code,
                message_id=message_id,
                response_summary=text[:500],
                error_message=error,
                request_context=request_context,
                created_by_admin_id=created_by_admin_id,
            )
            raise HTTPException(status_code=400, detail=error)
        accepted = bool(re.match(r"^\s*0\s+\d{3}\s+OK", text, re.IGNORECASE))
        if not accepted:
            error = f"Smart SMS was not accepted: {text[:300]}"
            record_a2p_message_log(
                status="FAILED",
                destination=clean_destination,
                source=clean_source,
                message_text=clean_message,
                purpose=purpose,
                http_status=response.status_code,
                smart_status="NOT_ACCEPTED",
                message_id=message_id,
                response_summary=text[:500],
                error_message=error,
                request_context=request_context,
                created_by_admin_id=created_by_admin_id,
            )
            raise HTTPException(status_code=400, detail=error)
        record_a2p_message_log(
            status="SUCCESS",
            destination=clean_destination,
            source=clean_source,
            message_text=clean_message,
            purpose=purpose,
            http_status=response.status_code,
            smart_status="ACCEPTED",
            message_id=message_id,
            response_summary=text[:500],
            request_context=request_context,
            created_by_admin_id=created_by_admin_id,
        )
        return {
            "status": "SUCCESS",
            "destination": mask_a2p_destination(clean_destination),
            "message_id": message_id,
            "response_summary": text[:300],
        }
    except HTTPException as exc:
        if not str(exc.detail).startswith("Smart SMS"):
            record_a2p_message_log(
                status="FAILED",
                destination=raw_destination,
                source=clean_source or source,
                message_text=raw_message,
                purpose=purpose,
                error_message=str(exc.detail),
                request_context=request_context,
                created_by_admin_id=created_by_admin_id,
            )
        raise
    except Exception as exc:
        record_a2p_message_log(
            status="FAILED",
            destination=raw_destination,
            source=clean_source or source,
            message_text=raw_message,
            purpose=purpose,
            error_message=str(exc),
            request_context=request_context,
            created_by_admin_id=created_by_admin_id,
        )
        raise HTTPException(status_code=400, detail=f"Smart SMS send failed: {exc}")


def parse_a2p_credit_available(text: str):
    clean = normalize_a2p_text(text, 1000)
    patterns = [
        r"Available\s*[:=]?\s*([\d,]+(?:\.\d+)?)",
        r"Credits?\s*[:=]?\s*([\d,]+(?:\.\d+)?)",
        r"Balance\s*[:=]?\s*([\d,]+(?:\.\d+)?)",
    ]
    for pattern in patterns:
        match = re.search(pattern, clean, re.IGNORECASE)
        if match:
            value = match.group(1).replace(",", "")
            return float(value) if "." in value else int(value)
    if re.fullmatch(r"[\d,]+(?:\.\d+)?", clean):
        value = clean.replace(",", "")
        return float(value) if "." in value else int(value)
    return None


def extract_openai_response_text(response_data: dict) -> str:
    output_text = response_data.get("output_text")
    if isinstance(output_text, str) and output_text.strip():
        return output_text.strip()
    output = response_data.get("output")
    texts = []
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict):
                continue
            content = item.get("content")
            if isinstance(content, list):
                for part in content:
                    if not isinstance(part, dict):
                        continue
                    text = part.get("text")
                    if isinstance(text, str) and text.strip():
                        texts.append(text.strip())
    return "\n".join(texts).strip()


def openai_api_status() -> dict:
    store = openai_store()
    api_key = decrypt_secret(store.get("api_key_encrypted"))
    model_id = normalize_openai_model(store.get("selected_model"))
    return {
        "configured": bool(normalize_openai_text(api_key)),
        "model": model_id,
        "reasoning_effort": normalize_openai_reasoning_effort(model_id, store.get("reasoning_effort")),
    }


def call_openai_responses(system_prompt: str, user_payload, max_output_tokens: int = 900, user_agent: str = "3JCentralPisowifi/0.1 ai-network-assistant", text_format: Optional[dict] = None, reasoning_effort_override: Optional[str] = None) -> str:
    store = openai_store()
    api_key = decrypt_secret(store.get("api_key_encrypted"))
    if not normalize_openai_text(api_key):
        raise HTTPException(status_code=400, detail="OpenAI API key is not configured. AI features are optional; preflight and planning still work without AI.")
    model_id = normalize_openai_model(store.get("selected_model"))
    reasoning_effort = normalize_openai_reasoning_effort(model_id, reasoning_effort_override or store.get("reasoning_effort"))
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "User-Agent": user_agent,
    }
    organization_id = normalize_openai_text(store.get("organization_id"))
    project_id = normalize_openai_text(store.get("project_id"))
    if organization_id:
        headers["OpenAI-Organization"] = organization_id
    if project_id:
        headers["OpenAI-Project"] = project_id
    payload_text = user_payload if isinstance(user_payload, str) else json.dumps(json_safe(user_payload), default=str)
    body = {
        "model": model_id,
        "input": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": payload_text[:24000]},
        ],
        "max_output_tokens": max_output_tokens,
    }
    if reasoning_effort:
        body["reasoning"] = {"effort": reasoning_effort}
    if text_format:
        body["text"] = {"format": text_format}
    try:
        response = requests.post("https://api.openai.com/v1/responses", headers=headers, json=body, timeout=60)
        response_data = response.json() if response.content else {}
        if response.status_code >= 400:
            message = response_data.get("error", {}).get("message") if isinstance(response_data, dict) else None
            raise RuntimeError(message or f"OpenAI API returned HTTP {response.status_code}")
        output_text = extract_openai_response_text(response_data if isinstance(response_data, dict) else {})
        if not output_text:
            raise RuntimeError("OpenAI returned an empty response.")
        return sanitize_routeros_text(output_text, max_length=12000)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"OpenAI request failed: {exc}") from exc


def clear_site_deployment_tombstone(cur, omada_site_id: Optional[str] = None, site_name: Optional[str] = None):
    clean_site_id = str(omada_site_id or "").strip() or None
    clean_site_name = str(site_name or "").strip() or None
    if not clean_site_id and not clean_site_name:
        return
    conditions = []
    params = []
    if clean_site_id:
        conditions.append("omada_site_id = %s")
        params.append(clean_site_id)
    if clean_site_name:
        conditions.append("lower(site_name) = lower(%s)")
        params.append(clean_site_name)
    cur.execute(f"DELETE FROM site_deployment_tombstones WHERE {' OR '.join(conditions)}", tuple(params))


def record_site_deployment_tombstone(
    cur,
    omada_site_id: Optional[str],
    site_name: Optional[str],
    admin_id: Optional[str],
    omada_delete_attempted: bool,
    omada_deleted: bool,
    omada_delete_error: Optional[str],
    omada_response_summary: Optional[dict],
):
    clean_site_id = str(omada_site_id or "").strip() or None
    clean_site_name = str(site_name or "").strip() or None
    if not clean_site_id and not clean_site_name:
        return
    clear_site_deployment_tombstone(cur, clean_site_id, clean_site_name)
    cur.execute(
        """
        INSERT INTO site_deployment_tombstones(
            omada_site_id, site_name, deleted_by_admin_id, omada_delete_attempted,
            omada_deleted, omada_delete_error, omada_response_summary
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s)
        """,
        (
            clean_site_id,
            clean_site_name,
            admin_id,
            omada_delete_attempted,
            omada_deleted,
            omada_delete_error,
            Json(sanitize_summary(omada_response_summary or {})),
        ),
    )


def ensure_omada_api_settings():
    row = fetch_one("SELECT * FROM omada_api_settings ORDER BY created_at ASC LIMIT 1")
    if row:
        return row
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO omada_api_settings(controller_host, https_port, api_base_url, verify_tls)
                VALUES ('192.168.50.71', 8043, 'https://192.168.50.71:8043', false)
                RETURNING *
                """
            )
            return cur.fetchone()


def public_omada_api_settings(row=None):
    row = row or ensure_omada_api_settings()
    return {
        "id": row["id"],
        "controller_host": row["controller_host"],
        "https_port": row["https_port"],
        "api_base_url": row["api_base_url"],
        "verify_tls": row["verify_tls"],
        "username": row["username"],
        "has_password": bool(row.get("password_encrypted")),
        "selected_site_id": row["selected_site_id"],
        "selected_site_name": row["selected_site_name"],
        "last_login_success_at": row["last_login_success_at"],
        "last_login_error": row["last_login_error"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


def omada_api_client_from_settings():
    row = ensure_omada_api_settings()
    password = decrypt_secret(row.get("password_encrypted"))
    if not row.get("username") or not password:
        raise HTTPException(status_code=400, detail="Omada API username and password are required")
    return row, OmadaApiClient(
        row["api_base_url"],
        row["username"],
        password,
        verify_tls=bool(row["verify_tls"]),
        # Controller IDs change after Omada reinstall/restore. Keep this
        # transient so stale database values cannot poison later API calls.
        controller_id=None,
    )


DEFAULT_OMADA_PAYMENT_AUTH_FREE_SETTINGS = {
    "enabled": True,
    "browser_transfer_required": True,
    "grant_timeout_seconds": 120,
    "post_payment_cleanup_delay_seconds": 20,
    "daily_attempt_limit": 5,
    "cooldown_seconds": 60,
    "abuse_block_hours": 24,
    "block_online_payment_on_abuse": True,
    "notes": "Temporarily places a client MAC in Omada Authentication-Free Client only while the customer completes PayMongo checkout in Chrome/Safari.",
}


def bounded_int(value, default: int, minimum: int, maximum: int) -> int:
    try:
        return max(minimum, min(int(value), maximum))
    except (TypeError, ValueError):
        return default


def omada_payment_auth_free_store() -> dict:
    row = fetch_one("SELECT value FROM app_settings WHERE key = 'omada_payment_auth_free'")
    value = row["value"] if row and isinstance(row["value"], dict) else {}
    store = {**DEFAULT_OMADA_PAYMENT_AUTH_FREE_SETTINGS, **value}
    return {
        "enabled": bool(store.get("enabled")),
        "browser_transfer_required": bool(store.get("browser_transfer_required")),
        "grant_timeout_seconds": bounded_int(store.get("grant_timeout_seconds"), 120, 30, 900),
        "post_payment_cleanup_delay_seconds": bounded_int(store.get("post_payment_cleanup_delay_seconds"), 20, 0, 300),
        "daily_attempt_limit": bounded_int(store.get("daily_attempt_limit"), 5, 1, 100),
        "cooldown_seconds": bounded_int(store.get("cooldown_seconds"), 60, 0, 3600),
        "abuse_block_hours": bounded_int(store.get("abuse_block_hours"), 24, 1, 168),
        "block_online_payment_on_abuse": bool(store.get("block_online_payment_on_abuse")),
        "notes": normalize_payment_text(store.get("notes"), 1000) or DEFAULT_OMADA_PAYMENT_AUTH_FREE_SETTINGS["notes"],
    }


def save_omada_payment_auth_free_store(store: dict):
    clean = {
        "enabled": bool(store.get("enabled")),
        "browser_transfer_required": bool(store.get("browser_transfer_required")),
        "grant_timeout_seconds": bounded_int(store.get("grant_timeout_seconds"), 120, 30, 900),
        "post_payment_cleanup_delay_seconds": bounded_int(store.get("post_payment_cleanup_delay_seconds"), 20, 0, 300),
        "daily_attempt_limit": bounded_int(store.get("daily_attempt_limit"), 5, 1, 100),
        "cooldown_seconds": bounded_int(store.get("cooldown_seconds"), 60, 0, 3600),
        "abuse_block_hours": bounded_int(store.get("abuse_block_hours"), 24, 1, 168),
        "block_online_payment_on_abuse": bool(store.get("block_online_payment_on_abuse")),
        "notes": normalize_payment_text(store.get("notes"), 1000) or DEFAULT_OMADA_PAYMENT_AUTH_FREE_SETTINGS["notes"],
    }
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO app_settings(key, value, updated_at)
                VALUES ('omada_payment_auth_free', %s, now())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
                """,
                (Json(clean),),
            )
    return clean


def public_omada_payment_auth_free_settings() -> dict:
    store = omada_payment_auth_free_store()
    return {
        **store,
        "grant_timeout_minutes": round(store["grant_timeout_seconds"] / 60, 2),
        "post_payment_cleanup_delay_minutes": round(store["post_payment_cleanup_delay_seconds"] / 60, 2),
        "cooldown_minutes": round(store["cooldown_seconds"] / 60, 2),
    }


def omada_payment_auth_free_public_grant(row: Optional[dict]) -> Optional[dict]:
    if not row:
        return None
    expires_at = aware_utc(row.get("expires_at"))
    now = datetime.now(timezone.utc)
    remaining_seconds = max(int((expires_at - now).total_seconds()), 0) if expires_at else 0
    return {
        "id": str(row["id"]),
        "public_grant_id": row.get("public_grant_id"),
        "payment_order_id": str(row["payment_order_id"]) if row.get("payment_order_id") else None,
        "portal_session_id": str(row["portal_session_id"]) if row.get("portal_session_id") else None,
        "user_id": str(row["user_id"]) if row.get("user_id") else None,
        "site_id": row.get("site_id"),
        "site_name": row.get("site_name"),
        "client_mac": row.get("client_mac"),
        "client_ip": str(row["client_ip"]) if row.get("client_ip") else None,
        "profile_name": row.get("profile_name"),
        "profile_contact_number": row.get("profile_contact_number"),
        "status": row.get("status"),
        "reason": row.get("reason"),
        "remaining_seconds": remaining_seconds,
        "granted_at": row.get("granted_at"),
        "expires_at": row.get("expires_at"),
        "removed_at": row.get("removed_at"),
        "last_error": row.get("last_error"),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def omada_payment_auth_free_attempts_today_for_row(cur, row: Optional[dict]) -> int:
    if not row:
        return 0
    clauses = []
    params = []
    if row.get("user_id"):
        clauses.append("g.user_id = %s")
        params.append(row["user_id"])
    if row.get("client_mac"):
        clauses.append("g.client_mac = %s")
        params.append(row["client_mac"])
    if row.get("device_token_hash"):
        clauses.append("g.device_token_hash = %s")
        params.append(row["device_token_hash"])
    if row.get("profile_contact_number"):
        clauses.append("g.profile_contact_number = %s")
        params.append(row["profile_contact_number"])
    if not clauses:
        return 0
    cur.execute(
        f"""
        SELECT count(*)::int AS attempts
        FROM omada_payment_auth_free_grants g
        LEFT JOIN payment_orders po ON po.id = g.payment_order_id
        WHERE g.created_at >= date_trunc('day', now())
          AND ({" OR ".join(clauses)})
          AND (po.id IS NULL OR NOT (po.status = 'PAID' AND po.fulfillment_status = 'FULFILLED'))
        """,
        tuple(params),
    )
    return int((cur.fetchone() or {}).get("attempts") or 0)


def omada_payment_auth_free_public_grants_with_attempts(cur, rows: list[dict], settings: dict) -> list[dict]:
    limit = max(1, int((settings or {}).get("daily_attempt_limit") or 5))
    warning_threshold = max(1, limit - 2)
    public_rows = []
    for row in rows:
        public = omada_payment_auth_free_public_grant(row)
        if not public:
            continue
        attempts_today = omada_payment_auth_free_attempts_today_for_row(cur, row)
        remaining_attempts = max(limit - attempts_today, 0)
        public.update(
            {
                "attempts_today": attempts_today,
                "daily_attempt_limit": limit,
                "remaining_attempts": remaining_attempts,
                "attempt_warning": attempts_today >= warning_threshold,
                "attempt_warning_level": (
                    "LIMIT_REACHED"
                    if attempts_today >= limit
                    else "LAST_CHANCE"
                    if remaining_attempts <= 1
                    else "WARNING"
                    if attempts_today >= warning_threshold
                    else "NONE"
                ),
            }
        )
        public_rows.append(public)
    return public_rows


def omada_payment_auth_free_site_rows(cur) -> list[dict]:
    cur.execute(
        """
        SELECT DISTINCT site_id, site_name
        FROM (
            SELECT omada_site_id AS site_id, site_name
            FROM site_deployments
            WHERE omada_site_id IS NOT NULL
              AND omada_site_id <> ''
              AND COALESCE(deployment_status, '') <> 'DELETED'
            UNION ALL
            SELECT site_id, site_name
            FROM omada_payment_auth_free_grants
            WHERE site_id IS NOT NULL
              AND site_id <> ''
            UNION ALL
            SELECT selected_omada_site_id AS site_id, selected_omada_site_name AS site_name
            FROM captive_portal_settings
            WHERE selected_omada_site_id IS NOT NULL
              AND selected_omada_site_id <> ''
        ) sites
        WHERE site_id IS NOT NULL
          AND site_id <> ''
        ORDER BY site_name NULLS LAST, site_id
        """
    )
    return cur.fetchall()


def omada_payment_auth_free_remote_snapshot(cur, active_grants: list[dict]) -> dict:
    site_rows = omada_payment_auth_free_site_rows(cur)
    active_by_mac = {}
    active_by_ip = {}
    for row in active_grants:
        site_id = row.get("site_id")
        mac = normalize_mac_if_valid(row.get("client_mac"))
        client_ip = str(row.get("client_ip") or "").strip()
        if site_id and mac:
            active_by_mac[(site_id, mac)] = row
        if site_id and client_ip:
            active_by_ip[(site_id, client_ip)] = row

    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        WHERE site_id IS NOT NULL AND site_id <> ''
        ORDER BY updated_at DESC NULLS LAST, created_at DESC
        LIMIT 500
        """
    )
    history_by_mac = {}
    history_by_ip = {}
    for row in cur.fetchall():
        public = omada_payment_auth_free_public_grant(row)
        if not public:
            continue
        site_id = public.get("site_id")
        mac = normalize_mac_if_valid(public.get("client_mac"))
        client_ip = str(public.get("client_ip") or "").strip()
        if site_id and mac and (site_id, mac) not in history_by_mac:
            history_by_mac[(site_id, mac)] = public
        if site_id and client_ip and (site_id, client_ip) not in history_by_ip:
            history_by_ip[(site_id, client_ip)] = public

    remote_clients = []
    errors = []
    try:
        _, client = omada_api_client_from_settings()
    except Exception as exc:
        return {
            "remote_clients": [],
            "orphaned_remote_clients": [],
            "remote_errors": [{"message": normalize_payment_text(str(exc), 1000)}],
        }

    for site in site_rows:
        site_id = site.get("site_id")
        if not site_id:
            continue
        site_name = site.get("site_name") or site_id
        try:
            data = client.get_access_control(site_id)
            access = data.get("access_control") or {}
            policies = access.get("freeAuthClientPolicies") or []
            enabled = bool(access.get("freeAuthClientEnable"))
            if not isinstance(policies, list):
                policies = []
            for index, policy in enumerate(policies):
                if not isinstance(policy, dict):
                    continue
                policy_type = int(policy.get("type") or 0)
                client_mac = normalize_mac_if_valid(policy.get("clientMac")) if policy_type == 4 else None
                client_ip = str(policy.get("clientIp") or "").strip() if policy_type == 3 else None
                if not client_mac and not client_ip:
                    continue
                local_match = None
                if client_mac:
                    local_match = active_by_mac.get((site_id, client_mac)) or history_by_mac.get((site_id, client_mac))
                if not local_match and client_ip:
                    local_match = active_by_ip.get((site_id, client_ip)) or history_by_ip.get((site_id, client_ip))
                locally_active = bool(
                    (client_mac and (site_id, client_mac) in active_by_mac)
                    or (client_ip and (site_id, client_ip) in active_by_ip)
                )
                status = "REMOTE_ACTIVE" if locally_active else "ORPHANED_IN_OMADA"
                remote_clients.append(
                    {
                        "id": f"omada:{site_id}:{client_mac or client_ip or index}",
                        "source": "OMADA_LIVE",
                        "orphaned": not locally_active,
                        "site_id": site_id,
                        "site_name": site_name,
                        "client_mac": client_mac,
                        "client_ip": client_ip,
                        "profile_name": (local_match or {}).get("profile_name"),
                        "profile_contact_number": (local_match or {}).get("profile_contact_number"),
                        "status": status,
                        "remote_enabled": enabled,
                        "remote_policy_type": policy_type,
                        "remote_policy_id": policy.get("id") or policy.get("idInt"),
                        "remaining_seconds": (local_match or {}).get("remaining_seconds") if locally_active else None,
                        "expires_at": (local_match or {}).get("expires_at") if locally_active else None,
                        "last_error": None if locally_active else "Exists in Omada Authentication-Free Client but no active local grant exists.",
                    }
                )
        except Exception as exc:
            errors.append(
                {
                    "site_id": site_id,
                    "site_name": site_name,
                    "message": normalize_payment_text(str(exc), 1000),
                }
            )

    return {
        "remote_clients": remote_clients,
        "orphaned_remote_clients": [row for row in remote_clients if row.get("orphaned")],
        "remote_errors": errors,
    }


def omada_payment_auth_free_identity(session: dict, user: Optional[dict] = None, profile: Optional[dict] = None, payload: Optional[PortalSessionRequest] = None, request: Optional[Request] = None) -> dict:
    ctx = portal_context(payload) if payload else {}
    client_mac = (
        normalize_mac_if_valid(portal_effective_mac_from_session(session))
        or normalize_mac_if_valid(ctx.get("client_mac"))
    )
    client_ip = host_ip(session.get("client_ip") or ctx.get("client_ip") or (public_ip(request) if request else None))
    device_token_hash = session.get("device_token_hash") or (portal_device_token_hash(payload.device_token) if payload else None)
    return {
        "user_id": (user or {}).get("id") or session.get("user_id"),
        "portal_session_id": session.get("id"),
        "client_mac": client_mac,
        "client_ip": client_ip,
        "device_token_hash": device_token_hash,
        "profile_name": normalize_payment_text((profile or {}).get("display_name") or (user or {}).get("full_name"), 120) or None,
        "profile_contact_number": normalize_payment_text((profile or {}).get("contact_number") or (user or {}).get("phone_number"), 32) or None,
    }


def omada_payment_auth_free_snapshot_matches_site(snapshot: Optional[dict], site_id: Optional[str], site_name: Optional[str]) -> bool:
    if not snapshot:
        return False
    target_site_id = normalize_payment_text(site_id, 120)
    target_site_name = normalize_payment_text(site_name, 160).lower()
    snapshot_site_id = normalize_payment_text(snapshot.get("site_id"), 120)
    snapshot_site_name = normalize_payment_text(snapshot.get("site"), 160).lower()
    if target_site_id and snapshot_site_id:
        return target_site_id == snapshot_site_id
    if target_site_name and snapshot_site_name:
        return target_site_name == snapshot_site_name
    return not target_site_id and not target_site_name


def omada_payment_auth_free_recent_user_macs(cur, user_id, site_id: Optional[str], site_name: Optional[str]) -> list[str]:
    if not user_id:
        return []
    cur.execute(
        """
        SELECT omada_client_mac, mikrotik_client_mac, client_mac, previous_client_macs,
               omada_site_id, omada_site_name, site
        FROM portal_sessions
        WHERE user_id = %s
          AND updated_at > now() - interval '45 days'
          AND (
            omada_client_mac IS NOT NULL
            OR mikrotik_client_mac IS NOT NULL
            OR client_mac IS NOT NULL
            OR previous_client_macs <> '[]'::jsonb
          )
        ORDER BY updated_at DESC
        LIMIT 100
        """,
        (user_id,),
    )
    target_site_id = normalize_payment_text(site_id, 120)
    target_site_name = normalize_payment_text(site_name, 160).lower()
    macs = []
    for row in cur.fetchall():
        row_site_id = normalize_payment_text(row.get("omada_site_id"), 120)
        row_site_name = normalize_payment_text(row.get("omada_site_name") or row.get("site"), 160).lower()
        if target_site_id and row_site_id and target_site_id != row_site_id:
            continue
        if target_site_name and row_site_name and target_site_name != row_site_name:
            continue
        for mac in portal_device_mac_values(
            row.get("omada_client_mac"),
            row.get("mikrotik_client_mac"),
            row.get("client_mac"),
            row.get("previous_client_macs") or [],
        ):
            if mac not in macs:
                macs.append(mac)
    return macs


def omada_payment_auth_free_live_sort_key(snapshot: dict) -> tuple:
    age = omada_last_seen_age_seconds((snapshot or {}).get("last_seen"))
    return (age is None, age if age is not None else 10**12)


def resolve_omada_payment_auth_free_identity(cur, session: dict, user: dict, profile: Optional[dict], payload: PortalPaymentCheckoutRequest, request: Request, site_id: Optional[str], site_name: Optional[str], identity: dict) -> tuple[dict, dict]:
    resolved = dict(identity or {})
    resolution = {
        "source": "portal_session",
        "selected_reason": "session_identity",
        "original_client_mac": resolved.get("client_mac"),
        "original_client_ip": resolved.get("client_ip"),
        "candidate_macs": [],
    }
    if not site_id:
        resolution["selected_reason"] = "missing_site"
        return resolved, resolution

    candidate_macs = []
    for mac in portal_device_mac_values(
        resolved.get("client_mac"),
        session.get("omada_client_mac"),
        session.get("mikrotik_client_mac"),
        session.get("client_mac"),
        session.get("previous_client_macs") or [],
    ):
        if mac not in candidate_macs:
            candidate_macs.append(mac)
    for mac in omada_payment_auth_free_recent_user_macs(cur, resolved.get("user_id") or (user or {}).get("id"), site_id, site_name):
        if mac not in candidate_macs:
            candidate_macs.append(mac)
    resolution["candidate_macs"] = candidate_macs[:20]

    try:
        snapshots = fetch_omada_client_snapshot_map(force=True)
    except Exception as exc:
        resolution["selected_reason"] = "omada_snapshot_unavailable"
        resolution["snapshot_error"] = normalize_payment_text(str(exc), 240)
        return resolved, resolution
    if not snapshots:
        resolution["selected_reason"] = "omada_snapshot_empty"
        return resolved, resolution

    def snapshot_is_usable(snapshot: Optional[dict]) -> bool:
        return bool(
            snapshot
            and snapshot.get("active")
            and omada_payment_auth_free_snapshot_matches_site(snapshot, site_id, site_name)
        )

    original_mac = normalize_mac_if_valid(resolved.get("client_mac"))
    original_snapshot = snapshots.get(original_mac) if original_mac else None
    selected_mac = None
    selected_snapshot = None
    selected_reason = None

    if snapshot_is_usable(original_snapshot):
        selected_mac = original_mac
        selected_snapshot = original_snapshot
        selected_reason = "session_mac_live"
    else:
        known_live = [
            (mac, snapshots.get(mac))
            for mac in candidate_macs
            if snapshot_is_usable(snapshots.get(mac))
        ]
        if known_live:
            selected_mac, selected_snapshot = sorted(known_live, key=lambda item: omada_payment_auth_free_live_sort_key(item[1]))[0]
            selected_reason = "linked_mac_live"
        else:
            seed_name_keys = {
                omada_device_name_key((snapshots.get(mac) or {}).get("device_name") or (snapshots.get(mac) or {}).get("hostname"))
                for mac in candidate_macs
            }
            seed_name_keys.discard("")
            named_live = [
                (mac, snapshot)
                for mac, snapshot in snapshots.items()
                if snapshot_is_usable(snapshot)
                and omada_device_name_key(snapshot.get("device_name") or snapshot.get("hostname")) in seed_name_keys
            ]
            if len(named_live) == 1:
                selected_mac, selected_snapshot = named_live[0]
                selected_reason = "same_omada_device_name_live"
            elif len(named_live) > 1:
                resolution["ambiguous_live_same_name_count"] = len(named_live)

    if selected_mac and selected_snapshot:
        resolved["client_mac"] = selected_mac
        live_ip = host_ip(selected_snapshot.get("client_ip"))
        if live_ip:
            resolved["client_ip"] = live_ip
        resolution.update({
            "source": "omada_live_client",
            "selected_reason": selected_reason,
            "selected_client_mac": selected_mac,
            "selected_client_ip": resolved.get("client_ip"),
            "selected_device_name": selected_snapshot.get("device_name") or selected_snapshot.get("hostname"),
            "selected_ssid": selected_snapshot.get("ssid"),
            "selected_site_id": selected_snapshot.get("site_id"),
            "selected_site": selected_snapshot.get("site"),
            "selected_last_seen": selected_snapshot.get("last_seen"),
            "original_client_active": bool((original_snapshot or {}).get("active")),
        })
    elif original_snapshot is not None:
        resolution["selected_reason"] = "session_mac_not_live"
        resolution["original_client_active"] = bool(original_snapshot.get("active"))

    return resolved, resolution


def record_omada_payment_auth_free_abuse_block(identity: dict, attempts_today: int, block_until: datetime) -> None:
    try:
        with get_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO omada_payment_auth_free_abuse_blocks(
                        user_id, portal_session_id, client_mac, device_token_hash, profile_name,
                        profile_contact_number, attempts_today, reason, block_until
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, 'DAILY_LIMIT', %s)
                    """,
                    (
                        identity.get("user_id"),
                        identity.get("portal_session_id"),
                        identity.get("client_mac"),
                        identity.get("device_token_hash"),
                        identity.get("profile_name"),
                        identity.get("profile_contact_number"),
                        attempts_today,
                        block_until,
                    ),
                )
    except Exception as exc:
        print(f"[omada-payment-auth-free] failed to record abuse block: {exc}")


def omada_payment_auth_free_abuse_identity(data: Optional[dict]) -> dict:
    data = data or {}
    return {
        "user_id": normalize_payment_text(data.get("user_id"), 80) or None,
        "client_mac": normalize_mac_if_valid(data.get("client_mac")) or normalize_payment_text(data.get("client_mac"), 64) or None,
        "device_token_hash": normalize_payment_text(data.get("device_token_hash"), 160) or None,
        "profile_contact_number": normalize_payment_text(data.get("profile_contact_number"), 40) or None,
        "profile_name": normalize_payment_text(data.get("profile_name"), 180) or None,
    }


def omada_payment_auth_free_abuse_identity_matches(left: dict, right: dict) -> bool:
    if not left or not right:
        return False
    for key in ("user_id", "client_mac", "device_token_hash", "profile_contact_number"):
        left_value = normalize_payment_text(left.get(key), 180)
        right_value = normalize_payment_text(right.get(key), 180)
        if left_value and right_value and left_value == right_value:
            return True
    return False


def omada_payment_auth_free_abuse_override_store() -> list[dict]:
    row = fetch_one("SELECT value FROM app_settings WHERE key = 'omada_payment_auth_free_abuse_overrides'")
    value = row["value"] if row and isinstance(row["value"], dict) else {}
    raw_items = value.get("items") if isinstance(value.get("items"), list) else []
    now = datetime.now(timezone.utc)
    items = []
    for item in raw_items:
        if not isinstance(item, dict):
            continue
        ignore_until = aware_utc(item.get("ignore_until"))
        if not ignore_until or ignore_until <= now:
            continue
        identity = omada_payment_auth_free_abuse_identity(item)
        if not any(identity.get(key) for key in ("user_id", "client_mac", "device_token_hash", "profile_contact_number")):
            continue
        items.append({**identity, "ignore_until": ignore_until, "removed_by_admin_id": item.get("removed_by_admin_id"), "removed_at": item.get("removed_at")})
    return items


def save_omada_payment_auth_free_abuse_overrides(items: list[dict]):
    clean_items = []
    for item in items:
        identity = omada_payment_auth_free_abuse_identity(item)
        if not any(identity.get(key) for key in ("user_id", "client_mac", "device_token_hash", "profile_contact_number")):
            continue
        clean_items.append({
            **identity,
            "ignore_until": item.get("ignore_until").isoformat() if hasattr(item.get("ignore_until"), "isoformat") else item.get("ignore_until"),
            "removed_by_admin_id": str(item.get("removed_by_admin_id")) if item.get("removed_by_admin_id") else None,
            "removed_at": item.get("removed_at").isoformat() if hasattr(item.get("removed_at"), "isoformat") else item.get("removed_at"),
        })
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO app_settings(key, value, updated_at)
                VALUES ('omada_payment_auth_free_abuse_overrides', %s, now())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
                """,
                (Json({"items": clean_items}),),
            )


def add_omada_payment_auth_free_abuse_override(identity: dict, admin_id) -> dict:
    clean_identity = omada_payment_auth_free_abuse_identity(identity)
    if not any(clean_identity.get(key) for key in ("user_id", "client_mac", "device_token_hash", "profile_contact_number")):
        raise HTTPException(status_code=400, detail="Customer, MAC, device token, or contact number is required.")
    now = datetime.now(timezone.utc)
    ignore_until = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    items = [
        item for item in omada_payment_auth_free_abuse_override_store()
        if not omada_payment_auth_free_abuse_identity_matches(clean_identity, item)
    ]
    override = {
        **clean_identity,
        "ignore_until": ignore_until.isoformat(),
        "removed_by_admin_id": str(admin_id) if admin_id else None,
        "removed_at": now.isoformat(),
    }
    items.append(override)
    save_omada_payment_auth_free_abuse_overrides(items)
    return override


def omada_payment_auth_free_abuse_is_overridden(identity: dict, overrides: Optional[list[dict]] = None) -> bool:
    active_overrides = overrides if overrides is not None else omada_payment_auth_free_abuse_override_store()
    return any(omada_payment_auth_free_abuse_identity_matches(identity, override) for override in active_overrides)


def omada_payment_auth_free_abuse_status(cur, session: dict, user: dict, profile: Optional[dict], payload: PortalSessionRequest, request: Request, record_limit_block: bool = False) -> dict:
    store = omada_payment_auth_free_store()
    if not store.get("enabled") or not store.get("block_online_payment_on_abuse"):
        return {
            "status": "OK",
            "enabled": bool(store.get("enabled")),
            "attempts_today": 0,
            "limit": store["daily_attempt_limit"],
            "remaining_attempts": store["daily_attempt_limit"],
            "warning": False,
        }
    identity = omada_payment_auth_free_identity(session, user, profile, payload, request)
    if omada_payment_auth_free_abuse_is_overridden(identity):
        return {
            "status": "OK",
            "enabled": True,
            "attempts_today": 0,
            "limit": store["daily_attempt_limit"],
            "remaining_attempts": store["daily_attempt_limit"],
            "warning": False,
            "admin_override": True,
        }
    clauses = []
    grant_clauses = []
    params = []
    if identity.get("user_id"):
        clauses.append("user_id = %s")
        grant_clauses.append("g.user_id = %s")
        params.append(identity["user_id"])
    if identity.get("client_mac"):
        clauses.append("client_mac = %s")
        grant_clauses.append("g.client_mac = %s")
        params.append(identity["client_mac"])
    if identity.get("device_token_hash"):
        clauses.append("device_token_hash = %s")
        grant_clauses.append("g.device_token_hash = %s")
        params.append(identity["device_token_hash"])
    if not clauses:
        return {
            "status": "OK",
            "enabled": True,
            "attempts_today": 0,
            "limit": store["daily_attempt_limit"],
            "remaining_attempts": store["daily_attempt_limit"],
            "warning": False,
        }
    where_clause = " OR ".join(clauses)
    grant_where_clause = " OR ".join(grant_clauses)
    unpaid_grant_clause = "(po.id IS NULL OR NOT (po.status = 'PAID' AND po.fulfillment_status = 'FULFILLED'))"
    cur.execute(
        f"""
        SELECT *
        FROM omada_payment_auth_free_abuse_blocks
        WHERE block_until > now()
          AND ({where_clause})
        ORDER BY block_until DESC
        LIMIT 1
        """,
        tuple(params),
    )
    active_block = cur.fetchone()
    if active_block:
        return {
            "status": "BLOCKED",
            "enabled": True,
            "attempts_today": int(active_block.get("attempts_today") or store["daily_attempt_limit"]),
            "limit": store["daily_attempt_limit"],
            "remaining_attempts": 0,
            "warning": False,
            "block_until": active_block.get("block_until"),
            "message": "Online payment is temporarily blocked for this device/profile because too many checkout windows were started today. You can try again tomorrow or buy in a physical store.",
        }
    if store["cooldown_seconds"] > 0:
        cur.execute(
            f"""
            SELECT g.created_at
            FROM omada_payment_auth_free_grants g
            LEFT JOIN payment_orders po ON po.id = g.payment_order_id
            WHERE ({grant_where_clause})
              AND {unpaid_grant_clause}
            ORDER BY g.created_at DESC
            LIMIT 1
            """,
            tuple(params),
        )
        last_attempt = cur.fetchone()
        last_created = aware_utc((last_attempt or {}).get("created_at"))
        if last_created and (datetime.now(timezone.utc) - last_created).total_seconds() < store["cooldown_seconds"]:
            remaining = max(int(store["cooldown_seconds"] - (datetime.now(timezone.utc) - last_created).total_seconds()), 1)
            return {
                "status": "COOLDOWN",
                "enabled": True,
                "attempts_today": 0,
                "limit": store["daily_attempt_limit"],
                "remaining_attempts": store["daily_attempt_limit"],
                "warning": False,
                "cooldown_remaining_seconds": remaining,
                "message": f"Please wait {remaining} seconds before starting another online payment checkout.",
            }
    cur.execute(
        f"""
        SELECT count(*)::int AS attempts
        FROM omada_payment_auth_free_grants g
        LEFT JOIN payment_orders po ON po.id = g.payment_order_id
        WHERE g.created_at >= date_trunc('day', now())
          AND ({grant_where_clause})
          AND {unpaid_grant_clause}
        """,
        tuple(params),
    )
    attempts_today = int((cur.fetchone() or {}).get("attempts") or 0)
    if attempts_today < store["daily_attempt_limit"]:
        remaining_attempts = max(store["daily_attempt_limit"] - attempts_today, 0)
        warning_threshold = max(1, store["daily_attempt_limit"] - 2)
        warning = attempts_today >= warning_threshold
        return {
            "status": "OK",
            "enabled": True,
            "attempts_today": attempts_today,
            "limit": store["daily_attempt_limit"],
            "remaining_attempts": remaining_attempts,
            "warning": warning,
            "warning_level": "LAST_CHANCE" if warning and remaining_attempts <= 1 else ("WARNING" if warning else "NONE"),
            "message": None,
        }
    block_until = datetime.now(timezone.utc) + timedelta(hours=store["abuse_block_hours"])
    if record_limit_block:
        record_omada_payment_auth_free_abuse_block(identity, attempts_today, block_until)
    return {
        "status": "BLOCKED",
        "enabled": True,
        "attempts_today": attempts_today,
        "limit": store["daily_attempt_limit"],
        "remaining_attempts": 0,
        "warning": False,
        "block_until": block_until,
        "message": "Online payment is temporarily blocked for this device/profile because too many checkout windows were started today. You can try again tomorrow or buy in a physical store.",
    }


def enforce_omada_payment_auth_free_abuse_limit(cur, session: dict, user: dict, profile: Optional[dict], payload: PortalSessionRequest, request: Request) -> dict:
    status = omada_payment_auth_free_abuse_status(cur, session, user, profile, payload, request, record_limit_block=True)
    if status.get("status") == "COOLDOWN":
        raise HTTPException(
            status_code=429,
            detail=status.get("message") or "Please wait before starting another online payment checkout.",
        )
    if status.get("status") == "BLOCKED":
        raise HTTPException(
            status_code=429,
            detail=status.get("message") or "Online payment access is temporarily blocked for this device/profile because too many checkout windows were started today. Try again later or ask the operator.",
        )
    return status


def create_omada_payment_auth_free_grant(cur, order: dict, session: dict, user: dict, profile: Optional[dict], payload: PortalPaymentCheckoutRequest, request: Request) -> Optional[dict]:
    store = omada_payment_auth_free_store()
    if not store.get("enabled"):
        return None
    cleanup_expired_omada_payment_auth_free_grants(cur, limit=20)
    identity = omada_payment_auth_free_identity(session, user, profile, payload, request)
    site_row = site_deployment_for_portal_context(session, payload)
    site_id = (
        normalize_payment_text(session.get("omada_site_id"), 120)
        or normalize_payment_text((site_row or {}).get("omada_site_id"), 120)
    )
    site_name = (
        normalize_payment_text(session.get("omada_site_name") or session.get("site"), 160)
        or normalize_payment_text((site_row or {}).get("site_name"), 160)
    )
    identity, identity_resolution = resolve_omada_payment_auth_free_identity(
        cur,
        session,
        user,
        profile,
        payload,
        request,
        site_id,
        site_name,
        identity,
    )
    expires_at = datetime.now(timezone.utc) + timedelta(seconds=store["grant_timeout_seconds"])
    public_grant_id = f"og_{secrets.token_urlsafe(16).replace('-', '').replace('_', '')[:24]}"
    status = "PENDING"
    last_error = None
    if not site_id:
        status = "GRANT_SKIPPED"
        last_error = "Omada site could not be detected for this checkout."
    elif not identity.get("client_mac") and not identity.get("client_ip"):
        status = "GRANT_SKIPPED"
        last_error = "Client MAC or IP could not be detected for this checkout."
    cur.execute(
        """
        INSERT INTO omada_payment_auth_free_grants(
            public_grant_id, payment_order_id, portal_session_id, user_id, site_id, site_name,
            client_mac, client_ip, device_token_hash, profile_name, profile_contact_number,
            status, reason, expires_at, last_error
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, NULLIF(%s, '')::inet, %s, %s, %s, %s, 'PAYMONGO_CHECKOUT', %s, %s)
        RETURNING *
        """,
        (
            public_grant_id,
            order.get("id"),
            session.get("id"),
            identity.get("user_id"),
            site_id,
            site_name,
            identity.get("client_mac"),
            identity.get("client_ip") or "",
            identity.get("device_token_hash"),
            identity.get("profile_name"),
            identity.get("profile_contact_number"),
            status,
            expires_at,
            last_error,
        ),
    )
    grant = cur.fetchone()
    if status != "PENDING":
        return grant
    try:
        _, client = omada_api_client_from_settings()
        result = client.grant_auth_free_client(site_id, client_mac=identity.get("client_mac"), client_ip=identity.get("client_ip"))
        cur.execute(
            """
            UPDATE omada_payment_auth_free_grants
            SET status = 'ACTIVE',
                granted_at = now(),
                omada_request_summary = %s,
                omada_response_summary = %s,
                last_error = NULL,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (
                Json({
                    "site_id": site_id,
                    "client_mac": identity.get("client_mac"),
                    "client_ip": identity.get("client_ip"),
                    "identity_resolution": identity_resolution,
                }),
                Json(sanitize_summary(result)),
                grant["id"],
            ),
        )
        grant = cur.fetchone()
    except Exception as exc:
        cur.execute(
            """
            UPDATE omada_payment_auth_free_grants
            SET status = 'FAILED',
                last_error = %s,
                omada_request_summary = %s,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (
                normalize_payment_text(str(exc), 1000),
                Json({
                    "site_id": site_id,
                    "client_mac": identity.get("client_mac"),
                    "client_ip": identity.get("client_ip"),
                    "identity_resolution": identity_resolution,
                }),
                grant["id"],
            ),
        )
        grant = cur.fetchone()
    return grant


def remove_omada_payment_auth_free_grant(cur, grant: dict, final_status: str = "REMOVED") -> dict:
    if not grant or grant.get("status") not in {"ACTIVE", "PAID_GRACE", "PENDING", "FAILED", "REMOVE_FAILED"}:
        return grant
    if grant.get("status") not in {"ACTIVE", "PAID_GRACE"}:
        cur.execute(
            """
            UPDATE omada_payment_auth_free_grants
            SET status = %s,
                removed_at = now(),
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (final_status, grant["id"]),
        )
        return cur.fetchone()
    try:
        _, client = omada_api_client_from_settings()
        result = client.remove_auth_free_client(grant.get("site_id"), client_mac=grant.get("client_mac"), client_ip=str(grant.get("client_ip") or ""))
        cur.execute(
            """
            UPDATE omada_payment_auth_free_grants
            SET status = %s,
                removed_at = now(),
                removal_response_summary = %s,
                last_error = NULL,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (final_status, Json(sanitize_summary(result)), grant["id"]),
        )
        return cur.fetchone()
    except Exception as exc:
        cur.execute(
            """
            UPDATE omada_payment_auth_free_grants
            SET status = 'REMOVE_FAILED',
                last_error = %s,
                updated_at = now()
            WHERE id = %s
            RETURNING *
            """,
            (normalize_payment_text(str(exc), 1000), grant["id"]),
        )
        return cur.fetchone()


def cleanup_expired_omada_payment_auth_free_grants(cur, limit: int = 50) -> list[dict]:
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        WHERE status IN ('ACTIVE', 'PAID_GRACE')
          AND expires_at <= now()
        ORDER BY expires_at ASC
        LIMIT %s
        FOR UPDATE SKIP LOCKED
        """,
        (max(1, min(int(limit or 50), 200)),),
    )
    rows = cur.fetchall()
    cleaned = []
    for row in rows:
        cleaned.append(remove_omada_payment_auth_free_grant(cur, row, final_status="REMOVED" if row.get("status") == "PAID_GRACE" else "EXPIRED"))
    return cleaned


def schedule_omada_payment_auth_free_paid_cleanup_for_order(cur, order: dict, reason: str = "PAYMENT_FULFILLED") -> list[dict]:
    if not order or not order.get("id"):
        return []
    store = omada_payment_auth_free_store()
    delay_seconds = max(0, int(store.get("post_payment_cleanup_delay_seconds") or 0))
    if delay_seconds <= 0:
        return finalize_omada_payment_auth_free_grants_for_order(cur, order, final_status="REMOVED")
    grace_until = datetime.now(timezone.utc) + timedelta(seconds=delay_seconds)
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        WHERE payment_order_id = %s
          AND status IN ('PENDING', 'ACTIVE', 'PAID_GRACE', 'FAILED', 'REMOVE_FAILED', 'GRANT_SKIPPED')
        ORDER BY created_at DESC
        FOR UPDATE
        """,
        (order["id"],),
    )
    rows = cur.fetchall()
    scheduled = []
    for row in rows:
        if row.get("status") in {"ACTIVE", "PAID_GRACE", "REMOVE_FAILED"}:
            cur.execute(
                """
                UPDATE omada_payment_auth_free_grants
                SET status = 'PAID_GRACE',
                    expires_at = %s,
                    last_error = NULL,
                    removal_response_summary = COALESCE(removal_response_summary, '{}'::jsonb) || %s::jsonb,
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (
                    grace_until,
                    json.dumps({
                        "paid_cleanup": {
                            "reason": reason,
                            "delay_seconds": delay_seconds,
                            "grace_until": grace_until.isoformat(),
                        }
                    }),
                    row["id"],
                ),
            )
            scheduled.append(cur.fetchone())
        elif row.get("status") == "GRANT_SKIPPED":
            cur.execute(
                """
                UPDATE omada_payment_auth_free_grants
                SET status = 'REMOVED',
                    removed_at = now(),
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (row["id"],),
            )
            scheduled.append(cur.fetchone())
        else:
            scheduled.append(remove_omada_payment_auth_free_grant(cur, row, final_status="REMOVED"))
    return scheduled


def remove_paid_omada_payment_auth_free_grants_for_session(cur, session: Optional[dict], request: Request = None, reason: str = "PORTAL_RETURNED") -> list[dict]:
    if not session or not session.get("id"):
        return []
    cur.execute(
        """
        SELECT g.*
        FROM omada_payment_auth_free_grants g
        JOIN payment_orders po ON po.id = g.payment_order_id
        WHERE g.portal_session_id = %s
          AND g.status IN ('ACTIVE', 'PAID_GRACE', 'REMOVE_FAILED')
          AND po.status = 'PAID'
          AND po.fulfillment_status = 'FULFILLED'
        ORDER BY g.created_at DESC
        FOR UPDATE OF g SKIP LOCKED
        """,
        (session["id"],),
    )
    rows = cur.fetchall()
    removed = []
    for row in rows:
        removed.append(remove_omada_payment_auth_free_grant(cur, row, final_status="REMOVED"))
    if removed:
        create_portal_event(
            cur,
            session["id"],
            "PAYMENT_ACCESS_GRACE_CLEARED",
            request or InternalRequestContext("3J payment access cleanup"),
            "Payment access grace removed because the paid customer returned to the portal.",
            raw_context={"reason": reason, "removed": sanitize_summary(removed)},
        )
    return removed


def finalize_omada_payment_auth_free_grants_for_order(cur, order: dict, final_status: str = "REMOVED") -> list[dict]:
    if not order or not order.get("id"):
        return []
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        WHERE payment_order_id = %s
          AND status IN ('PENDING', 'ACTIVE', 'PAID_GRACE', 'FAILED', 'REMOVE_FAILED', 'GRANT_SKIPPED')
        ORDER BY created_at DESC
        FOR UPDATE
        """,
        (order["id"],),
    )
    rows = cur.fetchall()
    finalized = []
    for row in rows:
        if row.get("status") == "GRANT_SKIPPED":
            cur.execute(
                """
                UPDATE omada_payment_auth_free_grants
                SET status = %s,
                    removed_at = now(),
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (final_status, row["id"]),
            )
            finalized.append(cur.fetchone())
        else:
            finalized.append(remove_omada_payment_auth_free_grant(cur, row, final_status=final_status))
    return finalized


def omada_payment_auth_free_dashboard_payload(cur) -> dict:
    cleanup_expired_omada_payment_auth_free_grants(cur, limit=50)
    settings = public_omada_payment_auth_free_settings()
    abuse_overrides = omada_payment_auth_free_abuse_override_store()
    cur.execute(
        """
        SELECT
          count(*) FILTER (WHERE status IN ('ACTIVE', 'PAID_GRACE') AND expires_at > now())::int AS active_count,
          count(*) FILTER (WHERE created_at >= date_trunc('day', now()))::int AS grants_today,
          count(*) FILTER (WHERE status IN ('FAILED', 'REMOVE_FAILED'))::int AS failed_count,
          count(*) FILTER (WHERE status = 'GRANT_SKIPPED')::int AS skipped_count
        FROM omada_payment_auth_free_grants
        """
    )
    overview = cur.fetchone() or {}
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        WHERE status IN ('ACTIVE', 'PAID_GRACE') AND expires_at > now()
        ORDER BY expires_at ASC
        LIMIT 100
        """
    )
    active_grants = omada_payment_auth_free_public_grants_with_attempts(cur, cur.fetchall(), settings)
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_grants
        ORDER BY created_at DESC
        LIMIT 100
        """
    )
    recent_grants = [omada_payment_auth_free_public_grant(row) for row in cur.fetchall()]
    cur.execute(
        """
        SELECT
          COALESCE(g.profile_name, 'Unprofiled device') AS profile_name,
          g.profile_contact_number,
          g.client_mac,
          g.device_token_hash,
          g.user_id,
          count(*)::int AS attempts_today,
          max(g.created_at) AS last_attempt_at
        FROM omada_payment_auth_free_grants g
        LEFT JOIN payment_orders po ON po.id = g.payment_order_id
        WHERE g.created_at >= date_trunc('day', now())
          AND (po.id IS NULL OR NOT (po.status = 'PAID' AND po.fulfillment_status = 'FULFILLED'))
        GROUP BY COALESCE(g.profile_name, 'Unprofiled device'), g.profile_contact_number, g.client_mac, g.device_token_hash, g.user_id
        HAVING count(*) >= %s
        ORDER BY attempts_today DESC, last_attempt_at DESC
        LIMIT 100
        """,
        (settings["daily_attempt_limit"],),
    )
    abuse_rows = []
    for row in cur.fetchall():
        public_row = {
            "profile_name": row.get("profile_name"),
            "profile_contact_number": row.get("profile_contact_number"),
            "client_mac": row.get("client_mac"),
            "device_token_hash": row.get("device_token_hash"),
            "user_id": str(row["user_id"]) if row.get("user_id") else None,
            "attempts_today": int(row.get("attempts_today") or 0),
            "last_attempt_at": row.get("last_attempt_at"),
        }
        if omada_payment_auth_free_abuse_is_overridden(public_row, abuse_overrides):
            continue
        abuse_rows.append(public_row)
    cur.execute(
        """
        SELECT *
        FROM omada_payment_auth_free_abuse_blocks
        WHERE block_until > now()
        ORDER BY block_until DESC
        LIMIT 100
        """
    )
    active_blocks = []
    for row in cur.fetchall():
        public_row = {
            "id": str(row["id"]),
            "user_id": str(row["user_id"]) if row.get("user_id") else None,
            "portal_session_id": str(row["portal_session_id"]) if row.get("portal_session_id") else None,
            "client_mac": row.get("client_mac"),
            "device_token_hash": row.get("device_token_hash"),
            "profile_name": row.get("profile_name"),
            "profile_contact_number": row.get("profile_contact_number"),
            "attempts_today": int(row.get("attempts_today") or 0),
            "reason": row.get("reason"),
            "block_until": row.get("block_until"),
            "created_at": row.get("created_at"),
        }
        if omada_payment_auth_free_abuse_is_overridden(public_row, abuse_overrides):
            continue
        active_blocks.append(public_row)
    remote_snapshot = omada_payment_auth_free_remote_snapshot(cur, active_grants)
    overview["active_blocks"] = len(active_blocks)
    overview["remote_client_count"] = len(remote_snapshot["remote_clients"])
    overview["orphaned_remote_clients"] = len(remote_snapshot["orphaned_remote_clients"])
    overview["remote_sync_errors"] = len(remote_snapshot["remote_errors"])
    return {
        "settings": settings,
        "overview": {key: int(value or 0) for key, value in overview.items()},
        "active_grants": active_grants,
        "recent_grants": recent_grants,
        "abuse_profiles": abuse_rows,
        "active_blocks": active_blocks,
        "remote_clients": remote_snapshot["remote_clients"],
        "orphaned_remote_clients": remote_snapshot["orphaned_remote_clients"],
        "remote_errors": remote_snapshot["remote_errors"],
        "guide": {
            "summary": "When a customer starts PayMongo checkout from a real browser, the system can place that client MAC in Omada Authentication-Free Client for a short time.",
            "cleanup": "After payment succeeds, the entry stays briefly in paid grace so PayMongo/GCash can finish returning. It is removed early once the customer reaches the portal, or automatically when the grace window expires.",
            "abuse": "The daily limit prevents customers from repeatedly opening free payment windows without paying.",
        },
    }


def log_omada_automation(admin_id, action: str, status: str, request_summary: dict = None, response_summary: dict = None, error_message: str = None):
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO omada_automation_logs(admin_id, action, status, request_summary, response_summary, error_message)
                VALUES (%s, %s, %s, %s, %s, %s)
                """,
                (
                    admin_id,
                    action,
                    status,
                    Json(sanitize_summary(request_summary or {})),
                    Json(sanitize_summary(response_summary or {})),
                    error_message,
                ),
            )


def tcp_check(host: str, port: int, timeout: float = 3.0):
    started = time.time()
    try:
        with socket.create_connection((host, int(port)), timeout=timeout):
            return {"port": int(port), "status": "Reachable", "latency_ms": int((time.time() - started) * 1000)}
    except socket.timeout:
        return {"port": int(port), "status": "Timeout", "latency_ms": None}
    except ConnectionRefusedError:
        return {"port": int(port), "status": "Connection refused", "latency_ms": None}
    except OSError as exc:
        return {"port": int(port), "status": "Not reachable", "error": str(exc), "latency_ms": None}


def routeros_write_word(sock, word: str):
    data = word.encode()
    length = len(data)
    if length < 0x80:
        prefix = bytes([length])
    elif length < 0x4000:
        prefix = struct.pack("!H", length | 0x8000)
    elif length < 0x200000:
        prefix = struct.pack("!I", length | 0xC00000)[1:]
    elif length < 0x10000000:
        prefix = struct.pack("!I", length | 0xE0000000)
    else:
        prefix = b"\xF0" + struct.pack("!I", length)
    sock.sendall(prefix + data)


def routeros_read_length(sock):
    first = sock.recv(1)
    if not first:
        raise OSError("RouterOS API closed the connection")
    c = first[0]
    if (c & 0x80) == 0:
        return c
    if (c & 0xC0) == 0x80:
        return ((c & ~0xC0) << 8) + sock.recv(1)[0]
    if (c & 0xE0) == 0xC0:
        rest = sock.recv(2)
        return ((c & ~0xE0) << 16) + (rest[0] << 8) + rest[1]
    if (c & 0xF0) == 0xE0:
        rest = sock.recv(3)
        return ((c & ~0xF0) << 24) + (rest[0] << 16) + (rest[1] << 8) + rest[2]
    rest = sock.recv(4)
    return struct.unpack("!I", rest)[0]


def routeros_read_sentence(sock):
    words = []
    while True:
        length = routeros_read_length(sock)
        if length == 0:
            return words
        words.append(sock.recv(length).decode(errors="replace"))


def routeros_send_sentence(sock, words):
    for word in words:
        routeros_write_word(sock, word)
    routeros_write_word(sock, "")


def routeros_sentence_dict(sentence):
    data = {}
    for word in sentence[1:]:
        if word.startswith("="):
            key_value = word[1:].split("=", 1)
            if len(key_value) == 2:
                key = sanitize_routeros_text(key_value[0], max_length=200) or "field"
                data[key] = sanitize_routeros_text(key_value[1])
    return data


def routeros_read_result(sock):
    replies = []
    while True:
        sentence = routeros_read_sentence(sock)
        if not sentence:
            continue
        marker = sentence[0]
        if marker == "!re":
            replies.append(routeros_sentence_dict(sentence))
            continue
        if marker == "!empty":
            continue
        if marker == "!done":
            return replies
        if marker == "!trap":
            message = next((word.split("=", 2)[2] for word in sentence if word.startswith("=message=")), "RouterOS API command failed")
            raise RuntimeError(sanitize_routeros_text(message))
        raise RuntimeError(f"Unexpected RouterOS API response: {sanitize_routeros_text(marker)}")


def routeros_login_socket(sock, username: Optional[str], password: Optional[str]):
    routeros_send_sentence(sock, ["/login", f"=name={username or ''}", f"=password={password or ''}"])
    routeros_read_result(sock)


def routeros_cli_preview(path: str, params: dict):
    command = path.strip("/").replace("/", " ")
    parts = [f"/{command}"]
    for key, value in (params or {}).items():
        if value is None or value == "":
            continue
        text_value = str(value)
        if any(char.isspace() for char in text_value):
            text_value = '"' + text_value.replace('"', '\\"') + '"'
        parts.append(f"{key}={text_value}")
    return " ".join(parts)


def routeros_remove_preview(print_path: str, query_field: str, query_value: str):
    base = print_path[:-6] if print_path.endswith("/print") else print_path
    command = base.strip("/").replace("/", " ")
    text_value = str(query_value)
    if any(char.isspace() for char in text_value):
        text_value = '"' + text_value.replace('"', '\\"') + '"'
    return f"/{command} remove [find {query_field}={text_value}]"


def routeros_safe_identifier(value: Optional[str], fallback: str = "3jcentralpisowifi") -> str:
    text = re.sub(r"[^a-zA-Z0-9]+", "-", (value or fallback).strip().lower()).strip("-")
    return text or fallback


def mikrotik_hotspot_managed_names(display_name: Optional[str]) -> dict:
    identifier = routeros_safe_identifier(display_name)
    base = identifier if identifier.endswith("-hotspot") else f"{identifier}-hotspot"
    return {
        "identifier": identifier,
        "hotspot_base": base,
        "vlan": f"{base}-vlan",
        "profile": f"{base}-profile",
        "server": base,
        "pool": f"{base}-pool",
        "dhcp": f"{base}-dhcp",
    }


def routeros_command_words(path: str, params: dict):
    return [path] + [f"={key}={value}" for key, value in (params or {}).items() if value is not None and value != ""]


def routeros_print_path_for_add(path: str):
    if path.endswith("/add"):
        return f"{path[:-4]}/print"
    return None


def routeros_remove_path_for_print(print_path: str):
    if print_path.endswith("/print"):
        return f"{print_path[:-6]}/remove"
    return None


def routeros_truthy(value) -> bool:
    return str(value or "").strip().lower() in {"true", "yes", "1"}


def routeros_query_words(print_path: str, query_fields: Optional[dict] = None, proplist: Optional[str] = None) -> list[str]:
    words = [print_path] + [
        f"?{key}={value}"
        for key, value in (query_fields or {}).items()
        if value not in (None, "")
    ]
    if proplist:
        words.append(f"=.proplist={proplist}")
    return words


def routeros_active_broad_notrack_condition() -> dict:
    return {
        "print_path": "/ip/firewall/raw/print",
        "query": {"chain": "prerouting", "action": "notrack"},
        "match": "active_broad_notrack",
        "label": "active broad raw notrack rule",
        "missing_message": "No active broad raw notrack rule was detected; this tracking exception is not required.",
    }


def routeros_active_fasttrack_condition() -> dict:
    return {
        "print_path": "/ip/firewall/filter/print",
        "query": {"chain": "forward", "action": "fasttrack-connection"},
        "match": "active_fasttrack",
        "label": "active forward fasttrack rule",
        "missing_message": "No active FastTrack rule was detected; this anti-tether FastTrack bypass is not required.",
    }


def routeros_condition_label(condition: Optional[dict]) -> str:
    if not condition:
        return ""
    if condition.get("label"):
        return condition["label"]
    query = condition.get("query") or {}
    return ", ".join(f"{key}={value}" for key, value in query.items()) or condition.get("print_path") or "condition"


def routeros_condition_rows(sock, condition: Optional[dict]) -> list[dict]:
    if not condition:
        return []
    print_path = condition.get("print_path")
    if not print_path:
        return []
    proplist = condition.get("proplist")
    if condition.get("match") == "active_broad_notrack":
        proplist = proplist or ".id,chain,action,src-address,dst-address,disabled,comment"
    if condition.get("match") == "active_fasttrack":
        proplist = proplist or ".id,chain,action,disabled,comment"
    rows = routeros_read_result_after_send(sock, routeros_query_words(print_path, condition.get("query"), proplist))
    if condition.get("match") == "active_broad_notrack":
        return [
            row
            for row in rows
            if not routeros_truthy(row.get("disabled"))
            and str(row.get("chain") or "").strip().lower() == "prerouting"
            and str(row.get("action") or "").strip().lower() == "notrack"
            and not str(row.get("src-address") or "").strip()
            and not str(row.get("dst-address") or "").strip()
        ]
    if condition.get("match") == "active_fasttrack":
        return [
            row
            for row in rows
            if not routeros_truthy(row.get("disabled"))
            and str(row.get("chain") or "").strip().lower() == "forward"
            and str(row.get("action") or "").strip().lower() == "fasttrack-connection"
        ]
    return rows


def routeros_execute_commands(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, commands: list, timeout: float = 8.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        results = []
        for command in commands:
            path = command.get("path")
            params = command.get("params") or {}
            label = command.get("label") or path
            only_if_query_exists = command.get("only_if_query_exists")
            if only_if_query_exists:
                condition_rows = routeros_condition_rows(sock, only_if_query_exists)
                if not condition_rows:
                    results.append({
                        "label": label,
                        "status": "SKIPPED",
                        "message": only_if_query_exists.get("missing_message") or "Required RouterOS condition was not detected; this step is not required.",
                        "condition": routeros_condition_label(only_if_query_exists),
                    })
                    continue
            verify = command.get("verify")
            if verify and verify.get("words"):
                existing = routeros_read_result_after_send(sock, verify["words"])
                if routeros_verify_matches(existing, verify):
                    results.append({
                        "label": label,
                        "status": "SKIPPED",
                        "message": routeros_verify_message(verify),
                        "existing_count": len(existing),
                    })
                    continue
            if command.get("set_existing_query"):
                query = command["set_existing_query"]
                print_path = query.get("print_path")
                query_fields = query.get("query") or {}
                set_path = query.get("set_path") or path
                existing = routeros_read_result_after_send(
                    sock,
                    [print_path] + [f"?{key}={value}" for key, value in query_fields.items() if value not in (None, "")],
                )
                if not existing:
                    query_label = ", ".join(f"{key}={value}" for key, value in query_fields.items())
                    raise RuntimeError(f"{label}: existing RouterOS item was not found for {query_label}.")
                item_id = existing[0].get(".id")
                if not item_id:
                    raise RuntimeError(f"{label}: existing RouterOS item has no ID.")
                replies = routeros_read_result_after_send(sock, routeros_command_words(set_path, {".id": item_id, **params}))
                results.append({"label": label, "status": "SUCCESS", "message": "Existing RouterOS item was updated.", "reply_count": len(replies)})
                continue
            if command.get("place_before_query"):
                place_query = command["place_before_query"]
                place_print_path = place_query.get("print_path")
                place_fields = place_query.get("query") or {}
                if place_print_path and place_fields:
                    place_rows = routeros_condition_rows(sock, place_query)
                    if place_rows and place_rows[0].get(".id"):
                        params = {**params, "place-before": place_rows[0][".id"]}
            if command.get("merge_bridge_vlan_tagged") or command.get("merge_bridge_vlan_members"):
                print_path = routeros_print_path_for_add(path)
                bridge = params.get("bridge")
                vlan_ids = params.get("vlan-ids")
                desired_tagged = params.get("tagged")
                desired_untagged = params.get("untagged")
                if print_path and bridge and vlan_ids and (desired_tagged or desired_untagged):
                    existing = routeros_read_result_after_send(sock, [print_path, f"?bridge={bridge}", f"?vlan-ids={vlan_ids}"])
                    if existing:
                        editable_existing = [item for item in existing if not routeros_truthy(item.get("dynamic"))]
                        if not editable_existing:
                            words = routeros_command_words(path, params)
                            replies = routeros_read_result_after_send(sock, words)
                            results.append({
                                "label": label,
                                "status": "SUCCESS",
                                "message": "Created a static bridge VLAN row. Existing dynamic RouterOS VLAN rows are read-only and were left unchanged.",
                                "reply_count": len(replies),
                                "dynamic_existing_count": len(existing),
                            })
                            continue
                        existing_item = editable_existing[0]
                        existing_tagged = existing_item.get("tagged") or ""
                        existing_untagged = existing_item.get("untagged") or ""
                        merged_tagged = station_dedupe_csv(existing_tagged, desired_tagged)
                        merged_untagged = station_dedupe_csv(existing_untagged, desired_untagged)
                        existing_set = {item.strip() for item in existing_tagged.split(",") if item.strip()}
                        merged_set = {item.strip() for item in merged_tagged.split(",") if item.strip()}
                        existing_untagged_set = {item.strip() for item in existing_untagged.split(",") if item.strip()}
                        merged_untagged_set = {item.strip() for item in merged_untagged.split(",") if item.strip()}
                        tagged_ok = not desired_tagged or merged_set == existing_set
                        untagged_ok = not desired_untagged or merged_untagged_set == existing_untagged_set
                        if tagged_ok and untagged_ok:
                            results.append({"label": label, "status": "SKIPPED", "message": "Existing static bridge VLAN already has the required tagged/untagged members.", "existing_count": len(editable_existing), "dynamic_existing_count": len(existing) - len(editable_existing)})
                            continue
                        item_id = existing_item.get(".id")
                        if not item_id:
                            raise RuntimeError("Existing bridge VLAN item has no RouterOS ID.")
                        set_words = ["/interface/bridge/vlan/set", f"=.id={item_id}"]
                        if desired_tagged:
                            set_words.append(f"=tagged={merged_tagged}")
                        if desired_untagged:
                            set_words.append(f"=untagged={merged_untagged}")
                        routeros_read_result_after_send(sock, set_words)
                        changed = []
                        if desired_tagged:
                            changed.append(f"tagged={merged_tagged}")
                        if desired_untagged:
                            changed.append(f"untagged={merged_untagged}")
                        results.append({"label": label, "status": "SUCCESS", "message": f"Updated existing static bridge VLAN members: {', '.join(changed)}.", "existing_count": len(editable_existing), "dynamic_existing_count": len(existing) - len(editable_existing)})
                        continue
            unique_query = None
            if command.get("existing_query"):
                unique_query = command.get("existing_query")
            elif command.get("unique_comment"):
                unique_query = ("comment", command.get("unique_comment"))
            elif command.get("unique_field") and command.get("unique_value"):
                unique_query = (command.get("unique_field"), command.get("unique_value"))
            if unique_query:
                print_path = routeros_print_path_for_add(path)
                if print_path:
                    if isinstance(unique_query, dict):
                        query_words = [print_path] + [f"?{key}={value}" for key, value in unique_query.items() if value not in (None, "")]
                    else:
                        query_words = [print_path, f"?{unique_query[0]}={unique_query[1]}"]
                    existing = routeros_read_result_after_send(sock, query_words)
                    if existing:
                        if isinstance(unique_query, dict):
                            query_label = ", ".join(f"{key}={value}" for key, value in unique_query.items())
                        else:
                            query_label = f"{unique_query[0]}={unique_query[1]}"
                        results.append({"label": label, "status": "SKIPPED", "message": f"Existing MikroTik item was found for {query_label}.", "existing_count": len(existing)})
                        continue
            words = routeros_command_words(path, params)
            replies = routeros_read_result_after_send(sock, words)
            results.append({"label": label, "status": "SUCCESS", "message": "Command accepted by RouterOS.", "reply_count": len(replies)})
        return {"status": "SUCCESS", "message": "RouterOS commands completed.", "results": results}
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_duration_to_seconds(value: Optional[str]) -> int:
    text = str(value or "").strip().lower()
    if not text:
        return 0
    if ":" in text and re.fullmatch(r"\d+:\d{1,2}:\d{1,2}", text):
        hours, minutes, seconds = [int(part) for part in text.split(":")]
        return hours * 3600 + minutes * 60 + seconds
    total = 0
    for amount, unit in re.findall(r"(\d+)([wdhms])", text):
        number = int(amount)
        if unit == "w":
            total += number * 7 * 24 * 3600
        elif unit == "d":
            total += number * 24 * 3600
        elif unit == "h":
            total += number * 3600
        elif unit == "m":
            total += number * 60
        elif unit == "s":
            total += number
    if total:
        return total
    try:
        return int(float(text))
    except ValueError:
        return 0


def routeros_authorize_hotspot_client(
    host: str,
    port: int,
    username: Optional[str],
    password: Optional[str],
    use_tls: bool,
    hotspot_username: str,
    hotspot_password: str,
    duration_seconds: int,
    comment: str,
    login_ip: str,
    client_mac: Optional[str],
    timeout: float = 8.0,
):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        requested_seconds = max(int(duration_seconds or 0), 60)
        existing_users = routeros_read_result_after_send(
            sock,
            [
                "/ip/hotspot/user/print",
                f"?name={hotspot_username}",
                "=.proplist=.id,name,uptime,limit-uptime,disabled,comment",
            ],
        )
        results = []
        if existing_users:
            existing = existing_users[0]
            existing_id = existing.get(".id")
            if not existing_id:
                raise RuntimeError("Existing HotSpot user has no RouterOS ID.")
            used_seconds = routeros_duration_to_seconds(existing.get("uptime"))
            new_limit_seconds = max(used_seconds + requested_seconds, requested_seconds)
            routeros_read_result_after_send(
                sock,
                [
                    "/ip/hotspot/user/set",
                    f"=.id={existing_id}",
                    f"=password={hotspot_password}",
                    f"=limit-uptime={new_limit_seconds}s",
                    f"=comment={comment}",
                    "=disabled=no",
                ],
            )
            results.append({
                "label": "Extend existing portal HotSpot user",
                "status": "SUCCESS",
                "message": f"Existing HotSpot user limit updated to preserve {requested_seconds}s of new voucher time.",
                "previous_uptime": existing.get("uptime"),
                "new_limit_uptime": f"{new_limit_seconds}s",
            })
        else:
            routeros_read_result_after_send(
                sock,
                [
                    "/ip/hotspot/user/add",
                    f"=name={hotspot_username}",
                    f"=password={hotspot_password}",
                    f"=limit-uptime={requested_seconds}s",
                    f"=comment={comment}",
                ],
            )
            results.append({
                "label": "Create portal HotSpot user",
                "status": "SUCCESS",
                "message": "HotSpot user created for this portal account.",
                "limit_uptime": f"{requested_seconds}s",
            })
        login_words = [
            "/ip/hotspot/active/login",
            f"=user={hotspot_username}",
            f"=password={hotspot_password}",
            f"=ip={login_ip}",
        ]
        if client_mac:
            login_words.append(f"=mac-address={client_mac}")
        replies = routeros_read_result_after_send(sock, login_words)
        results.append({
            "label": "Authorize active MikroTik HotSpot client",
            "status": "SUCCESS",
            "message": "Command accepted by RouterOS.",
            "reply_count": len(replies),
        })
        return {"status": "SUCCESS", "message": "RouterOS HotSpot authorization completed.", "results": results}
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_remove_hotspot_client_state(
    host: str,
    port: int,
    username: Optional[str],
    password: Optional[str],
    use_tls: bool,
    client_mac: Optional[str] = None,
    timeout: float = 8.0,
) -> dict:
    if not client_mac:
        return {"status": "SKIPPED", "message": "No client MAC was available for HotSpot state cleanup.", "removed": []}
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    removed = []
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        for print_path, remove_path in [
            ("/ip/hotspot/active/print", "/ip/hotspot/active/remove"),
            ("/ip/hotspot/host/print", "/ip/hotspot/host/remove"),
        ]:
            rows = routeros_read_result_after_send(
                sock,
                [print_path, f"?mac-address={client_mac}", "=.proplist=.id,address,to-address,mac-address,user,server,authorized"],
            )
            for row in rows:
                item_id = row.get(".id")
                if not item_id:
                    continue
                routeros_read_result_after_send(sock, [remove_path, f"=.id={item_id}"])
                removed.append({"path": remove_path, "id": item_id, "address": row.get("address"), "to_address": row.get("to-address")})
        return {"status": "SUCCESS", "message": "HotSpot active/host state removed for this client.", "removed": removed}
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_execute_remove_commands(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, commands: list, timeout: float = 8.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        results = []
        for command in commands:
            label = command.get("label") or command.get("print_path") or "Remove managed item"
            print_path = command.get("print_path")
            remove_path = command.get("remove_path") or routeros_remove_path_for_print(print_path or "")
            query_field = command.get("query_field")
            query_value = command.get("query_value")
            if not print_path or not remove_path or not query_field or query_value in (None, ""):
                results.append({"label": label, "status": "SKIPPED", "message": "Removal command is incomplete."})
                continue
            existing = routeros_read_result_after_send(sock, [print_path, f"?{query_field}={query_value}"])
            if not existing:
                results.append({"label": label, "status": "SKIPPED", "message": "No matching 3JCentralPisowifi-managed item found."})
                continue
            removed_ids = []
            for item in existing:
                item_id = item.get(".id")
                if not item_id:
                    continue
                routeros_read_result_after_send(sock, [remove_path, f"=.id={item_id}"])
                removed_ids.append(item_id)
            results.append({"label": label, "status": "SUCCESS", "message": f"Removed {len(removed_ids)} managed item(s).", "removed_count": len(removed_ids)})
        return {"status": "SUCCESS", "message": "Managed MikroTik configuration removed.", "results": results}
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_detect_remove_targets(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, commands: list, timeout: float = 8.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        items = []
        found_count = 0
        for index, command in enumerate(commands):
            label = command.get("label") or command.get("print_path") or "Managed item"
            verify = command.get("verify")
            if verify and verify.get("words"):
                existing = routeros_read_result_after_send(sock, verify["words"])
                already_clean = routeros_verify_matches(existing, verify)
                needs_action = bool(existing) and not already_clean
                found_count += 1 if needs_action else 0
                items.append({
                    "label": label,
                    "command_index": index,
                    "status": "FOUND" if needs_action else "NOT_FOUND",
                    "found_count": 1 if needs_action else 0,
                    "query_label": verify.get("label") or ", ".join(verify.get("words") or []),
                    "existing_count": len(existing),
                    "message": verify.get("not_found_message") if needs_action else routeros_verify_message(verify),
                })
                continue
            print_path = command.get("print_path")
            query_field = command.get("query_field")
            query_value = command.get("query_value")
            if not print_path or not query_field or query_value in (None, ""):
                items.append({"label": label, "command_index": index, "status": "SKIPPED", "found_count": 0, "message": "Detection command is incomplete."})
                continue
            existing = routeros_read_result_after_send(sock, [print_path, f"?{query_field}={query_value}"])
            count = len(existing)
            found_count += count
            items.append({
                "label": label,
                "command_index": index,
                "status": "FOUND" if count else "NOT_FOUND",
                "found_count": count,
                "query_field": query_field,
                "query_value": query_value,
            })
        return {
            "status": "SUCCESS",
            "message": f"Found {found_count} 3JCentralPisowifi-managed MikroTik object(s).",
            "has_managed_config": found_count > 0,
            "found_count": found_count,
            "items": items,
        }
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_detect_station_apply_targets(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, commands: list, timeout: float = 8.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        items = []
        found_count = 0
        for index, command in enumerate(commands):
            label = command.get("label") or command.get("path") or f"Command {index + 1}"
            if command.get("operation") == "REMOVE_OLD":
                verify = command.get("verify")
                if verify and verify.get("words"):
                    existing = routeros_read_result_after_send(sock, verify["words"])
                    matched = routeros_verify_matches(existing, verify)
                    already_clean = not existing or matched
                    found_count += 1 if already_clean else 0
                    items.append({
                        "label": label,
                        "command_index": index,
                        "status": "FOUND" if already_clean else "NOT_FOUND",
                        "found_count": 1 if already_clean else 0,
                        "query_label": verify.get("label") or ", ".join(verify.get("words") or []),
                        "existing_count": len(existing),
                        "message": "Old managed setting is already absent." if not existing else routeros_verify_message(verify) if matched else verify.get("not_found_message") or "Old managed setting still needs cleanup.",
                    })
                    continue
                print_path = command.get("print_path")
                query_field = command.get("query_field")
                query_value = command.get("query_value")
                if not print_path or not query_field or query_value in (None, ""):
                    items.append({"label": label, "command_index": index, "status": "UNKNOWN", "found_count": 0, "message": "No safe cleanup detection query is available for this old config removal step."})
                    continue
                existing = routeros_read_result_after_send(sock, [print_path, f"?{query_field}={query_value}"])
                already_clean = len(existing) == 0
                found_count += 1 if already_clean else 0
                items.append({
                    "label": label,
                    "command_index": index,
                    "status": "FOUND" if already_clean else "NOT_FOUND",
                    "found_count": 1 if already_clean else 0,
                    "query_label": f"{query_field}={query_value}",
                    "existing_count": len(existing),
                    "message": "Old managed object is already absent." if already_clean else "Old managed object still exists and will be removed before the new config is pushed.",
                })
                continue
            path = command.get("path")
            params = command.get("params") or {}
            print_path = routeros_print_path_for_add(path or "")
            query_words = None
            query_label = ""
            only_if_query_exists = command.get("only_if_query_exists")
            if only_if_query_exists:
                condition_rows = routeros_condition_rows(sock, only_if_query_exists)
                if not condition_rows:
                    found_count += 1
                    items.append({
                        "label": label,
                        "command_index": index,
                        "status": "FOUND",
                        "found_count": 1,
                        "query_label": routeros_condition_label(only_if_query_exists),
                        "existing_count": 0,
                        "message": only_if_query_exists.get("missing_message") or "Required RouterOS condition was not detected; this step is not required.",
                        "condition_skipped": True,
                    })
                    continue
            verify = command.get("verify")
            if verify and verify.get("words"):
                existing = routeros_read_result_after_send(sock, verify["words"])
                matched = routeros_verify_matches(existing, verify)
                found_count += 1 if matched else 0
                items.append({
                    "label": label,
                    "command_index": index,
                    "status": "FOUND" if matched else "NOT_FOUND",
                    "found_count": 1 if matched else 0,
                    "query_label": verify.get("label") or ", ".join(verify.get("words") or []),
                    "existing_count": len(existing),
                    "message": routeros_verify_message(verify) if matched else verify.get("not_found_message") or "Required RouterOS state was not detected.",
                })
                continue
            if command.get("set_existing_query"):
                query = command["set_existing_query"]
                print_path = query.get("print_path")
                query_fields = query.get("query") or {}
                existing = routeros_read_result_after_send(
                    sock,
                    [print_path] + [f"?{key}={value}" for key, value in query_fields.items() if value not in (None, "")],
                )
                items.append({
                    "label": label,
                    "command_index": index,
                    "status": "UNKNOWN",
                    "found_count": 0,
                    "query_label": ", ".join(f"{key}={value}" for key, value in query_fields.items()),
                    "existing_count": len(existing),
                    "message": "This step updates an existing RouterOS item. Detection requires a verification rule.",
                })
                continue
            if (command.get("merge_bridge_vlan_tagged") or command.get("merge_bridge_vlan_members")) and print_path:
                bridge = params.get("bridge")
                vlan_ids = params.get("vlan-ids")
                tagged = {item.strip() for item in str(params.get("tagged") or "").split(",") if item.strip()}
                untagged = {item.strip() for item in str(params.get("untagged") or "").split(",") if item.strip()}
                if bridge and vlan_ids:
                    query_words = [print_path, f"?bridge={bridge}", f"?vlan-ids={vlan_ids}"]
                    query_label = f"bridge={bridge}, vlan-ids={vlan_ids}"
                    existing = routeros_read_result_after_send(sock, query_words)
                    static_rows = [row for row in existing if not routeros_truthy(row.get("dynamic"))]
                    matched = any(
                        tagged.issubset({item.strip() for item in str(row.get("tagged") or "").split(",") if item.strip()})
                        and untagged.issubset({item.strip() for item in str(row.get("untagged") or "").split(",") if item.strip()})
                        for row in static_rows
                    )
                    found_count += 1 if matched else 0
                    items.append({
                        "label": label,
                        "command_index": index,
                        "status": "FOUND" if matched else "NOT_FOUND",
                        "found_count": 1 if matched else 0,
                        "query_label": query_label,
                        "dynamic_existing_count": len(existing) - len(static_rows),
                        "message": "Static bridge VLAN row has the required tagged/untagged members." if matched else "No static bridge VLAN row has all required tagged/untagged members yet.",
                    })
                    continue
            if command.get("existing_query") and print_path:
                unique_query = command.get("existing_query")
                if isinstance(unique_query, dict):
                    query_words = [print_path] + [f"?{key}={value}" for key, value in unique_query.items() if value not in (None, "")]
                    query_label = ", ".join(f"{key}={value}" for key, value in unique_query.items())
            elif command.get("unique_comment") and print_path:
                query_words = [print_path, f"?comment={command.get('unique_comment')}"]
                query_label = f"comment={command.get('unique_comment')}"
            elif command.get("unique_field") and command.get("unique_value") and print_path:
                query_words = [print_path, f"?{command.get('unique_field')}={command.get('unique_value')}"]
                query_label = f"{command.get('unique_field')}={command.get('unique_value')}"
            if not query_words:
                items.append({"label": label, "command_index": index, "status": "UNKNOWN", "found_count": 0, "message": "No safe detection query is available for this command."})
                continue
            existing = routeros_read_result_after_send(sock, query_words)
            count = len(existing)
            found_count += 1 if count else 0
            items.append({
                "label": label,
                "command_index": index,
                "status": "FOUND" if count else "NOT_FOUND",
                "found_count": 1 if count else 0,
                "query_label": query_label,
                "existing_count": count,
            })
        return {
            "status": "SUCCESS",
            "message": f"Found {found_count} pushed station step(s).",
            "has_managed_config": found_count > 0,
            "found_count": found_count,
            "items": items,
        }
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_readonly_query(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, words: list, timeout: float = 8.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        return routeros_read_result_after_send(sock, words)
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_file_words(file_path: str) -> list[str]:
    return [
        "/file/print",
        f"?name={file_path}",
        "=.proplist=.id,name,type,size,contents,creation-time,modified-time",
    ]


def routeros_file_query(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, file_path: str, timeout: float = 8.0):
    return routeros_readonly_query(host, port, username, password, use_tls, routeros_file_words(file_path), timeout=timeout)


def routeros_speed_rate_value(value) -> str:
    try:
        mbps = Decimal(str(value or "0")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise RuntimeError("Speed limit Mbps is invalid.") from exc
    if mbps <= 0:
        raise RuntimeError("Speed limit Mbps must be greater than zero.")
    if mbps == mbps.to_integral_value():
        return f"{int(mbps)}M"
    return f"{str(mbps).rstrip('0').rstrip('.')}M"


def routeros_speed_queue_name(session_id) -> str:
    safe = re.sub(r"[^a-zA-Z0-9]+", "", str(session_id or "speed"))
    return f"3J-SPEED-{safe[:20] or secrets.token_hex(5)}"


def routeros_speed_queue_comment(session_id, bag_item_id=None) -> str:
    base = f"3JCentralPisowifi speed limit portal_session={session_id}"
    if bag_item_id:
        base += f" bag_item={bag_item_id}"
    return sanitize_routeros_text(base, 240)


def routeros_upsert_simple_queue(
    host: str,
    port: int,
    username: Optional[str],
    password: Optional[str],
    use_tls: bool,
    *,
    queue_name: str,
    target_ip: str,
    upload_mbps,
    download_mbps,
    comment: str,
    timeout: float = 8.0,
) -> dict:
    target = f"{host_ip(target_ip)}/32"
    max_limit = f"{routeros_speed_rate_value(upload_mbps)}/{routeros_speed_rate_value(download_mbps)}"
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        rows = routeros_read_result_after_send(
            sock,
            [
                "/queue/simple/print",
                f"?name={queue_name}",
                "=.proplist=.id,name,target,max-limit,comment,disabled",
            ],
        )
        params = {
            "name": queue_name,
            "target": target,
            "max-limit": max_limit,
            "comment": comment,
            "disabled": "no",
        }
        if rows:
            item_id = rows[0].get(".id")
            if not item_id:
                raise RuntimeError("Existing RouterOS queue has no ID and cannot be updated safely.")
            routeros_read_result_after_send(sock, ["/queue/simple/set", f"=.id={item_id}", *[f"={key}={value}" for key, value in params.items()]])
            action = "UPDATED"
        else:
            routeros_read_result_after_send(sock, ["/queue/simple/add", *[f"={key}={value}" for key, value in params.items()]])
            action = "CREATED"
        verified = routeros_read_result_after_send(
            sock,
            [
                "/queue/simple/print",
                f"?name={queue_name}",
                "=.proplist=.id,name,target,max-limit,comment,disabled",
            ],
        )
        return {
            "status": "SUCCESS",
            "action": action,
            "queue_name": queue_name,
            "target": target,
            "max_limit": max_limit,
            "queue": sanitize_summary(verified[0] if verified else {}),
        }
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_remove_simple_queue(
    host: str,
    port: int,
    username: Optional[str],
    password: Optional[str],
    use_tls: bool,
    *,
    queue_name: str,
    timeout: float = 8.0,
) -> dict:
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        rows = routeros_read_result_after_send(
            sock,
            [
                "/queue/simple/print",
                f"?name={queue_name}",
                "=.proplist=.id,name,target,max-limit,comment,disabled",
            ],
        )
        removed = 0
        for row in rows:
            item_id = row.get(".id")
            if not item_id:
                continue
            routeros_read_result_after_send(sock, ["/queue/simple/remove", f"=.id={item_id}"])
            removed += 1
        return {"status": "SUCCESS", "queue_name": queue_name, "removed_count": removed}
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_write_text_file(host: str, port: int, username: Optional[str], password: Optional[str], use_tls: bool, file_path: str, content: str, timeout: float = 10.0):
    raw_sock = socket.create_connection((host, int(port)), timeout=timeout)
    sock = raw_sock
    try:
        if use_tls:
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(raw_sock, server_hostname=host)
        sock.settimeout(timeout)
        routeros_login_socket(sock, username, password)
        existing = routeros_read_result_after_send(sock, routeros_file_words(file_path))
        action = "add"
        if existing:
            item_id = existing[0].get(".id")
            if not item_id:
                raise RuntimeError("Existing RouterOS file has no ID and cannot be updated safely.")
            try:
                routeros_read_result_after_send(sock, ["/file/set", f"=.id={item_id}", f"=contents={content}"])
                action = "set"
            except Exception:
                routeros_read_result_after_send(sock, ["/file/remove", f"=.id={item_id}"])
                routeros_read_result_after_send(sock, ["/file/add", f"=name={file_path}", f"=contents={content}"])
                action = "replace"
        else:
            routeros_read_result_after_send(sock, ["/file/add", f"=name={file_path}", f"=contents={content}"])
        verified = routeros_read_result_after_send(sock, routeros_file_words(file_path))
        if not verified:
            raise RuntimeError("RouterOS accepted the file operation but the file was not detected after upload.")
        returned_content = verified[0].get("contents")
        expected_hash = sha256(content.encode()).hexdigest()
        try:
            remote_size = int(verified[0].get("size") or 0)
        except (TypeError, ValueError):
            remote_size = 0
        returned_truncated = bool(returned_content and ("[TRUNCATED]" in returned_content or (remote_size and len(returned_content) < remote_size)))
        returned_hash = sha256(returned_content.encode()).hexdigest() if returned_content is not None and not returned_truncated else None
        return {
            "status": "SUCCESS",
            "message": f"Uploaded managed HotSpot login.html using RouterOS /file {action}.",
            "file_path": file_path,
            "action": action,
            "content_hash": expected_hash,
            "returned_content_hash": returned_hash,
            "content_verified": returned_hash == expected_hash if returned_hash else None,
            "content_readback_truncated": returned_truncated,
            "file": sanitize_summary(verified[0]),
        }
    finally:
        try:
            sock.close()
        except Exception:
            pass
        if sock is not raw_sock:
            try:
                raw_sock.close()
            except Exception:
                pass


def routeros_hotspot_file_candidates(file_path: str) -> list[str]:
    normalized = re.sub(r"/+", "/", str(file_path or "").strip().replace("\\", "/")).strip("/")
    if not normalized:
        normalized = "hotspot/login.html"
    candidates = [normalized]
    if not normalized.startswith("flash/"):
        candidates.append(f"flash/{normalized}")
    if normalized.startswith("flash/"):
        candidates.append(normalized.removeprefix("flash/"))
    deduped = []
    for candidate in candidates:
        if candidate and candidate not in deduped:
            deduped.append(candidate)
    return deduped


def routeros_write_text_file_via_ftp(host: str, username: Optional[str], password: Optional[str], file_path: str, content: str, timeout: float = 12.0):
    last_error = None
    content_bytes = content.encode()
    for candidate in routeros_hotspot_file_candidates(file_path):
        directory, _, filename = candidate.rpartition("/")
        try:
            ftp = ftplib.FTP()
            ftp.connect(host, 21, timeout=timeout)
            ftp.login(username or "", password or "")
            if directory:
                ftp.cwd(directory)
            ftp.storbinary(f"STOR {filename or 'login.html'}", io.BytesIO(content_bytes))
            try:
                ftp.quit()
            except Exception:
                pass
            return {
                "status": "SUCCESS",
                "message": f"Uploaded managed HotSpot login.html using RouterOS FTP fallback to {candidate}.",
                "file_path": candidate,
                "action": "ftp_stor",
                "content_hash": sha256(content_bytes).hexdigest(),
                "content_verified": None,
            }
        except Exception as exc:
            last_error = exc
            try:
                ftp.close()
            except Exception:
                pass
    raise RuntimeError(f"RouterOS API file upload failed and FTP fallback could not upload login.html: {last_error}")


def routeros_read_result_after_send(sock, words):
    routeros_send_sentence(sock, words)
    return routeros_read_result(sock)


