def store_pwa_cache_version(row: Optional[dict]) -> str:
    if not row:
        return "default"
    settings = row.get("store_pwa_settings_json") or {}
    raw = f"{settings.get('icon_url') or ''}|{row.get('updated_at') or ''}"
    return md5(raw.encode("utf-8")).hexdigest()[:12]


