        {"id": "rocket", "label": "Rocket Speed", "min_mbps": 50.01, "max_mbps": None, "color": "#a855f7", "glow": "#ec4899", "flame": "#fb923c", "smoke": "#e2e8f0", "travel_speed": 5, "rocket_size": 8, "air_particles": 14, "smoke_particles": 10, "fire_intensity": 8},
