def public_ap_coverage_rows() -> list[dict]:
    rows = fetch_all(
        """
        SELECT DISTINCT ON (a.id)
            a.id,
            a.display_name,
            a.model,
            a.deployment_status,
            a.map_latitude,
            a.map_longitude,
            s.site_name,
            s.omada_site_id,
            s.barangay,
            s.municipality,
            s.latitude AS site_latitude,
            s.longitude AS site_longitude
        FROM ap_deployments a
        LEFT JOIN site_deployments s
               ON (
                    NULLIF(a.omada_site_id, '') IS NOT NULL
                    AND NULLIF(s.omada_site_id, '') IS NOT NULL
                    AND a.omada_site_id = s.omada_site_id
                  )
               OR (
                    NULLIF(a.site_name, '') IS NOT NULL
                    AND lower(a.site_name) = lower(s.site_name)
                  )
        WHERE a.deployment_status <> 'DELETED'
          AND a.map_latitude IS NOT NULL
          AND a.map_longitude IS NOT NULL
        ORDER BY a.id, COALESCE(s.barangay, s.site_name, a.site_name, a.display_name), a.display_name
        """
    )
    public_rows = []
    for row in rows:
        latitude = row.get("map_latitude")
        longitude = row.get("map_longitude")
        if latitude is None or longitude is None:
            continue
        area = normalize_barangay_label(row.get("barangay")) or row.get("site_name") or "Mapped Area"
        public_rows.append({
            "id": str(row["id"]),
            "display_name": row.get("display_name") or "3J WiFi AP",
            "name": row.get("display_name") or "3J WiFi AP",
            "model": row.get("model") or "",
            "status": row.get("deployment_status") or "UNKNOWN",
            "site_name": row.get("site_name") or "",
            "site_id": row.get("omada_site_id") or "",
            "barangay": normalize_barangay_label(row.get("barangay")),
            "municipality": normalize_payment_text(row.get("municipality"), 120),
            "area_label": area,
            "map_latitude": float(latitude),
            "map_longitude": float(longitude),
            "site_latitude": float(row["site_latitude"]) if row.get("site_latitude") is not None else None,
            "site_longitude": float(row["site_longitude"]) if row.get("site_longitude") is not None else None,
            "mapped": True,
            "map_health": "NO_CLIENTS",
            "client_count": 0,
            "active_client_count": 0,
        })
    return public_rows


def public_ap_coverage_summary(rows: Optional[list[dict]] = None) -> dict:
    rows = rows if rows is not None else public_ap_coverage_rows()
    areas = sorted({
        barangay_key(row.get("barangay") or row.get("area_label"))
        for row in rows
        if row.get("barangay") or row.get("area_label")
    })
    labels = []
    seen = set()
    for row in rows:
        label = row.get("barangay") or row.get("area_label")
        key = barangay_key(label)
        if label and key and key not in seen:
            seen.add(key)
            labels.append(label)
    return {
        "ap_count": len(rows),
        "areas_count": len(areas),
        "area_labels": labels,
    }


def public_portal_barangays() -> list[str]:
    rows = fetch_all(
        """
        SELECT DISTINCT label
        FROM (
            SELECT barangay AS label
            FROM site_deployments
            WHERE deployment_status <> 'INACTIVE'
              AND NULLIF(trim(barangay), '') IS NOT NULL
            UNION
            SELECT barangay AS label
            FROM locations
            WHERE NULLIF(trim(barangay), '') IS NOT NULL
        ) source_barangays
        ORDER BY label ASC
        """
    )
    labels = []
    seen = set()
    for row in rows:
        label = normalize_barangay_label(row.get("label"))
        key = barangay_key(label)
        if label and key not in seen:
            seen.add(key)
            labels.append(label)
    return labels


@app.get("/api/portal/ap-coverage")
def portal_ap_coverage():
    aps = public_ap_coverage_rows()
    site_centers = []
    seen_sites = set()
    for ap in aps:
        if ap.get("site_latitude") is None or ap.get("site_longitude") is None:
            continue
        key = ap.get("site_id") or ap.get("site_name") or ap.get("area_label")
        if key in seen_sites:
            continue
        seen_sites.add(key)
        site_centers.append({
            "site_id": ap.get("site_id"),
            "site_name": ap.get("site_name"),
            "latitude": ap.get("site_latitude"),
            "longitude": ap.get("site_longitude"),
            "barangay": ap.get("barangay"),
        })
    return {
        "aps": aps,
        "mapped": aps,
        "site_centers": site_centers,
        "summary": public_ap_coverage_summary(aps),
    }


@app.get("/api/portal/map-tiles/{z}/{x}/{y}.png")
def portal_map_tile(z: int, x: int, y: int):
    """Proxy public map tiles so captive clients only need portal-domain access."""
    if z < 0 or z > 19:
        raise HTTPException(status_code=400, detail="Invalid map zoom.")
    max_tile = 2 ** z
    if x < 0 or x >= max_tile or y < 0 or y >= max_tile:
        raise HTTPException(status_code=400, detail="Invalid map tile.")

    tile_url = f"https://tile.openstreetmap.org/{z}/{x}/{y}.png"
    try:
        tile_response = requests.get(
            tile_url,
            headers={
                "User-Agent": "3JCentralPisowifi/1.0 (AP coverage captive portal map)",
                "Accept": "image/png,image/*;q=0.8,*/*;q=0.5",
            },
            timeout=8,
        )
        tile_response.raise_for_status()
    except requests.RequestException:
        raise HTTPException(status_code=502, detail="Map tile unavailable.")

    return Response(
        content=tile_response.content,
        media_type=tile_response.headers.get("content-type") or "image/png",
        headers={"Cache-Control": "public, max-age=86400, stale-while-revalidate=604800"},
    )


def portal_validate_coordinate(value, minimum, maximum, label):
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"Invalid {label}.")
    if not math.isfinite(number) or number < minimum or number > maximum:
        raise HTTPException(status_code=400, detail=f"Invalid {label}.")
    return number


def portal_distance_meters(lat1, lng1, lat2, lng2):
    radius = 6371000
    phi1 = math.radians(lat1)
    phi2 = math.radians(lat2)
    d_phi = math.radians(lat2 - lat1)
    d_lam = math.radians(lng2 - lng1)
    hav = math.sin(d_phi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(d_lam / 2) ** 2
    return 2 * radius * math.asin(min(1, math.sqrt(hav)))


@app.get("/api/portal/ap-route")
def portal_ap_route(from_lat: float, from_lng: float, to_lat: float, to_lng: float):
    start_lat = portal_validate_coordinate(from_lat, -90, 90, "start latitude")
    start_lng = portal_validate_coordinate(from_lng, -180, 180, "start longitude")
    end_lat = portal_validate_coordinate(to_lat, -90, 90, "destination latitude")
    end_lng = portal_validate_coordinate(to_lng, -180, 180, "destination longitude")
    fallback = {
        "status": "FALLBACK",
        "route": [
            {"latitude": start_lat, "longitude": start_lng},
            {"latitude": end_lat, "longitude": end_lng},
        ],
        "distance_meters": portal_distance_meters(start_lat, start_lng, end_lat, end_lng),
        "duration_seconds": None,
        "source": "direct",
        "warning": "Road route is unavailable, so a direct line was returned.",
    }
    route_url = f"https://router.project-osrm.org/route/v1/driving/{start_lng},{start_lat};{end_lng},{end_lat}"
    try:
        response = requests.get(
            route_url,
            params={"overview": "full", "geometries": "geojson", "steps": "false"},
            headers={
                "User-Agent": "3JCentralPisowifi/1.0 (AP coverage captive portal route)",
                "Accept": "application/json",
            },
            timeout=8,
        )
        response.raise_for_status()
        payload = response.json()
        route = (payload.get("routes") or [None])[0] or {}
        coordinates = ((route.get("geometry") or {}).get("coordinates") or [])
        points = [
            {"latitude": float(lat), "longitude": float(lng)}
            for lng, lat in coordinates
            if isinstance(lng, (int, float)) and isinstance(lat, (int, float))
        ]
        if len(points) < 2:
            return fallback
        return {
            "status": "OK",
            "route": points[:800],
            "distance_meters": route.get("distance"),
            "duration_seconds": route.get("duration"),
            "source": "osrm",
        }
    except Exception:
        return fallback


OMADA_PORTAL_ENABLE_ACTIONS = (
    "STATION_CONFIGURE_EXTERNAL_PORTAL",
    "CONFIGURE_EXTERNAL_PORTAL",
)


def portal_profile_name_for_station(station: Optional[dict], site: Optional[dict] = None) -> str:
    if station and station.get("station_name"):
        return f"3JCentralPisowifi External Portal - {station['station_name']}"
    if site and site.get("site_name"):
        return f"3JCentralPisowifi External Portal - {site['site_name']}"
    return "3JCentralPisowifi External Portal"


def omada_portal_ap_coverage(api_configured: bool, client: Optional[OmadaApiClient] = None) -> dict:
    ap_config = ensure_ap_deployment_configuration()
    portal_url = current_captive_portal_url()
    portal_url_https = str(portal_url or "").strip().lower().startswith("https://")
    site_rows = {
        str(row.get("omada_site_id") or ""): row
        for row in local_site_deployments_for_ap_inventory()
        if row.get("omada_site_id")
    }
    ap_rows = fetch_all(
        """
        SELECT *
        FROM ap_deployments
        WHERE deployment_status <> 'DELETED'
        ORDER BY site_name, display_name, mac
        """
    )
    site_portal_status = {}
    portal_client = client
    if api_configured and portal_client is None:
        try:
            _, portal_client = omada_api_client_from_settings()
        except Exception:
            portal_client = None
    for site_id, site in site_rows.items():
        wifi_config = site_wifi_configuration_for_site(site, ap_config)
        desired_ssids = sorted(desired_wifi_ssid_names(wifi_config))
        vlan_tag, vlan_source, station = effective_customer_vlan_for_site(site)
        status = {
            "site_id": site_id,
            "site_name": site.get("site_name"),
            "desired_ssids": desired_ssids,
            "vlan_id": vlan_tag,
            "vlan_source": vlan_source,
            "portal_url": portal_url,
            "portal_url_https": portal_url_https,
            "portal_enabled": False,
            "https_redirect_enabled": False,
            "pre_auth_ready": False,
            "portal_error": None,
            "pre_auth_error": None,
            "details": {},
            "pre_auth_access": {},
            "readiness_checks": [],
            "readiness_status": "UNKNOWN",
        }
        if not desired_ssids:
            status["portal_error"] = "No desired SSID names are configured for this site."
        elif not api_configured:
            status["portal_error"] = "Omada API credentials are not configured."
        elif portal_client:
            try:
                details = portal_client.external_portal_ssid_status_if_supported(site_id, desired_ssids)
                status["details"] = sanitize_summary(details)
                status["portal_enabled"] = bool(details.get("all_portal_enabled"))
                status["https_redirect_enabled"] = bool(details.get("all_https_redirect_enabled"))
                if not details.get("all_present"):
                    missing = [item.get("ssid") for item in details.get("ssids", []) if not item.get("exists")]
                    status["portal_error"] = f"SSID missing in Omada portal candidates: {', '.join(missing)}" if missing else "One or more desired SSIDs are missing in Omada."
                elif not details.get("all_portal_enabled"):
                    missing = [item.get("ssid") for item in details.get("ssids", []) if not item.get("portal_enabled")]
                    status["portal_error"] = f"SSID not attached to Omada portal: {', '.join(missing)}" if missing else "Desired SSIDs are not attached to an enabled external portal."
                try:
                    pre_auth = portal_client.pre_auth_access_status_if_supported(site_id, portal_url, extra_hosts=iptv_pre_auth_hosts())
                    status["pre_auth_access"] = sanitize_summary(pre_auth)
                    status["pre_auth_ready"] = bool(pre_auth.get("ready"))
                    if not pre_auth.get("ready"):
                        missing = pre_auth.get("missing_hosts") or []
                        if not pre_auth.get("enabled"):
                            status["pre_auth_error"] = "Omada Pre-Auth Access is disabled."
                        elif missing:
                            status["pre_auth_error"] = f"Pre-auth access is missing: {', '.join(missing[:5])}"
                        else:
                            status["pre_auth_error"] = "Pre-auth access is incomplete."
                except Exception as exc:
                    status["pre_auth_error"] = sanitize_routeros_text(str(exc))
            except Exception as exc:
                response_summary = exc.response_summary if isinstance(exc, OmadaApiError) else {}
                status["portal_error"] = str(exc)
                status["details"] = sanitize_summary(response_summary)
        checks = [
            {"key": "portal_url_https", "label": "Portal URL uses HTTPS", "passed": portal_url_https, "message": portal_url if portal_url_https else f"Current portal URL is not HTTPS: {portal_url or '-'}"},
            {"key": "desired_ssids", "label": "Site SSIDs configured", "passed": bool(desired_ssids), "message": ", ".join(desired_ssids) if desired_ssids else "Configure the captive SSID names for this site."},
            {"key": "ssid_portal_binding", "label": "SSID attached to External Portal", "passed": bool(status.get("portal_enabled")), "message": status.get("portal_error") or "Desired SSID(s) are attached to Omada External Portal."},
            {"key": "https_redirect_disabled", "label": "Omada HTTPS Redirect disabled", "passed": not bool(status.get("https_redirect_enabled")), "message": "Omada HTTPS Redirect is disabled to avoid TP-Link self-signed certificate warnings." if not status.get("https_redirect_enabled") else "Disable Omada HTTPS Redirect; keep the external portal URL on HTTPS instead."},
            {"key": "pre_auth_access", "label": "Pre-auth access allows portal/payment/IPTV hosts", "passed": bool(status.get("pre_auth_ready")), "message": status.get("pre_auth_error") or "Pre-auth access includes portal, payment, and IPTV hosts."},
        ]
        status["readiness_checks"] = checks
        failed_required = [item for item in checks if not item.get("passed")]
        status["readiness_status"] = "READY" if not failed_required else "NEEDS_FIX"
        site_portal_status[site_id] = status

    aps = []
    site_ap_counts = {site_id: {"ap_count": 0, "connected_ap_count": 0, "portal_connected_ap_count": 0} for site_id in site_portal_status}
    for row in ap_rows:
        site_id = str(row.get("omada_site_id") or "")
        site_status = site_portal_status.get(site_id) or {
            "site_id": site_id,
            "site_name": row.get("site_name"),
            "desired_ssids": [],
            "vlan_id": None,
            "portal_enabled": False,
            "portal_error": "AP site is not linked to a local site deployment record.",
            "details": {},
        }
        connected = row.get("deployment_status") == "CONNECTED"
        portal_connected = bool(connected and site_status.get("portal_enabled"))
        if site_id in site_ap_counts:
            site_ap_counts[site_id]["ap_count"] += 1
            if connected:
                site_ap_counts[site_id]["connected_ap_count"] += 1
            if portal_connected:
                site_ap_counts[site_id]["portal_connected_ap_count"] += 1
        reason = None
        if not connected:
            reason = f"AP status is {row.get('deployment_status') or 'unknown'}."
        elif not site_status.get("portal_enabled"):
            reason = site_status.get("portal_error") or "SSID is not attached to the Omada portal."
        elif not site_status.get("pre_auth_ready"):
            reason = site_status.get("pre_auth_error") or "Pre-auth access is incomplete."
        aps.append({
            "id": str(row["id"]),
            "name": row.get("display_name"),
            "mac": mask_mac(row.get("mac")),
            "site_id": site_id,
            "site_name": row.get("site_name") or site_status.get("site_name"),
            "ip": row.get("ip_address"),
            "model": row.get("model"),
            "status": row.get("deployment_status"),
            "omada_status": row.get("last_omada_status"),
            "desired_ssids": site_status.get("desired_ssids") or [],
            "vlan_id": site_status.get("vlan_id"),
            "portal_connected": portal_connected,
            "portal_status": "CONNECTED" if portal_connected else "NOT_CONNECTED",
            "reason": reason,
        })
    for site_id, counts in site_ap_counts.items():
        site_status = site_portal_status.get(site_id)
        if not site_status:
            continue
        site_status.update(counts)
        ap_check = {
            "key": "connected_aps",
            "label": "APs visible in site",
            "passed": counts["ap_count"] == 0 or counts["portal_connected_ap_count"] == counts["ap_count"],
            "message": f"{counts['portal_connected_ap_count']}/{counts['ap_count']} AP(s) connected to portal SSID status." if counts["ap_count"] else "No APs are currently tracked for this site.",
        }
        site_status["readiness_checks"] = list(site_status.get("readiness_checks") or []) + [ap_check]
        if site_status.get("readiness_status") == "READY" and not ap_check["passed"]:
            site_status["readiness_status"] = "PARTIAL"
    total = len(aps)
    connected_count = len([item for item in aps if item["portal_connected"]])
    return {
        "total": total,
        "connected": connected_count,
        "not_connected": total - connected_count,
        "aps": aps,
        "sites": list(site_portal_status.values()),
    }


def captive_portal_omada_status_payload() -> dict:
    settings = ensure_captive_portal_settings()
    api_settings = ensure_omada_api_settings()
    bound_stations = fetch_all(
        """
        SELECT id, station_name, station_code, vlan_id, client_network_cidr, omada_site_id, omada_site_name, status
        FROM mikrotik_stations
        WHERE status <> 'ARCHIVED'
          AND (
            NULLIF(TRIM(COALESCE(omada_site_id, '')), '') IS NOT NULL
            OR NULLIF(TRIM(COALESCE(omada_site_name, '')), '') IS NOT NULL
          )
        ORDER BY updated_at DESC
        """
    )
    latest_enable = fetch_one(
        """
        SELECT id, action, status, message, omada_site_id, omada_site_name, ssid_name, station_id, created_at
        FROM captive_portal_test_logs
        WHERE action = ANY(%s)
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (list(OMADA_PORTAL_ENABLE_ACTIONS),),
    )
    latest_success = fetch_one(
        """
        SELECT id, action, status, message, omada_site_id, omada_site_name, ssid_name, station_id, created_at
        FROM captive_portal_test_logs
        WHERE action = ANY(%s) AND status = 'SUCCESS'
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (list(OMADA_PORTAL_ENABLE_ACTIONS),),
    )
    api_configured = bool(api_settings.get("username") and api_settings.get("password_encrypted"))
    selected_site_ready = bool(settings.get("selected_omada_site_id") or settings.get("selected_omada_site_name"))
    portal_coverage = omada_portal_ap_coverage(api_configured)
    portal_total = int(portal_coverage.get("total") or 0)
    portal_connected = int(portal_coverage.get("connected") or 0)
    if not api_configured:
        status = "DOWN"
        message = "Omada API credentials are not configured."
    elif not bound_stations and not selected_site_ready:
        status = "DOWN"
        message = "No MikroTik station is bound to an Omada site yet."
    elif portal_total > 0 and portal_connected == portal_total:
        status = "UP"
        message = f"Omada portal is attached to the expected SSID(s) for {portal_connected}/{portal_total} AP(s)."
    elif portal_total > 0 and portal_connected > 0:
        status = "PARTIAL"
        message = f"Omada portal is attached for {portal_connected}/{portal_total} AP(s). Review APs not connected to portal."
    elif latest_enable and latest_enable.get("status") == "FAILED":
        status = "DOWN"
        message = latest_enable.get("message") or "Latest Omada portal enable attempt failed."
    elif latest_success:
        status = "NEEDS_SETUP"
        message = "Latest portal action succeeded, but no connected AP is currently confirmed against the Omada portal SSID list."
    else:
        status = "NEEDS_SETUP"
        message = "Omada portal has not been enabled from this system yet."
    return {
        "status": status,
        "message": message,
        "api_configured": api_configured,
        "controller": api_settings.get("api_base_url") or api_settings.get("controller_host"),
        "selected_site_id": settings.get("selected_omada_site_id"),
        "selected_site_name": settings.get("selected_omada_site_name"),
        "bound_station_count": len(bound_stations),
        "portal_ap_count": portal_total,
        "portal_ap_connected_count": portal_connected,
        "portal_ap_not_connected_count": int(portal_coverage.get("not_connected") or 0),
        "portal_ap_ratio": f"{portal_connected}/{portal_total}",
        "portal_aps": portal_coverage.get("aps") or [],
        "portal_sites": portal_coverage.get("sites") or [],
        "bound_stations": [
            {
                "id": row.get("id"),
                "station_name": row.get("station_name"),
                "station_code": row.get("station_code"),
                "vlan_id": row.get("vlan_id"),
                "client_network_cidr": row.get("client_network_cidr"),
                "omada_site_id": row.get("omada_site_id"),
                "omada_site_name": row.get("omada_site_name"),
                "status": row.get("status"),
            }
            for row in bound_stations
        ],
        "latest_enable_action": latest_enable,
        "latest_success_action": latest_success,
        "checked_at": datetime.now(timezone.utc),
    }


