PORTAL_LOCAL_PRESENCE_PIXEL = base64.b64decode("R0lGODlhAQABAPAAAP///wAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==")


@app.get("/api/portal/local-presence-pixel")
def portal_local_presence_pixel(request: Request, portal_session_id: Optional[str] = None):
    response = Response(content=PORTAL_LOCAL_PRESENCE_PIXEL, media_type="image/gif")
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Access-Control-Allow-Origin"] = "*"
    response.headers["Access-Control-Allow-Private-Network"] = "true"
    if not portal_session_id or not request:
        return response
    request_station = station_for_client_ip(public_ip(request))
    if not request_station:
        return response
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM portal_sessions WHERE public_session_id = %s", (portal_session_id,))
            session = cur.fetchone()
            if session:
                create_portal_event(
                    cur,
                    session["id"],
                    "LOCAL_PRESENCE_PIXEL",
                    request,
                    "Local 3J WiFi presence pixel loaded.",
                    raw_context={"station_id": str(request_station.get("id")), "station_name": request_station.get("name")},
                )
    return response


@app.post("/api/portal/session")
def create_or_update_portal_session(payload: PortalSessionRequest, request: Request, response: Response):
    handoff_session_id = parse_portal_handoff_token(payload.handoff)
    if handoff_session_id:
        payload = payload.model_copy(update={"portal_session_id": handoff_session_id})
    if not payload.portal_session_id and request.cookies.get(PORTAL_SESSION_COOKIE):
        payload = payload.model_copy(update={"portal_session_id": request.cookies.get(PORTAL_SESSION_COOKIE)})
    if not payload.device_token and request.cookies.get(PORTAL_DEVICE_TOKEN_COOKIE):
        payload = payload.model_copy(update={"device_token": request.cookies.get(PORTAL_DEVICE_TOKEN_COOKIE)})
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            blocked_public = enforce_portal_device_not_blocked(cur, session, payload, request, "PORTAL_SESSION", raise_error=False)
            if blocked_public:
                session = blocked_public["session"]
                blocked_response = {key: value for key, value in blocked_public.items() if key != "session"}
                profile = portal_profile_for_user(cur, session.get("user_id"))
                network_presence = portal_network_presence(session, request, payload)
                device_token = payload.device_token if payload.device_token else None
                set_portal_session_cookies(response, session["public_session_id"], device_token)
                return {
                    "portal_session_id": session["public_session_id"],
                    "device_token": device_token,
                    "status": session["status"],
                    "source": session["source"],
                    "current_barangay": portal_current_barangay(session, payload),
                    "omada_authorization_status": session.get("omada_authorization_status"),
                    "mikrotik_authorization_status": session.get("mikrotik_authorization_status"),
                    "mac_rebind_status": "BLOCKED",
                    "mac_rebind_message": blocked_response["message"],
                    "portal_handoff_url": None,
                    "device_detected": session["source"] in {"OMADA", "MIKROTIK", "UNKNOWN"},
                    "network_presence": network_presence,
                    "profile": public_portal_profile(profile),
                    "pwa_install": public_portal_pwa_install_context(cur, session, profile),
                    "blocked_device": blocked_response,
                }
            create_portal_event(cur, session["id"], "PORTAL_VIEW", request, "Portal viewed", raw_context=payload.model_dump())
            mac_rebind = attempt_portal_device_mac_rebind(cur, session, payload, request)
            device_token = None
            incoming_hash = portal_device_token_hash(payload.device_token)
            if incoming_hash and session.get("device_token_hash") and hmac.compare_digest(str(incoming_hash), str(session["device_token_hash"])):
                device_token = payload.device_token
            profile = portal_profile_for_user(cur, session.get("user_id"))
            network_presence = portal_network_presence(session, request, payload)
            monthly_access = monthly_access_view_for_session(cur, session)
            raw_payload = payload.raw_query_params or {}
            local_bridge_request = str(raw_payload.get("handoff_bridge") or "").strip().lower() in {"1", "true", "yes"}
            handoff_url = portal_handoff_url(session["public_session_id"]) if (
                portal_session_has_current_gateway_access(session)
                or (local_bridge_request and network_presence.get("connected_to_3j_ap") is True)
            ) else None
    set_portal_session_cookies(response, session["public_session_id"], device_token)
    return {
        "portal_session_id": session["public_session_id"],
        "device_token": device_token,
        "status": session["status"],
        "source": session["source"],
        "current_barangay": portal_current_barangay(session, payload),
        "omada_authorization_status": session.get("omada_authorization_status"),
        "mikrotik_authorization_status": session.get("mikrotik_authorization_status"),
        "mac_rebind_status": mac_rebind.get("status"),
        "mac_rebind_message": mac_rebind.get("message"),
        "portal_handoff_url": handoff_url,
        "device_detected": session["source"] in {"OMADA", "MIKROTIK", "UNKNOWN"},
        "network_presence": network_presence,
        "profile": public_portal_profile(profile),
        "monthly_subscriber": (monthly_access or {}).get("monthly_subscriber"),
        "pwa_install": public_portal_pwa_install_context(cur, session, profile),
        "blocked_device": None,
    }


@app.post("/api/portal/profile/send-code")
def portal_profile_send_code(payload: PortalProfileOtpRequest, request: Request):
    normalized_contact, _ = normalize_portal_contact_number(payload.contact_number)
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            user = ensure_portal_user(cur, session)
            cur.execute("SELECT * FROM portal_sessions WHERE id = %s", (session["id"],))
            session = cur.fetchone()
            current_profile = portal_profile_for_user(cur, user["id"])
            if (
                current_profile
                and current_profile.get("contact_verified_at")
                and normalize_a2p_text(current_profile.get("normalized_contact"), 32) == normalized_contact
            ):
                raise HTTPException(status_code=400, detail="This device already has a verified profile with this contact number.")
            cur.execute(
                """
                SELECT id
                FROM portal_customer_profiles
                WHERE normalized_contact = %s
                  AND user_id <> %s
                  AND contact_verified_at IS NOT NULL
                LIMIT 1
                """,
                (normalized_contact, user["id"]),
            )
            if cur.fetchone():
                raise HTTPException(status_code=400, detail="This contact number is already verified for another customer profile.")
            cur.execute(
                """
                SELECT id
                FROM users
                WHERE phone_number = %s
                  AND id <> %s
                LIMIT 1
                """,
                (normalized_contact, user["id"]),
            )
            if cur.fetchone():
                raise HTTPException(status_code=400, detail="This contact number is already used by another account.")
            result = create_portal_contact_verification(cur, session, payload.contact_number, "PROFILE", request)
            return result


@app.post("/api/portal/monthly-login/send-code")
def portal_monthly_login_send_code(payload: PortalMonthlyLoginOtpRequest, request: Request):
    normalized_contact, a2p_destination = normalize_portal_contact_number(payload.contact_number)
    display_contact = portal_contact_display_number(payload.contact_number)
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "MONTHLY_LOGIN_SEND_CODE")
            settings = ensure_monthly_subscriber_settings(cur)
            if not settings.get("integration_enabled", True):
                raise HTTPException(status_code=403, detail="Monthly subscriber login is currently disabled.")
            contact = find_monthly_contact_by_number(cur, payload.contact_number)
            if not contact:
                raise HTTPException(status_code=404, detail="This contact number is not listed as a monthly subscriber.")
            if contact.get("status") != "ACTIVE" or contact.get("subscriber_status") != "ACTIVE":
                raise HTTPException(status_code=403, detail="This monthly subscriber account is not active.")
            ttl_seconds, cooldown_seconds = monthly_login_challenge_settings(settings)
            cur.execute(
                """
                SELECT created_at
                FROM monthly_subscriber_login_challenges
                WHERE normalized_contact = %s
                  AND created_at > now() - make_interval(secs => %s)
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (normalized_contact, cooldown_seconds),
            )
            recent = cur.fetchone()
            if recent:
                elapsed = int((datetime.now(timezone.utc) - aware_utc(recent["created_at"])).total_seconds())
                wait_seconds = max(1, cooldown_seconds - elapsed)
                raise HTTPException(status_code=429, detail=f"Send again ({wait_seconds}s).")
            code = generate_portal_otp()
            expires_at = datetime.now(timezone.utc) + timedelta(seconds=ttl_seconds)
            cur.execute(
                """
                UPDATE monthly_subscriber_login_challenges
                SET status = 'EXPIRED', updated_at = now()
                WHERE normalized_contact = %s AND status = 'PENDING'
                """,
                (normalized_contact,),
            )
            cur.execute(
                """
                INSERT INTO monthly_subscriber_login_challenges(
                    contact_id, portal_session_id, normalized_contact, code_hash, expires_at
                )
                VALUES (%s, %s, %s, %s, %s)
                RETURNING *
                """,
                (contact["id"], session["id"], normalized_contact, monthly_subscriber_login_code_hash(code, normalized_contact), expires_at),
            )
            challenge = cur.fetchone()
            sms_settings = public_portal_sms_confirmation_settings()
            sms_result = send_a2p_sms_message(
                a2p_destination,
                f"Your 3J WiFi monthly subscriber login code is {code}. It expires in {max(1, ttl_seconds // 60)} minutes.",
                source=sms_settings.get("sender_id"),
                purpose="MONTHLY_SUBSCRIBER_LOGIN",
                request_context={"portal_session_id": str(session.get("id")), "challenge_id": str(challenge.get("id"))},
            )
            create_portal_event(
                cur,
                session["id"],
                "MONTHLY_LOGIN_OTP_SENT",
                request,
                f"Monthly subscriber login code sent to {mask_a2p_destination(a2p_destination)}.",
                raw_context={"contact_id": str(contact["id"]), "sms": sanitize_summary(sms_result)},
            )
    return {
        "status": "SENT",
        "message": f"Verification code sent to {display_contact}.",
        "expires_at": expires_at,
        "contact_hint": mask_a2p_destination(a2p_destination),
    }


@app.post("/api/portal/monthly-login/confirm")
def portal_monthly_login_confirm(payload: PortalMonthlyLoginConfirmRequest, request: Request, response: Response):
    normalized_contact, _ = normalize_portal_contact_number(payload.contact_number)
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "MONTHLY_LOGIN_CONFIRM")
            settings = ensure_monthly_subscriber_settings(cur)
            if not settings.get("integration_enabled", True):
                raise HTTPException(status_code=403, detail="Monthly subscriber login is currently disabled.")
            contact = find_monthly_contact_by_number(cur, payload.contact_number)
            if not contact:
                raise HTTPException(status_code=404, detail="This contact number is not listed as a monthly subscriber.")
            if contact.get("status") != "ACTIVE" or contact.get("subscriber_status") != "ACTIVE":
                raise HTTPException(status_code=403, detail="This monthly subscriber account is not active.")
            verify_monthly_login_code(cur, normalized_contact, payload.verification_code)
            user, profile = ensure_monthly_profile_for_contact(cur, session, contact)
            cur.execute("SELECT * FROM portal_sessions WHERE id = %s", (session["id"],))
            session = cur.fetchone()
            binding = bind_monthly_contact_to_session(cur, contact, session, payload, request, user)
            contact = binding["contact"]
            session = binding["session"]
            authorization = authorize_monthly_subscriber_session(cur, session, contact, user, payload)
            session = authorization["session"]
            access_view = monthly_access_view_for_session(cur, session) or portal_session_access_state(cur, session)
            create_portal_event(
                cur,
                session["id"],
                "MONTHLY_LOGIN_SUCCESS" if authorization["authorization"].get("status") != "FAILED" else "MONTHLY_LOGIN_AUTH_FAILED",
                request,
                "Monthly subscriber login completed." if authorization["authorization"].get("status") != "FAILED" else "Monthly subscriber login verified but authorization failed.",
                raw_context={
                    "contact_id": str(contact["id"]),
                    "subscriber_id": str(contact["subscriber_id"]),
                    "authorization": sanitize_summary(authorization["authorization"]),
                },
            )
            if authorization["authorization"].get("status") == "FAILED":
                response_payload = {
                    "status": "FAILED",
                    "message": authorization["authorization"].get("error") or "Monthly subscriber login verified, but WiFi authorization failed.",
                    "portal_session_id": session["public_session_id"],
                    "device_token": binding["device_token"],
                    "profile": public_portal_profile(profile),
                    "monthly_subscriber": public_monthly_subscriber_access(contact),
                }
            else:
                response_payload = {
                    "status": "SUCCESS",
                    "message": "Monthly subscriber access is active.",
                    "portal_session_id": session["public_session_id"],
                    "device_token": binding["device_token"],
                    "profile": public_portal_profile(profile),
                    "monthly_subscriber": public_monthly_subscriber_access(contact),
                    **access_view,
                }
    set_portal_session_cookies(response, response_payload["portal_session_id"], response_payload.get("device_token"))
    return response_payload


@app.post("/api/portal/profile")
def save_portal_profile(payload: PortalProfileSaveRequest, request: Request, response: Response):
    if not payload.terms_accepted:
        raise HTTPException(status_code=400, detail="Accept the terms and customer data consent before saving.")
    display_name = normalize_payment_text(payload.display_name, 120)
    if not display_name:
        raise HTTPException(status_code=400, detail="Name is required.")
    email = normalize_portal_email(payload.email)
    normalized_contact, _ = normalize_portal_contact_number(payload.contact_number)
    display_contact = portal_contact_display_number(payload.contact_number)
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            user = ensure_portal_user(cur, session)
            cur.execute("SELECT * FROM portal_sessions WHERE id = %s", (session["id"],))
            session = cur.fetchone()
            verify_portal_contact_code(cur, payload.contact_number, "PROFILE", payload.verification_code)
            cur.execute(
                """
                SELECT *
                FROM portal_customer_profiles
                WHERE normalized_contact = %s AND user_id <> %s
                LIMIT 1
                """,
                (normalized_contact, user["id"]),
            )
            if cur.fetchone():
                raise HTTPException(status_code=400, detail="This contact number is already verified for another customer profile.")
            existing_profile = portal_profile_for_user(cur, user["id"])
            if existing_profile and existing_profile.get("contact_verified_at"):
                raise HTTPException(status_code=400, detail="Customer profile is already set and cannot be changed.")
            first_profile_save = existing_profile is None
            gift_settings = portal_profile_gift_settings()
            voucher = create_welcome_voucher_if_needed(cur, user, existing_profile, gift_settings) if gift_settings["enabled"] else None
            gift_created_at = datetime.now(timezone.utc) if voucher else None
            gift_status = "AVAILABLE" if voucher else "NONE"
            created_welcome_gift = bool(voucher and not (existing_profile or {}).get("welcome_voucher_id"))
            cur.execute(
                """
                INSERT INTO portal_customer_profiles(
                    user_id, display_name, email, contact_number, normalized_contact, contact_verified_at,
                    terms_accepted_at, marketing_sms_consent, welcome_voucher_id, welcome_gift_status,
                    welcome_gift_created_at, portal_notifications_enabled, portal_notification_interval_seconds
                )
                VALUES (%s, %s, %s, %s, %s, now(), now(), %s, %s, %s, %s, %s, 10)
                ON CONFLICT (user_id) DO UPDATE
                SET display_name = EXCLUDED.display_name,
                    email = EXCLUDED.email,
                    contact_number = EXCLUDED.contact_number,
                    normalized_contact = EXCLUDED.normalized_contact,
                    contact_verified_at = now(),
                    terms_accepted_at = now(),
                    marketing_sms_consent = EXCLUDED.marketing_sms_consent,
                    portal_notifications_enabled = EXCLUDED.portal_notifications_enabled,
                    portal_notification_interval_seconds = EXCLUDED.portal_notification_interval_seconds,
                    welcome_voucher_id = CASE
                        WHEN EXCLUDED.welcome_voucher_id IS NULL THEN portal_customer_profiles.welcome_voucher_id
                        ELSE EXCLUDED.welcome_voucher_id
                    END,
                    welcome_gift_status = CASE
                        WHEN portal_customer_profiles.welcome_gift_status = 'REDEEMED' THEN 'REDEEMED'
                        WHEN EXCLUDED.welcome_voucher_id IS NULL THEN portal_customer_profiles.welcome_gift_status
                        ELSE 'AVAILABLE'
                    END,
                    welcome_gift_created_at = CASE
                        WHEN EXCLUDED.welcome_voucher_id IS NULL THEN portal_customer_profiles.welcome_gift_created_at
                        ELSE COALESCE(portal_customer_profiles.welcome_gift_created_at, EXCLUDED.welcome_gift_created_at, now())
                    END,
                    updated_at = now()
                RETURNING *
                """,
                (
                    user["id"],
                    display_name,
                    email,
                    display_contact,
                    normalized_contact,
                    bool(payload.marketing_sms_consent),
                    voucher["id"] if voucher else None,
                    gift_status,
                    gift_created_at,
                    bool(payload.portal_notifications_enabled),
                ),
            )
            profile = cur.fetchone()
            cur.execute(
                """
                UPDATE users
                SET full_name = %s,
                    email = %s,
                    phone_number = %s,
                    marketing_sms_consent = %s,
                    terms_accepted_at = now(),
                    profile_verified_at = now(),
                    updated_at = now()
                WHERE id = %s
                """,
                (display_name, email, normalized_contact, bool(payload.marketing_sms_consent), user["id"]),
            )
            cur.execute("UPDATE portal_sessions SET user_id = %s, updated_at = now() WHERE id = %s", (user["id"], session["id"]))
            create_portal_event(cur, session["id"], "PROFILE_SAVED", request, "Customer profile saved.", raw_context={"marketing_sms_consent": bool(payload.marketing_sms_consent)})
            if created_welcome_gift:
                create_portal_event(cur, session["id"], "WELCOME_GIFT_CREATED", request, gift_settings["profile_saved_message"], voucher["code"])
            welcome_sms_result = None
            if first_profile_save:
                welcome_sms_result = send_portal_welcome_sms_if_enabled(cur, session, profile, request)
            device_token = ensure_portal_device_token(cur, session, payload.device_token)
            response_message = gift_settings["profile_saved_message"] if profile.get("welcome_gift_status") == "AVAILABLE" else "Profile saved."
    set_portal_session_cookies(response, session["public_session_id"], device_token)
    return {
        "status": "SUCCESS",
        "message": response_message,
        "portal_session_id": session["public_session_id"],
        "device_token": device_token,
        "profile": public_portal_profile(profile),
        "pwa_install": public_portal_pwa_install_context(cur, session, profile),
        "welcome_sms": sanitize_summary(welcome_sms_result or {}),
    }


