@app.post("/api/portal/profile/device-link/qr")
def portal_profile_device_link_qr(payload: PortalDeviceLinkCodeRequest, request: Request):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            profile = portal_profile_for_user(cur, session.get("user_id"))
            if not profile or not profile.get("contact_number") or not profile.get("contact_verified_at"):
                raise HTTPException(status_code=400, detail="Set and verify your customer profile before adding another device.")
            if not portal_session_can_generate_device_link(cur, profile, session):
                raise HTTPException(status_code=400, detail="This linked device cannot add more devices. Generate the QR from the main profile device.")
            cur.execute(
                """
                SELECT created_at
                FROM portal_device_link_codes
                WHERE owner_user_id = %s
                  AND created_at > now() - interval '60 seconds'
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (profile["user_id"],),
            )
            recent = cur.fetchone()
            if recent:
                elapsed = int((datetime.now(timezone.utc) - aware_utc(recent["created_at"])).total_seconds())
                wait_seconds = max(1, 60 - elapsed)
                raise HTTPException(status_code=429, detail=f"Try again after ({wait_seconds}s).")
            code = generate_portal_device_link_code()
            expires_at = datetime.now(timezone.utc) + timedelta(minutes=10)
            cur.execute(
                """
                UPDATE portal_device_link_codes
                SET status = 'EXPIRED', updated_at = now()
                WHERE owner_user_id = %s AND status = 'PENDING'
                """,
                (profile["user_id"],),
            )
            cur.execute(
                """
                INSERT INTO portal_device_link_codes(
                    owner_user_id, owner_profile_id, owner_portal_session_id, code_hash, expires_at
                )
                VALUES (%s, %s, %s, %s, %s)
                RETURNING *
                """,
                (
                    profile["user_id"],
                    profile["id"],
                    session["id"],
                    portal_device_link_code_hash(code),
                    expires_at,
                ),
            )
            link_code = cur.fetchone()
            qr_payload = portal_device_link_qr_payload(code)
            create_portal_event(
                cur,
                session["id"],
                "DEVICE_LINK_QR_CREATED",
                request,
                "Device link QR created.",
                raw_context={"link_code_id": str(link_code["id"])},
            )
    return {
        "status": "SUCCESS",
        "message": "Device QR is ready. Scan it on the other phone within 10 minutes.",
        "expires_at": expires_at,
        "link_code": code,
        "qr_payload": qr_payload,
    }


@app.post("/api/portal/profile/device-link/send-code")
def portal_profile_device_link_send_code(payload: PortalDeviceLinkCodeRequest, request: Request):
    return portal_profile_device_link_qr(payload, request)


@app.post("/api/portal/profile/device-link/confirm")
def portal_profile_device_link_confirm(payload: PortalDeviceLinkConfirmRequest, request: Request, response: Response):
    code_text = extract_portal_device_link_code(payload.link_code)
    with get_conn() as conn:
        with conn.cursor() as cur:
            target_session = ensure_portal_session(cur, payload, request)
            if portal_session_is_device_link_target(cur, target_session):
                create_portal_event(cur, target_session["id"], "DEVICE_LINK_FAILED", request, "Linked device tried to register under another profile.")
                raise HTTPException(status_code=400, detail="This device is already registered under a profile and cannot be registered to another profile.")
            code_hash = portal_device_link_code_hash(code_text)
            cur.execute(
                """
                SELECT *
                FROM portal_device_link_codes
                WHERE code_hash = %s AND status = 'PENDING'
                ORDER BY created_at DESC
                LIMIT 1
                FOR UPDATE
                """,
                (code_hash,),
            )
            link_code = cur.fetchone()
            if not link_code:
                create_portal_event(cur, target_session["id"], "DEVICE_LINK_FAILED", request, "Invalid add-device code.")
                raise HTTPException(status_code=400, detail="Add-device code is invalid or already used.")
            if aware_utc(link_code["expires_at"]) <= datetime.now(timezone.utc):
                cur.execute("UPDATE portal_device_link_codes SET status = 'EXPIRED', updated_at = now() WHERE id = %s", (link_code["id"],))
                create_portal_event(cur, target_session["id"], "DEVICE_LINK_FAILED", request, "Expired add-device code.")
                raise HTTPException(status_code=400, detail="Add-device code expired. Send a new code from your main device.")
            attempts = int(link_code.get("attempts") or 0) + 1
            if attempts > 5:
                cur.execute("UPDATE portal_device_link_codes SET status = 'FAILED', attempts = %s, updated_at = now() WHERE id = %s", (attempts, link_code["id"]))
                create_portal_event(cur, target_session["id"], "DEVICE_LINK_FAILED", request, "Too many add-device attempts.")
                raise HTTPException(status_code=400, detail="Too many incorrect attempts. Send a new code from your main device.")
            cur.execute("SELECT * FROM portal_customer_profiles WHERE user_id = %s", (link_code["owner_user_id"],))
            owner_profile = cur.fetchone()
            if not owner_profile:
                cur.execute("UPDATE portal_device_link_codes SET status = 'FAILED', attempts = %s, updated_at = now() WHERE id = %s", (attempts, link_code["id"]))
                raise HTTPException(status_code=404, detail="The owner profile for this add-device code was not found.")
            previous_profile = portal_profile_for_user(cur, target_session.get("user_id")) if target_session.get("user_id") and str(target_session["user_id"]) != str(owner_profile["user_id"]) else None
            cur.execute(
                """
                UPDATE portal_device_link_codes
                SET status = 'USED',
                    attempts = %s,
                    target_portal_session_id = %s,
                    used_at = now(),
                    updated_at = now()
                WHERE id = %s
                """,
                (attempts, target_session["id"], link_code["id"]),
            )
            cur.execute(
                """
                UPDATE portal_sessions
                SET user_id = %s,
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (owner_profile["user_id"], target_session["id"]),
            )
            target_session = cur.fetchone()
            create_portal_event(
                cur,
                target_session["id"],
                "DEVICE_LINK_SUCCESS",
                request,
                "Device linked to an existing customer profile.",
                raw_context={"owner_profile_id": str(owner_profile["id"]), "link_code_id": str(link_code["id"]), "previous_profile_id": str(previous_profile["id"]) if previous_profile else None},
            )
            device_token = ensure_portal_device_token(cur, target_session, payload.device_token)
            devices = public_portal_profile_devices(cur, owner_profile["user_id"], target_session["id"])
    set_portal_session_cookies(response, target_session["public_session_id"], device_token)
    return {
        "status": "SUCCESS",
        "message": "This device is now linked to your customer profile.",
        "portal_session_id": target_session["public_session_id"],
        "device_token": device_token,
        "profile": public_portal_profile(owner_profile),
        "devices": devices,
    }


@app.post("/api/portal/welcome-gift/redeem")
def redeem_portal_welcome_gift(payload: PortalWelcomeGiftRedeemRequest, request: Request, response: Response):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "WELCOME_GIFT_REDEEM")
            user = ensure_portal_user(cur, session)
            cur.execute("SELECT * FROM portal_sessions WHERE id = %s FOR UPDATE", (session["id"],))
            session = cur.fetchone()
            profile = portal_profile_for_user(cur, user["id"])
            if not profile or profile.get("welcome_gift_status") != "AVAILABLE" or not profile.get("welcome_voucher_id"):
                raise HTTPException(status_code=400, detail="No welcome gift is available for this customer profile.")
            cur.execute("SELECT * FROM vouchers WHERE id = %s FOR UPDATE", (profile["welcome_voucher_id"],))
            voucher = cur.fetchone()
            if not voucher:
                raise HTTPException(status_code=404, detail="Welcome gift voucher was not found.")
            if voucher["status"] != "UNUSED":
                cur.execute(
                    "UPDATE portal_customer_profiles SET welcome_gift_status = 'REDEEMED', welcome_gift_redeemed_at = COALESCE(welcome_gift_redeemed_at, now()), updated_at = now() WHERE id = %s RETURNING *",
                    (profile["id"],),
                )
                profile = cur.fetchone()
                raise HTTPException(status_code=400, detail="Welcome gift was already redeemed.")
            settings = ensure_captive_portal_settings()
            gift_settings = portal_profile_gift_settings(settings)
            duration_seconds, _access_expires_at = voucher_authorization_duration(voucher, settings)
            if int(duration_seconds or 0) <= 0:
                raise HTTPException(status_code=400, detail="Welcome gift has no remaining usable time.")
            item = create_customer_bag_item_from_voucher(
                cur,
                voucher,
                session,
                user,
                int(duration_seconds),
                request,
                source="WELCOME_GIFT",
                product_name=gift_settings["title"],
                product_category_name="Welcome Gift",
                event_type="WELCOME_GIFT_ADDED_TO_BAG",
                event_message="Welcome gift added to customer WiFi bag.",
            )
            cur.execute(
                """
                UPDATE portal_customer_profiles
                SET welcome_gift_status = 'REDEEMED',
                    welcome_gift_redeemed_at = now(),
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (profile["id"],),
            )
            profile = cur.fetchone()
            create_portal_event(
                cur,
                session["id"],
                "WELCOME_GIFT_REDEEMED",
                request,
                "Welcome gift added to My WiFi Bag.",
                voucher["code"],
                {"bag_item_id": str(item["id"]), "source": "WELCOME_GIFT"},
            )
            device_token = ensure_portal_device_token(cur, session, payload.device_token)
            bag = customer_bag_payload(cur, user["id"])
    set_portal_session_cookies(response, session["public_session_id"], device_token)
    return {
        "status": "SUCCESS",
        "message": "Welcome gift added to My WiFi Bag. Open your bag to activate it.",
        "portal_session_id": session["public_session_id"],
        "device_token": device_token,
        "profile": public_portal_profile(profile),
        "bag_item": bag_item_public(item),
        "bag": bag,
        "activation": {"status": "QUEUED", "message": "Welcome gift added to My WiFi Bag."},
    }


