@app.patch("/api/portal/bag/settings")
def update_portal_bag_settings(payload: PortalBagSettingsRequest, request: Request):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "BAG_SETTINGS")
            user = ensure_portal_user(cur, session)
            cur.execute(
                """
                INSERT INTO customer_bag_settings(user_id, auto_activate)
                VALUES (%s, %s)
                ON CONFLICT (user_id) DO UPDATE
                SET auto_activate = EXCLUDED.auto_activate,
                    updated_at = now()
                RETURNING *
                """,
                (user["id"], bool(payload.auto_activate)),
            )
            settings = cur.fetchone()
            create_customer_bag_event(cur, user["id"], None, session["id"], "AUTO_ACTIVATE_UPDATED", "Auto activation setting updated.", bool(settings.get("auto_activate")), bag_overlap_seconds())
            bag_refresh = refresh_customer_bag_for_session(cur, session, request) if bool(settings.get("auto_activate")) else None
            return {
                "status": "SUCCESS",
                "bag": bag_refresh["bag"] if bag_refresh else customer_bag_payload(cur, user["id"]),
                "activation": sanitize_summary((bag_refresh or {}).get("activation")),
            }


@app.post("/api/portal/bag/reorder")
def reorder_portal_bag(payload: PortalBagReorderRequest, request: Request):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "BAG_REORDER")
            user = ensure_portal_user(cur, session)
            clean_ids = []
            for item_id in payload.item_ids or []:
                try:
                    clean_ids.append(str(uuid.UUID(str(item_id))))
                except (TypeError, ValueError):
                    continue
            priority = 100
            for item_id in clean_ids:
                cur.execute(
                    """
                    UPDATE customer_bag_items
                    SET priority = %s,
                        updated_at = now()
                    WHERE id = %s AND user_id = %s AND status = 'QUEUED'
                    """,
                    (priority, item_id, user["id"]),
                )
                priority += 100
            create_customer_bag_event(cur, user["id"], None, session["id"], "QUEUE_REORDERED", "Customer bag queue reordered.", metadata={"item_ids": clean_ids})
            return {"status": "SUCCESS", "bag": customer_bag_payload(cur, user["id"])}


@app.post("/api/portal/bag/items/{item_id}/activate")
def activate_portal_bag_item(item_id: str, payload: PortalBagActivateRequest, request: Request):
    try:
        clean_item_id = str(uuid.UUID(str(item_id)))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Invalid bag item.")
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "BAG_ACTIVATE")
            user = ensure_portal_user(cur, session)
            cur.execute("SELECT * FROM customer_bag_items WHERE id = %s AND user_id = %s FOR UPDATE", (clean_item_id, user["id"]))
            item = cur.fetchone()
            if not item:
                raise HTTPException(status_code=404, detail="Bag item not found.")
            if product_kind_requires_iptv(item.get("product_kind")):
                profile = portal_profile_for_user(cur, user["id"])
                if not portal_profile_is_configured(profile):
                    raise HTTPException(status_code=400, detail="Set your customer profile before activating IPTV access.")
            result = activate_customer_bag_item(cur, item, session, request, "MANUAL")
            if result.get("status") == "FAILED":
                raise HTTPException(status_code=400, detail=result.get("error") or "Could not activate this bag item.")
            return {"status": result.get("status"), "message": result.get("message"), "bag": customer_bag_payload(cur, user["id"])}


@app.post("/api/portal/bag/claim-voucher")
def claim_portal_bag_voucher(payload: PortalBagClaimVoucherRequest, request: Request):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "BAG_CLAIM_VOUCHER")
            user = ensure_portal_user(cur, session)
            voucher, failure = validate_voucher_for_portal(cur, payload.voucher_code)
            if failure:
                create_portal_event(cur, session["id"], "VOUCHER_REDEEM_FAILED", request, failure, payload.voucher_code, {"phase": "bag_claim"})
                raise HTTPException(status_code=400, detail=failure)
            access_allowed, access_error, current_barangay = voucher_access_allowed_for_session(voucher, session, payload)
            if not access_allowed:
                create_portal_event(cur, session["id"], "VOUCHER_REDEEM_FAILED", request, access_error, payload.voucher_code, {"phase": "bag_claim_scope", "current_barangay": current_barangay})
                raise HTTPException(status_code=400, detail=access_error or "This voucher is not allowed in the current Barangay.")
            portal_settings_row = ensure_captive_portal_settings()
            duration_seconds, _access_expires_at = voucher_authorization_duration(voucher, portal_settings_row)
            if int(duration_seconds or 0) <= 0:
                create_portal_event(cur, session["id"], "VOUCHER_REDEEM_FAILED", request, "Voucher has no remaining usable time.", payload.voucher_code, {"phase": "bag_claim_duration"})
                raise HTTPException(status_code=400, detail="Voucher has no remaining usable time.")
            item = create_customer_bag_item_from_voucher(cur, voucher, session, user, int(duration_seconds), request)
            settings = ensure_customer_bag_settings(cur, user["id"])
            activation = {"status": "QUEUED", "message": "Voucher added to My WiFi Bag."}
            cur.execute(
                """
                SELECT 1
                FROM customer_bag_items
                WHERE user_id = %s
                  AND status = 'ACTIVE'
                  AND COALESCE(active_until, now()) > now()
                LIMIT 1
                """,
                (user["id"],),
            )
            active_exists = bool(cur.fetchone())
            if bool(settings.get("auto_activate")) and not active_exists:
                activation = activate_customer_bag_item(cur, item, session, request, "VOUCHER_CLAIM")
                if activation.get("status") == "SUCCESS":
                    item = activation["item"]
                elif activation.get("status") == "FAILED":
                    raise HTTPException(status_code=400, detail=activation.get("error") or "Voucher was added but could not be activated.")
            create_portal_event(cur, session["id"], "VOUCHER_REDEEM_SUCCESS", request, "Voucher added to My WiFi Bag.", payload.voucher_code, {"phase": "bag_claim", "activation": sanitize_summary(activation)})
            device_token = ensure_portal_device_token(cur, session, payload.device_token)
            return {
                "status": "SUCCESS",
                "message": activation.get("message") or "Voucher added to My WiFi Bag.",
                "portal_session_id": session["public_session_id"],
                "device_token": device_token,
                "bag_item": bag_item_public(item),
                "activation": sanitize_summary(activation),
                "bag": customer_bag_payload(cur, user["id"]),
            }


@app.post("/api/portal/iptv/watch")
def create_portal_iptv_watch_session(payload: PortalIptvWatchRequest, request: Request):
    clean_item_id = parse_uuid_or_400(payload.bag_item_id, "bag item")
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "IPTV_WATCH")
            user = ensure_portal_user(cur, session)
            cur.execute(
                """
                SELECT *
                FROM customer_bag_items
                WHERE id = %s
                  AND user_id = %s
                  AND status = 'ACTIVE'
                FOR UPDATE
                """,
                (clean_item_id, user["id"]),
            )
            bag_item = cur.fetchone()
            if not bag_item:
                raise HTTPException(status_code=404, detail="Activate this IPTV pass first before watching.")
            product_kind = normalize_product_kind(bag_item.get("product_kind"))
            if not product_kind_requires_iptv(product_kind):
                raise HTTPException(status_code=400, detail="This item does not include IPTV access.")
            profile = portal_profile_for_user(cur, user["id"])
            if not portal_profile_is_configured(profile):
                raise HTTPException(status_code=400, detail="Set your customer profile before watching IPTV.")
            if bag_item.get("iptv_status") != "PROVISIONED" or not bag_item.get("iptv_account_id"):
                raise HTTPException(status_code=400, detail="IPTV access is not ready yet. Please ask the operator to check provisioning.")
            cur.execute("SELECT * FROM iptv_accounts WHERE id = %s", (bag_item["iptv_account_id"],))
            account = cur.fetchone()
            if not account or account.get("status") != "PROVISIONED":
                raise HTTPException(status_code=400, detail="IPTV account is not ready yet.")
            now = datetime.now(timezone.utc)
            active_until = aware_utc(bag_item.get("active_until"))
            if not active_until or active_until <= now:
                raise HTTPException(status_code=400, detail="IPTV access has expired.")
            expires_at = aware_utc(account.get("expires_at"))
            if expires_at and expires_at + timedelta(seconds=5) < active_until:
                try:
                    coverage = ensure_iptv_account_covers_bag_item(cur, bag_item, reason="WATCH")
                except Exception as exc:
                    raise HTTPException(status_code=400, detail=normalize_iptv_text(str(exc), 700) or "IPTV account expiry could not be synced.") from exc
                if coverage.get("status") in {"COVERED", "PROVISIONED"}:
                    account = coverage.get("account") or account
                    bag_item = coverage.get("bag_item") or bag_item
                    expires_at = aware_utc(account.get("expires_at"))
                else:
                    raise HTTPException(status_code=400, detail=coverage.get("error") or "IPTV access could not be synced.")
            if expires_at and expires_at <= now:
                raise HTTPException(status_code=400, detail="IPTV access has expired.")
            route_preference = iptv_route_preference(payload.route_preference)
            network_presence = portal_network_presence(session, request, payload, force_omada_lookup=True)
            token = create_iptv_watch_token(cur, session, bag_item, account, network_presence, route_preference)
            cur.execute(
                """
                UPDATE customer_bag_items
                SET iptv_watch_url = %s,
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (token["watch_url"], bag_item["id"]),
            )
            bag_item = cur.fetchone()
            create_customer_bag_event(
                cur,
                user["id"],
                bag_item["id"],
                session["id"],
                "IPTV_WATCH_TOKEN_CREATED",
                "Short-lived IPTV watch token created.",
                metadata={"expires_at": token["expires_at"].isoformat() if token.get("expires_at") else None},
            )
            return {
                "status": "SUCCESS",
                "watch_url": token["watch_url"],
                "fallback_watch_url": token.get("fallback_watch_url"),
                "route_mode": token.get("route_mode"),
                "route_preference": route_preference,
                "network_presence": network_presence,
                "token_expires_at": token["expires_at"],
                "ttl_minutes": token["ttl_minutes"],
                "account": iptv_account_public(account),
                "bag_item": bag_item_public(bag_item),
            }


@app.post("/api/iptv/session/status")
def check_iptv_login_token_status(payload: IptvTokenResolvePayload):
    expected_secret = iptv_integration_secret()
    provided_secret = payload.integration_secret or ""
    if not hmac.compare_digest(provided_secret, expected_secret):
        raise HTTPException(status_code=403, detail="Invalid IPTV integration secret.")
    notice_settings = iptv_runtime_notice_settings()
    token_hash = iptv_token_hash(payload.token)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT t.*, a.xui_username, a.expires_at AS account_expires_at,
                       a.status AS account_status, a.all_bouquets, a.max_connections,
                       i.product_name, i.product_kind, i.iptv_status, i.status AS bag_status,
                       i.active_until AS bag_active_until
                FROM iptv_login_tokens t
                JOIN iptv_accounts a ON a.id = t.iptv_account_id
                JOIN customer_bag_items i ON i.id = t.bag_item_id
                WHERE t.token_hash = %s
                """,
                (token_hash,),
            )
            row = cur.fetchone()
            if not row:
                return {
                    "status": "REVOKED",
                    "allowed": False,
                    "reason_code": "TOKEN_NOT_FOUND",
                    "message": "IPTV access is no longer available.",
                    "remaining_seconds": 0,
                    "warning_seconds": notice_settings["warning_seconds"],
                    "warning_minutes": notice_settings["warning_minutes"],
                    "stop_seconds": notice_settings["stop_seconds"],
                    "warning_active": False,
                    "force_stop": True,
                    "portal_url": notice_settings["portal_url"],
                }
            now = datetime.now(timezone.utc)
            bag_active_until = aware_utc(row.get("bag_active_until"))
            account_expiry = aware_utc(row.get("account_expires_at"))
            reason_code = None
            message = None
            allowed = True
            if row.get("bag_status") != "ACTIVE":
                allowed = False
                reason_code = "ACCESS_NOT_ACTIVE"
                message = "This IPTV pass is no longer active."
            elif row.get("iptv_status") != "PROVISIONED" or row.get("account_status") != "PROVISIONED":
                allowed = False
                reason_code = "LINE_REVOKED"
                message = "This IPTV line was removed or is no longer provisioned."
            elif not bag_active_until or bag_active_until <= now:
                allowed = False
                reason_code = "ACCESS_EXPIRED"
                message = "Your IPTV access time is fully consumed."
            elif account_expiry and account_expiry <= now:
                allowed = False
                reason_code = "LINE_EXPIRED"
                message = "This IPTV line has expired."
            remaining_seconds = max(int((bag_active_until - now).total_seconds()), 0) if bag_active_until else 0
            warning_seconds = int(notice_settings["warning_seconds"])
            stop_seconds = int(notice_settings["stop_seconds"])
            warning_active = bool(allowed and warning_seconds > 0 and remaining_seconds <= warning_seconds)
            force_stop = bool(allowed and stop_seconds > 0 and remaining_seconds <= stop_seconds)
            return {
                "status": "STOPPING" if force_stop else ("ACTIVE" if allowed else "RESTRICTED"),
                "allowed": allowed,
                "reason_code": reason_code,
                "message": message or "IPTV access is active.",
                "remaining_seconds": remaining_seconds if allowed else 0,
                "warning_seconds": warning_seconds,
                "warning_minutes": int(notice_settings["warning_minutes"]),
                "stop_seconds": stop_seconds,
                "warning_active": warning_active,
                "force_stop": force_stop,
                "portal_url": notice_settings["portal_url"],
                "access_expires_at": bag_active_until,
                "account_expires_at": account_expiry,
                "product_name": row.get("product_name"),
                "product_kind": row.get("product_kind") or "IPTV",
                "xui_username": row.get("xui_username"),
                "all_bouquets": bool(row.get("all_bouquets")),
                "max_connections": int(row.get("max_connections") or 1),
            }


@app.post("/api/iptv/session/login-failure")
def report_iptv_login_failure(payload: IptvLoginFailureReportPayload, request: Request):
    expected_secret = iptv_integration_secret()
    provided_secret = payload.integration_secret or ""
    if not hmac.compare_digest(provided_secret, expected_secret):
        raise HTTPException(status_code=403, detail="Invalid IPTV integration secret.")
    notification_id = create_iptv_login_failure_notification(
        token=payload.token,
        stage=payload.stage or "IPTV_WEB_HANDOFF",
        reason_code=payload.reason_code or "IPTV_WEB_LOGIN_FAILED",
        message=payload.message or "The IPTV web app could not complete customer login.",
        source_url=payload.source_url or "",
        checked_urls=payload.checked_urls,
        metadata=payload.metadata or {},
        request=request,
        severity="DANGER",
    )
    return {"status": "OK", "notification_id": notification_id}


@app.post("/api/iptv/session/resolve")
def resolve_iptv_login_token(payload: IptvTokenResolvePayload, request: Request):
    expected_secret = iptv_integration_secret()
    provided_secret = payload.integration_secret or ""
    if not hmac.compare_digest(provided_secret, expected_secret):
        raise HTTPException(status_code=403, detail="Invalid IPTV integration secret.")
    token_hash = iptv_token_hash(payload.token)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT t.*, a.xui_username, a.xui_password_encrypted, a.expires_at AS account_expires_at,
                       a.status AS account_status, a.all_bouquets, a.max_connections,
                       i.product_name, i.product_kind, i.iptv_status, i.active_until AS bag_active_until,
                       p.display_name, p.contact_number, p.email
                FROM iptv_login_tokens t
                JOIN iptv_accounts a ON a.id = t.iptv_account_id
                JOIN customer_bag_items i ON i.id = t.bag_item_id
                LEFT JOIN portal_customer_profiles p ON p.user_id = t.user_id
                WHERE t.token_hash = %s
                  AND t.expires_at > now()
                FOR UPDATE OF t
                """,
                (token_hash,),
            )
            row = cur.fetchone()
            if not row:
                create_iptv_login_failure_notification(
                    token=payload.token,
                    stage="HOTSPOT_TOKEN_RESOLVE",
                    reason_code="TOKEN_NOT_FOUND",
                    message="IPTV token was not found or has expired while a customer attempted to open IPTV.",
                    request=request,
                    severity="WARNING",
                )
                raise HTTPException(status_code=404, detail="IPTV token was not found or has expired.")
            if row.get("account_status") != "PROVISIONED" or row.get("iptv_status") != "PROVISIONED":
                create_iptv_login_failure_notification(
                    token=payload.token,
                    stage="HOTSPOT_TOKEN_RESOLVE",
                    reason_code="ACCOUNT_NOT_PROVISIONED",
                    message="IPTV token resolved, but the linked XUI account or bag item is not provisioned.",
                    metadata={
                        "account_status": row.get("account_status"),
                        "iptv_status": row.get("iptv_status"),
                        "bag_item_id": str(row.get("bag_item_id") or ""),
                        "user_id": str(row.get("user_id") or ""),
                    },
                    request=request,
                    severity="DANGER",
                )
                raise HTTPException(status_code=400, detail="IPTV account is not provisioned.")
            now = datetime.now(timezone.utc)
            account_expiry = aware_utc(row.get("account_expires_at"))
            bag_active_until = aware_utc(row.get("bag_active_until"))
            if account_expiry and account_expiry <= now and bag_active_until and bag_active_until > now:
                cur.execute("SELECT * FROM customer_bag_items WHERE id = %s FOR UPDATE", (row["bag_item_id"],))
                repair_item = cur.fetchone()
                if repair_item:
                    try:
                        repair_result = ensure_iptv_account_covers_bag_item(cur, repair_item, reason="TOKEN_RESOLVE")
                    except Exception as exc:
                        create_iptv_login_failure_notification(
                            token=payload.token,
                            stage="HOTSPOT_TOKEN_RESOLVE",
                            reason_code="ACCOUNT_REPAIR_FAILED",
                            message=normalize_iptv_text(str(exc), 700) or "IPTV account expiry could not be synced during customer login.",
                            metadata={
                                "bag_item_id": str(row.get("bag_item_id") or ""),
                                "user_id": str(row.get("user_id") or ""),
                            },
                            request=request,
                            severity="DANGER",
                        )
                        raise HTTPException(status_code=400, detail=normalize_iptv_text(str(exc), 700) or "IPTV account expiry could not be synced.") from exc
                    repair_account = repair_result.get("account") if repair_result.get("status") in {"COVERED", "PROVISIONED"} else None
                    if repair_account:
                        row["account_expires_at"] = repair_account.get("expires_at")
                        row["xui_username"] = repair_account.get("xui_username") or row.get("xui_username")
                        row["xui_password_encrypted"] = repair_account.get("xui_password_encrypted") or row.get("xui_password_encrypted")
                        account_expiry = aware_utc(repair_account.get("expires_at"))
            if account_expiry and account_expiry <= now:
                create_iptv_login_failure_notification(
                    token=payload.token,
                    stage="HOTSPOT_TOKEN_RESOLVE",
                    reason_code="ACCOUNT_EXPIRED",
                    message="IPTV token resolved, but the linked XUI account is expired.",
                    metadata={
                        "account_expires_at": row.get("account_expires_at"),
                        "bag_active_until": row.get("bag_active_until"),
                        "bag_item_id": str(row.get("bag_item_id") or ""),
                        "user_id": str(row.get("user_id") or ""),
                    },
                    request=request,
                    severity="WARNING",
                )
                raise HTTPException(status_code=400, detail="IPTV account has expired.")
            password = decrypt_secret(row.get("xui_password_encrypted"))
            if not password:
                create_iptv_login_failure_notification(
                    token=payload.token,
                    stage="HOTSPOT_TOKEN_RESOLVE",
                    reason_code="ACCOUNT_PASSWORD_UNAVAILABLE",
                    message="IPTV token resolved, but the XUI account credential could not be decrypted.",
                    metadata={
                        "bag_item_id": str(row.get("bag_item_id") or ""),
                        "user_id": str(row.get("user_id") or ""),
                    },
                    request=request,
                    severity="DANGER",
                )
                raise HTTPException(status_code=500, detail="IPTV account credential is unavailable.")
            cur.execute("UPDATE iptv_login_tokens SET used_at = now() WHERE id = %s", (row["id"],))
            store = iptv_store()
            return {
                "status": "SUCCESS",
                "xui_base_url": store.get("xui_base_url"),
                "xui_public_url": store.get("xui_public_url"),
                "xui_server_host": store.get("xui_server_host"),
                "username": row.get("xui_username"),
                "password": password,
                "expires_at": row.get("bag_active_until") or row.get("account_expires_at"),
                "access_expires_at": row.get("bag_active_until"),
                "account_expires_at": row.get("account_expires_at"),
                "all_bouquets": bool(row.get("all_bouquets")),
                "max_connections": int(row.get("max_connections") or 1),
                "product_name": row.get("product_name"),
                "product_kind": row.get("product_kind") or "IPTV",
                "customer": {
                    "display_name": row.get("display_name"),
                    "contact_number": row.get("contact_number"),
                    "email": row.get("email"),
                },
            }



def payment_checkout_method(store: dict, value: str) -> str:
    methods = payment_enabled_checkout_methods(store)
    if not methods:
        raise HTTPException(status_code=400, detail="Enable at least one PayMongo checkout method before accepting online payments")
    return PAYMONGO_HOSTED_CHECKOUT_METHOD


@app.post("/api/portal/payments/checkout-access")
def portal_payment_checkout_access(payload: PortalPaymentCheckoutRequest, request: Request):
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "PAYMENT_CHECKOUT_ACCESS")
            user = ensure_portal_user(cur, session)
            profile = portal_profile_for_user(cur, user["id"])
            cleanup_expired_omada_payment_auth_free_grants(cur, limit=20)
            access_status = omada_payment_auth_free_abuse_status(cur, session, user, profile, payload, request)
    return {
        "status": "SUCCESS",
        "checkout_access": access_status,
        "portal_session_id": session["public_session_id"],
        "profile": public_portal_profile(profile),
    }


@app.post("/api/portal/payments/checkout")
def create_portal_payment_checkout(payload: PortalPaymentCheckoutRequest, request: Request):
    store = payment_gateway_store()
    active_credentials = payment_gateway_active_credentials(store)
    if not store.get("enabled"):
        raise HTTPException(status_code=400, detail="Online payments are not enabled")
    if store.get("provider") != "PAYMONGO":
        raise HTTPException(status_code=400, detail="Only PayMongo payments are supported")
    method = payment_checkout_method(store, payload.payment_method)
    enabled_checkout_methods = payment_enabled_checkout_methods(store)
    if not active_credentials.get("secret_key"):
        raise HTTPException(status_code=400, detail=f"PayMongo {active_credentials['mode']} secret key is not configured")

    checkout_error = None
    response_payload = None
    with get_conn() as conn:
        with conn.cursor() as cur:
            session = ensure_portal_session(cur, payload, request)
            enforce_portal_device_not_blocked(cur, session, payload, request, "PAYMENT_CHECKOUT")
            user = ensure_portal_user(cur, session)
            profile = portal_profile_for_user(cur, user["id"])
            cleanup_expired_omada_payment_auth_free_grants(cur, limit=20)
            enforce_omada_payment_auth_free_abuse_limit(cur, session, user, profile, payload, request)
            network_presence = portal_network_presence(session, request, payload)
            outside_network_purchase = (
                bool(payload.outside_network_purchase)
                or network_presence.get("connected_to_3j_ap") is False
            )
            if outside_network_purchase and not portal_profile_is_configured(profile):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "Set up your customer profile before buying outside 3J WiFi. "
                        "Outside-network purchases are saved to your profile so your package can be recovered."
                    ),
                )
            customer_name = normalize_payment_text((profile or {}).get("display_name") or user.get("full_name"), 120) or None
            customer_email = normalize_portal_email((profile or {}).get("email") or user.get("email")) or None
            customer_contact = normalize_payment_text((profile or {}).get("contact_number") or user.get("phone_number"), 32) or None
            cur.execute(
                """
                SELECT p.*
                FROM product_items p
                WHERE p.id = %s
                  AND p.status = 'ACTIVE'
                """,
                (payload.product_item_id,),
            )
            product = cur.fetchone()
            if not product:
                raise HTTPException(status_code=404, detail="Product item not found or disabled")
            product["discounts"] = product_item_discount_rows([str(product["id"])], active_only=True)
            product_kind = normalize_product_kind(product.get("product_kind"))
            if product_kind_requires_iptv(product_kind) and not portal_profile_is_configured(profile):
                raise HTTPException(status_code=400, detail="Set your customer profile before buying IPTV. IPTV access needs a verified profile for account creation and recovery.")
            site_row = site_deployment_for_portal_context(session, payload)
            current_barangay = normalize_barangay_label((site_row or {}).get("barangay"))
            selected_category_id = normalize_product_category_id(payload.product_category_id) or normalize_product_category_id(product.get("category_id"))
            category_row = None
            if selected_category_id:
                cur.execute(
                    """
                    SELECT c.*
                    FROM product_categories c
                    JOIN product_category_item_assignments pcia ON pcia.category_id = c.id
                    WHERE c.id = %s
                      AND pcia.item_id = %s
                      AND c.status = 'ACTIVE'
                      AND pcia.status = 'ACTIVE'
                    """,
                    (selected_category_id, product["id"]),
                )
                category_row = cur.fetchone()
                if not category_row:
                    raise HTTPException(status_code=400, detail="Selected product category is not available for this item.")
            elif product.get("category_id"):
                category_row = product_category_for_payload(cur, product.get("category_id"), active_only=True)
            if category_row:
                product["category_id"] = category_row["id"]
                product["category_name"] = category_row.get("name")
                product["category_description"] = category_row.get("description")
                product["category_access_scope"] = category_row.get("access_scope")
                product["category_allowed_barangay"] = category_row.get("allowed_barangay")
            category_access_scope = normalize_product_access_scope(product.get("category_access_scope") or "ALL_LOCATIONS")
            selected_barangay = normalize_barangay_label(payload.selected_barangay)
            legacy_category_barangay = normalize_barangay_label(product.get("category_allowed_barangay"))
            category_barangay = None
            if category_access_scope == "BARANGAY_ONLY":
                category_barangay = selected_barangay or current_barangay or legacy_category_barangay
                if not category_barangay:
                    raise HTTPException(status_code=400, detail="Choose a Barangay for this Barangay-only package.")
                if current_barangay and barangay_key(category_barangay) != barangay_key(current_barangay):
                    raise HTTPException(
                        status_code=403,
                        detail=f"You are currently connected in {current_barangay}. Choose {current_barangay} for immediate access.",
                    )
            checkout_amount = product_checkout_amount(product, payload.purchase_quantity)
            amount_centavos = checkout_amount["amount_centavos"]
            duration_unit = normalize_product_duration_unit(product["duration_unit"])
            duration_seconds = product_duration_seconds(product["duration_value"], duration_unit) * checkout_amount["quantity"]
            speed = speed_limit_snapshot(product)
            public_order_id = generate_payment_order_public_id()
            for _ in range(10):
                cur.execute("SELECT 1 FROM payment_orders WHERE public_order_id = %s", (public_order_id,))
                if not cur.fetchone():
                    break
                public_order_id = generate_payment_order_public_id()
            cur.execute(
                """
                INSERT INTO payment_orders(
                    public_order_id, provider, provider_mode, product_item_id, portal_session_id, user_id,
                    status, fulfillment_status, payment_method, amount_centavos, base_amount_centavos,
                    purchase_quantity, discount_type, discount_value, discount_amount_centavos, currency, product_name,
                    product_description, duration_seconds, product_category_id,
                    product_category_name, product_category_access_scope, product_category_barangay,
                    product_kind, iptv_package_label, iptv_xui_package_id,
                    speed_limit_enabled, speed_download_mbps, speed_upload_mbps,
                    client_mac, client_ip, user_agent,
                    customer_name, customer_email, customer_contact_number, outside_network_purchase
                )
                VALUES (
                    %s, 'PAYMONGO', %s, %s, %s, %s,
                    'PENDING', 'PENDING', %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s,
                    %s, %s, %s,
                    %s, %s, %s, NULLIF(%s, '')::inet, %s,
                    %s, %s, %s, %s
                )
                RETURNING *
                """,
                (
                    public_order_id,
                    active_credentials["mode"],
                    product["id"],
                    session["id"],
                    user["id"],
                    method,
                    amount_centavos,
                    checkout_amount["base_amount_centavos"],
                    checkout_amount["quantity"],
                    checkout_amount["discount_type"],
                    checkout_amount["discount_value"],
                    checkout_amount["discount_amount_centavos"],
                    store.get("currency"),
                    product["name"],
                    product.get("description"),
                    duration_seconds,
                    product.get("category_id"),
                    product.get("category_name"),
                    category_access_scope,
                    category_barangay,
                    product_kind,
                    normalize_payment_text(product.get("iptv_package_label"), 160) or None,
                    normalize_payment_text(product.get("iptv_xui_package_id"), 160) or None,
                    speed["speed_limit_enabled"],
                    speed["speed_download_mbps"],
                    speed["speed_upload_mbps"],
                    session.get("client_mac") or session.get("omada_client_mac") or session.get("mikrotik_client_mac"),
                    str(session.get("client_ip") or public_ip(request) or ""),
                    request.headers.get("user-agent"),
                    customer_name,
                    customer_email,
                    customer_contact,
                    outside_network_purchase,
                ),
            )
            order = cur.fetchone()
            try:
                checkout = paymongo_create_checkout_session(store, active_credentials["secret_key"], order, session)
                checkout_data = checkout.get("data") if isinstance(checkout.get("data"), dict) else {}
                checkout_attributes = checkout_data.get("attributes") if isinstance(checkout_data.get("attributes"), dict) else {}
                checkout_session_id = checkout_data.get("id")
                checkout_url = checkout_attributes.get("checkout_url") or checkout_attributes.get("url")
                if not checkout_url:
                    raise HTTPException(status_code=502, detail="PayMongo did not return a checkout URL")
                cur.execute(
                    """
                    UPDATE payment_orders
                    SET status = 'CHECKOUT_CREATED',
                        checkout_session_id = %s,
                        checkout_url = %s,
                        provider_response_json = %s,
                        last_error = NULL,
                        updated_at = now()
                    WHERE id = %s
                    RETURNING *
                    """,
                    (checkout_session_id, checkout_url, Json(sanitize_summary(checkout)), order["id"]),
                )
                order = cur.fetchone()
                auth_free_grant = create_omada_payment_auth_free_grant(cur, order, session, user, profile, payload, request)
                create_portal_event(cur, session["id"], "PAYMENT_CHECKOUT_CREATED", request, "PayMongo checkout created", raw_context={"payment_order_id": public_order_id, "product_item_id": str(product["id"]), "method": method, "payment_method_types": enabled_checkout_methods, "category": product.get("category_name"), "current_barangay": current_barangay})
                response_payload = {
                    "status": "CHECKOUT_CREATED",
                    "payment_order_id": order["public_order_id"],
                    "checkout_url": order["checkout_url"],
                    "provider": order["provider"],
                    "mode": order["provider_mode"],
                    "payment_method": order["payment_method"],
                    "payment_method_types": enabled_checkout_methods,
                    "amount_centavos": order["amount_centavos"],
                    "base_amount_centavos": order.get("base_amount_centavos"),
                    "purchase_quantity": order.get("purchase_quantity") or 1,
                    "discount_type": order.get("discount_type"),
                    "discount_value": float(order.get("discount_value") or 0),
                    "discount_amount_centavos": order.get("discount_amount_centavos") or 0,
                    "currency": order["currency"],
                    "product_name": order["product_name"],
                    "product_kind": order.get("product_kind") or "WIFI",
                    "product_kind_label": product_kind_label(order.get("product_kind")),
                    "iptv_enabled": product_kind_requires_iptv(order.get("product_kind")),
                    "iptv_package_label": order.get("iptv_package_label"),
                    "product_category_name": order.get("product_category_name"),
                    "product_category_access_scope": order.get("product_category_access_scope"),
                    "product_category_barangay": order.get("product_category_barangay"),
                    "outside_network_purchase": bool(order.get("outside_network_purchase")),
                    "portal_session_id": session["public_session_id"],
                    "payment_access_grant": omada_payment_auth_free_public_grant(auth_free_grant),
                }
            except HTTPException as exc:
                checkout_error = exc
                cur.execute(
                    """
                    UPDATE payment_orders
                    SET status = 'FAILED',
                        fulfillment_status = 'FAILED',
                        last_error = %s,
                        updated_at = now()
                    WHERE id = %s
                    """,
                    (str(exc.detail), order["id"]),
                )
                create_portal_event(cur, session["id"], "PAYMENT_CHECKOUT_FAILED", request, str(exc.detail), raw_context={"payment_order_id": public_order_id, "product_item_id": str(product["id"]), "method": method, "payment_method_types": enabled_checkout_methods})
    if checkout_error:
        raise checkout_error
    return response_payload


@app.get("/api/portal/payments/{public_order_id}/status")
def portal_payment_status(public_order_id: str, request: Request, response: Response):
    normalized_order_id = normalize_payment_text(public_order_id, 120)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cleanup_expired_omada_payment_auth_free_grants(cur, limit=20)
            cur.execute("SELECT * FROM payment_orders WHERE public_order_id = %s FOR UPDATE", (normalized_order_id,))
            order = cur.fetchone()
            if order and order.get("portal_session_id"):
                create_portal_event(cur, order["portal_session_id"], "PAYMENT_STATUS_VIEW", request, "Payment status viewed", raw_context={"payment_order_id": order["public_order_id"]})
            if order and order.get("status") in {"PENDING", "CHECKOUT_CREATED"}:
                try:
                    order = sync_paymongo_checkout_status(cur, order, request)
                except HTTPException as exc:
                    cur.execute(
                        """
                        UPDATE payment_orders
                        SET last_error = %s,
                            updated_at = now()
                        WHERE id = %s
                        RETURNING *
                        """,
                        (str(exc.detail), order["id"]),
                    )
                    order = cur.fetchone()
                except Exception as exc:
                    cur.execute(
                        """
                        UPDATE payment_orders
                        SET last_error = %s,
                            updated_at = now()
                        WHERE id = %s
                        RETURNING *
                        """,
                        (str(exc), order["id"]),
                    )
                    order = cur.fetchone()
            if order and order.get("status") == "PAID" and order.get("fulfillment_status") == "FULFILLED" and order.get("portal_session_id"):
                device_token = issue_portal_device_token_for_session(cur, order["portal_session_id"])
                if device_token:
                    order["_device_token"] = device_token
                cur.execute("SELECT public_session_id FROM portal_sessions WHERE id = %s", (order["portal_session_id"],))
                session_row = cur.fetchone()
                if session_row:
                    order["_portal_session_public_id"] = session_row["public_session_id"]
                    order["_portal_handoff_url"] = portal_handoff_url(session_row["public_session_id"])
                    set_portal_session_cookies(response, session_row["public_session_id"], device_token)
                cur.execute("SELECT * FROM portal_sessions WHERE id = %s", (order["portal_session_id"],))
                paid_session = cur.fetchone()
                remove_paid_omada_payment_auth_free_grants_for_session(cur, paid_session, request, "PAYMENT_STATUS_VIEW")
            if order:
                cur.execute(
                    """
                    SELECT *
                    FROM omada_payment_auth_free_grants
                    WHERE payment_order_id = %s
                    ORDER BY expires_at DESC, created_at DESC
                    LIMIT 1
                    """,
                    (order["id"],),
                )
                order["_payment_access_grant"] = omada_payment_auth_free_public_grant(cur.fetchone())
                order["_bag_item"] = customer_bag_item_for_payment(cur, order["id"])
    return payment_order_status_payload(order)


@app.post("/api/portal/payments/{public_order_id}/cancel")
def cancel_portal_payment(public_order_id: str, payload: PortalPaymentCancelRequest, request: Request):
    normalized_order_id = normalize_payment_text(public_order_id, 120)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM payment_orders WHERE public_order_id = %s FOR UPDATE", (normalized_order_id,))
            order = cur.fetchone()
            if not order:
                return {"found": False, "status": "NOT_FOUND", "message": "Payment checkout was not found."}
            if order.get("status") == "PAID":
                order["_bag_item"] = customer_bag_item_for_payment(cur, order["id"])
                return {**payment_order_status_payload(order), "message": "Payment was already paid and cannot be cancelled."}

            session = ensure_portal_session(cur, payload, request)
            same_session = bool(order.get("portal_session_id") and order.get("portal_session_id") == session.get("id"))
            same_user = False
            if order.get("user_id"):
                user = ensure_portal_user(cur, session)
                same_user = bool(user and order.get("user_id") == user.get("id"))
            if not (same_session or same_user):
                raise HTTPException(status_code=403, detail="This payment checkout belongs to another portal session.")

            if order.get("status") in {"PENDING", "CHECKOUT_CREATED"}:
                if order.get("checkout_session_id"):
                    try:
                        order = sync_paymongo_checkout_status(cur, order, request)
                    except Exception as exc:
                        cur.execute(
                            """
                            UPDATE payment_orders
                            SET last_error = %s,
                                updated_at = now()
                            WHERE id = %s
                            RETURNING *
                            """,
                            (str(exc), order["id"]),
                        )
                        order = cur.fetchone()
                if order.get("status") == "PAID":
                    order["_bag_item"] = customer_bag_item_for_payment(cur, order["id"])
                    return {**payment_order_status_payload(order), "message": "Payment was already paid and cannot be cancelled."}
                expire_payload = None
                expire_error = ""
                if order.get("checkout_session_id") and order.get("provider") == "PAYMONGO":
                    try:
                        store = payment_gateway_store()
                        credentials = payment_gateway_active_credentials(store, order.get("provider_mode") or store.get("mode"))
                        expire_payload = paymongo_expire_checkout_session(store, credentials.get("secret_key"), order.get("checkout_session_id"))
                    except Exception as exc:
                        expire_error = normalize_payment_text(str(exc), 500)
                        if "already expired" in expire_error.lower():
                            expire_payload = {"status": "already_expired", "message": expire_error}
                            expire_error = ""
                cur.execute(
                    """
                    UPDATE payment_orders
                    SET status = 'CANCELLED',
                        fulfillment_status = 'NOT_REQUIRED',
                        provider_response_json = COALESCE(%s::jsonb, provider_response_json),
                        last_error = %s,
                        updated_at = now()
                    WHERE id = %s
                    RETURNING *
                    """,
                    (
                        Json(sanitize_summary(expire_payload)) if expire_payload else None,
                        f"Checkout cancelled by customer. PayMongo expire failed: {expire_error}" if expire_error else "Checkout cancelled by customer.",
                        order["id"],
                    ),
                )
                order = cur.fetchone()
                if order.get("portal_session_id"):
                    create_portal_event(
                        cur,
                        order["portal_session_id"],
                        "PAYMENT_CHECKOUT_CANCELLED",
                        request,
                        "PayMongo checkout cancelled by customer.",
                        raw_context={"payment_order_id": order["public_order_id"]},
                    )
                finalize_omada_payment_auth_free_grants_for_order(cur, order, final_status="CANCELLED")
            order["_bag_item"] = customer_bag_item_for_payment(cur, order["id"])
    return {**payment_order_status_payload(order), "message": "Payment checkout cancelled."}


def payment_fulfillment_payload_from_session(session: dict, voucher_code: str) -> PortalRedeemRequest:
    raw_params = session.get("raw_query_params") if isinstance(session.get("raw_query_params"), dict) else {}
    return PortalRedeemRequest(
        portal_session_id=session.get("public_session_id"),
        voucher_code=voucher_code,
        mac=session.get("client_mac"),
        ip=str(session.get("client_ip") or ""),
        client_mac=session.get("omada_client_mac") or session.get("mikrotik_client_mac") or session.get("client_mac"),
        client_ip=str(session.get("mikrotik_client_ip") or session.get("client_ip") or ""),
        ap_mac=session.get("omada_ap_mac") or session.get("ap_mac"),
        gateway_mac=session.get("omada_gateway_mac") or session.get("gateway_mac"),
        vlan_id=session.get("vlan_id"),
        ssid=session.get("ssid"),
        site=session.get("omada_site_name") or session.get("site"),
        site_id=session.get("omada_site_id"),
        gateway=session.get("gateway"),
        redirect_url=session.get("omada_redirect_url") or session.get("redirect_url"),
        nas_id=session.get("nas_id"),
        server_name=session.get("mikrotik_server_name"),
        link_login=session.get("mikrotik_link_login"),
        link_login_only=session.get("mikrotik_link_login_only"),
        link_orig=session.get("mikrotik_link_orig"),
        chap_id=session.get("mikrotik_chap_id"),
        chap_challenge=session.get("mikrotik_chap_challenge"),
        token=decrypt_secret(session.get("omada_token_encrypted")) if session.get("omada_token_encrypted") else None,
        authToken=decrypt_secret(session.get("omada_token_encrypted")) if session.get("omada_token_encrypted") else None,
        raw_query_params=raw_params,
    )


def fulfill_paid_payment_order(cur, order: dict, request: Request):
    if order.get("fulfillment_status") == "FULFILLED":
        return {"status": "FULFILLED", "message": "Payment order was already fulfilled.", "order": order, "bag_item": customer_bag_item_for_payment(cur, order.get("id"))}
    cur.execute("SELECT * FROM portal_sessions WHERE id = %s FOR UPDATE", (order["portal_session_id"],))
    session = cur.fetchone()
    if not session:
        raise RuntimeError("Portal session was not found for this payment order")
    blocked_public = enforce_portal_device_not_blocked(cur, session, None, request, "PAYMENT_FULFILLMENT", raise_error=False)
    if blocked_public:
        raise RuntimeError("This device is blocked. Please contact the operator.")
    user = ensure_portal_user(cur, session)
    bag_item = create_customer_bag_item_from_payment(cur, order, session, user)
    settings = ensure_customer_bag_settings(cur, user["id"])
    activation = {"status": "QUEUED", "message": "Payment item saved to customer bag."}
    cur.execute(
        """
        SELECT id, product_kind
        FROM customer_bag_items
        WHERE user_id = %s AND status = 'ACTIVE'
        """,
        (user["id"],),
    )
    active_rows = cur.fetchall()
    product_kind = normalize_product_kind(bag_item.get("product_kind"))
    if product_kind_is_iptv_only(product_kind):
        active_exists = any(product_kind_requires_iptv(row.get("product_kind")) for row in active_rows)
    elif product_kind_grants_hotspot(product_kind):
        active_exists = any(product_kind_grants_hotspot(row.get("product_kind")) for row in active_rows)
    else:
        active_exists = bool(active_rows)
    can_auto_activate = product_kind_is_iptv_only(product_kind) or (product_kind_grants_hotspot(product_kind) and not bool(order.get("outside_network_purchase")))
    if bool(settings.get("auto_activate")) and can_auto_activate and not active_exists:
        activation = activate_customer_bag_item(cur, bag_item, session, request, "PAYMENT_FULFILLMENT", require_current_network=False)
        if activation.get("status") == "SUCCESS":
            bag_item = activation["item"]
        elif activation.get("status") == "FAILED":
            raise RuntimeError(activation.get("error") or "Payment was received, but gateway authorization failed")
    voucher_id = (bag_item or {}).get("voucher_id")
    cur.execute(
        """
        UPDATE portal_sessions
        SET user_id = %s,
            last_error = NULL,
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (user["id"], session["id"]),
    )
    session = cur.fetchone()
    cur.execute(
        """
        UPDATE payment_orders
        SET voucher_id = %s,
            user_id = %s,
            fulfillment_status = 'FULFILLED',
            fulfilled_at = now(),
            last_error = NULL,
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (voucher_id, user["id"], order["id"]),
    )
    fulfilled_order = cur.fetchone()
    if product_kind_is_iptv_only(bag_item.get("product_kind")):
        message = "Payment received. IPTV pass activated." if activation.get("status") == "SUCCESS" else "Payment received. IPTV pass saved to your bag."
    else:
        message = "Payment received. Internet access activated." if activation.get("status") == "SUCCESS" else "Payment received. Package saved to your bag."
    create_portal_event(cur, session["id"], "PAYMENT_FULFILLMENT_SUCCESS", request, message, raw_context={"payment_order_id": order["public_order_id"], "bag_item_id": str(bag_item["id"]), "activation": sanitize_summary(activation)})
    fulfilled_order["_bag_item"] = bag_item
    return {"status": "FULFILLED", "order": fulfilled_order, "bag_item": bag_item, "activation": sanitize_summary(activation)}


def record_rejected_paymongo_webhook(payload: dict, event_type: str, reason: str):
    try:
        event_id = normalize_payment_text(
            nested_value(payload, ["data", "id"]) or f"rejected_{sha256(json.dumps(sanitize_summary(payload), sort_keys=True).encode('utf-8')).hexdigest()[:28]}",
            120,
        )
        with get_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO payment_webhook_events(provider, provider_mode, provider_event_id, event_type, processing_status, payload_json, error_message, processed_at)
                    VALUES ('PAYMONGO', NULL, %s, %s, 'FAILED', %s, %s, now())
                    ON CONFLICT (provider_event_id) DO UPDATE
                    SET processing_status = 'FAILED',
                        error_message = EXCLUDED.error_message,
                        processed_at = now()
                    """,
                    (event_id, event_type or "unknown", Json(sanitize_summary(payload)), normalize_payment_text(reason, 1000)),
                )
    except Exception as exc:
        print(f"PayMongo rejected webhook record failed: {exc}")


def safe_paymongo_diagnostic_headers(request: Request) -> dict:
    blocked = {"authorization", "cookie", "set-cookie"}
    return {
        key: normalize_payment_text(value, 1200)
        for key, value in request.headers.items()
        if key.lower() not in blocked
    }


def paymongo_signature_timestamp(header: str) -> Optional[str]:
    parsed = parse_paymongo_signature(header or "")
    return parsed.get("t")


def record_paymongo_webhook_diagnostic(request: Request, raw_body: bytes, payload: dict) -> dict:
    signature_header = request.headers.get("Paymongo-Signature") or request.headers.get("paymongo-signature") or ""
    headers = safe_paymongo_diagnostic_headers(request)
    cf_connecting_ip = host_ip(request.headers.get("cf-connecting-ip"))
    request_ip = host_ip(public_ip(request))
    content_length = request.headers.get("content-length")
    try:
        content_length_int = int(content_length) if content_length is not None else len(raw_body)
    except (TypeError, ValueError):
        content_length_int = len(raw_body)
    event_id = paymongo_event_id(payload) or normalize_payment_text(nested_value(payload, ["data", "id"]), 160)
    event_type = paymongo_event_type(payload)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO paymongo_webhook_diagnostics(
                    request_method, request_path, event_id, event_type, request_ip, cf_connecting_ip,
                    x_forwarded_for, user_agent, cf_ray, content_type, content_length,
                    signature_present, signature_timestamp, body_sha256, payload_json,
                    header_names, headers_json
                )
                VALUES (%s, %s, %s, %s, NULLIF(%s, '')::inet, NULLIF(%s, '')::inet,
                        %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING *
                """,
                (
                    request.method,
                    str(request.url.path),
                    normalize_payment_text(event_id, 160) or None,
                    normalize_payment_text(event_type, 160) or None,
                    request_ip or "",
                    cf_connecting_ip or "",
                    normalize_payment_text(request.headers.get("x-forwarded-for"), 1200),
                    normalize_payment_text(request.headers.get("user-agent"), 1200),
                    normalize_payment_text(request.headers.get("cf-ray"), 160),
                    normalize_payment_text(request.headers.get("content-type"), 300),
                    content_length_int,
                    bool(signature_header),
                    normalize_payment_text(paymongo_signature_timestamp(signature_header), 80),
                    sha256(raw_body).hexdigest(),
                    Json(sanitize_summary(payload) if payload else {"raw_body_sha256": sha256(raw_body).hexdigest()}),
                    list(headers.keys()),
                    Json(headers),
                ),
            )
            return cur.fetchone()


class DetachedRequestClient:
    def __init__(self, host: str = ""):
        self.host = host


class DetachedRequestContext:
    def __init__(self, request: Request):
        self.headers = dict(request.headers)
        self.client = DetachedRequestClient(request.client.host if request.client else "")


def enqueue_paymongo_webhook_processing(webhook_event_id: str, request: Request):
    request_context = DetachedRequestContext(request)

    def worker():
        try:
            process_paymongo_webhook_event(webhook_event_id, request_context)
        except Exception as exc:
            print(f"PayMongo webhook worker failed for {webhook_event_id}: {exc}")

    threading.Thread(target=worker, daemon=True).start()


def process_paymongo_webhook_event(webhook_event_id: str, request: Request):
    processing_status = "RECEIVED"
    error_message = None
    order = None
    event_type = ""
    payload = {}
    event_id = ""
    try:
        with get_conn() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT * FROM payment_webhook_events WHERE id = %s FOR UPDATE", (webhook_event_id,))
                webhook_event = cur.fetchone()
                if not webhook_event:
                    return
                if webhook_event.get("processing_status") in {"PROCESSED", "IGNORED"}:
                    return
                payload = webhook_event.get("payload_json") if isinstance(webhook_event.get("payload_json"), dict) else {}
                event_type = webhook_event.get("event_type") or paymongo_event_type(payload)
                event_id = webhook_event.get("provider_event_id") or paymongo_event_id(payload)
                public_order_id = paymongo_payment_reference(payload)
                checkout_session_id = paymongo_checkout_session_id(payload)
                provider_payment_id = paymongo_provider_payment_id(payload)
                event_amount = paymongo_payload_amount(payload)
                if webhook_event.get("payment_order_id"):
                    cur.execute("SELECT * FROM payment_orders WHERE id = %s FOR UPDATE", (webhook_event["payment_order_id"],))
                    order = cur.fetchone()
                if not order and public_order_id:
                    cur.execute("SELECT * FROM payment_orders WHERE public_order_id = %s FOR UPDATE", (public_order_id,))
                    order = cur.fetchone()
                if not order and checkout_session_id:
                    cur.execute("SELECT * FROM payment_orders WHERE checkout_session_id = %s FOR UPDATE", (checkout_session_id,))
                    order = cur.fetchone()
                if order and webhook_event.get("payment_order_id") != order.get("id"):
                    cur.execute("UPDATE payment_webhook_events SET payment_order_id = %s WHERE id = %s", (order["id"], webhook_event["id"]))

                if not order:
                    processing_status = "IGNORED"
                    error_message = "No local payment order matched this webhook."
                elif order.get("portal_session_id"):
                    create_portal_event(cur, order["portal_session_id"], "PAYMENT_WEBHOOK_RECEIVED", request, "PayMongo webhook received", raw_context={"payment_order_id": order["public_order_id"], "event_type": event_type})

                if order and paymongo_event_is_paid(event_type):
                    if order.get("checkout_session_id"):
                        order = sync_paymongo_checkout_status(cur, order, request)
                    else:
                        if event_amount is None:
                            raise RuntimeError("PayMongo paid webhook did not include a parsable amount.")
                        if int(event_amount) != int(order["amount_centavos"]):
                            raise RuntimeError(f"Paid amount mismatch. Expected {order['amount_centavos']} centavos, got {event_amount}.")
                        cur.execute(
                            """
                            UPDATE payment_orders
                            SET status = 'PAID',
                                provider_payment_id = COALESCE(%s, provider_payment_id),
                                provider_event_id = %s,
                                provider_webhook_json = %s,
                                paid_at = COALESCE(paid_at, now()),
                                last_error = NULL,
                                updated_at = now()
                            WHERE id = %s
                            RETURNING *
                            """,
                            (provider_payment_id, event_id, Json(sanitize_summary(payload)), order["id"]),
                        )
                        order = cur.fetchone()
                        fulfillment = fulfill_paid_payment_order(cur, order, request)
                        schedule_omada_payment_auth_free_paid_cleanup_for_order(cur, fulfillment.get("order") or order, reason="PAYMONGO_WEBHOOK_PAID")
                    processing_status = "PROCESSED"
                elif order and paymongo_event_is_failed(event_type):
                    error_message = paymongo_failure_message(payload)
                    cur.execute(
                        """
                        UPDATE payment_orders
                        SET status = 'FAILED',
                            fulfillment_status = CASE WHEN fulfillment_status = 'PENDING' THEN 'NOT_REQUIRED' ELSE fulfillment_status END,
                            provider_payment_id = COALESCE(%s, provider_payment_id),
                            provider_event_id = %s,
                            provider_webhook_json = %s,
                            last_error = %s,
                            updated_at = now()
                        WHERE id = %s
                        RETURNING *
                        """,
                        (provider_payment_id, event_id, Json(sanitize_summary(payload)), error_message, order["id"]),
                    )
                    order = cur.fetchone()
                    finalize_omada_payment_auth_free_grants_for_order(cur, order, final_status="CANCELLED")
                    if order.get("portal_session_id"):
                        create_portal_event(cur, order["portal_session_id"], "PAYMENT_FAILED", request, error_message, raw_context={"payment_order_id": order["public_order_id"], "event_type": event_type, "failure_code": paymongo_failure_code(payload)})
                    processing_status = "PROCESSED"
                elif order and processing_status == "RECEIVED":
                    processing_status = "IGNORED"
                    error_message = f"Event type {event_type or 'unknown'} does not require payment fulfillment."

                cur.execute(
                    """
                    UPDATE payment_webhook_events
                    SET processing_status = %s,
                        error_message = %s,
                        processed_at = now()
                    WHERE id = %s
                    """,
                    (processing_status, error_message, webhook_event["id"]),
                )
        if processing_status == "FAILED" or (processing_status == "PROCESSED" and order and order.get("status") == "FAILED"):
            create_paymongo_admin_notification(
                "PayMongo payment failed",
                error_message or "A PayMongo payment failed.",
                related_id=(order or {}).get("public_order_id") or event_id,
                metadata={"event_type": event_type, "order": (order or {}).get("public_order_id"), "failure_code": paymongo_failure_code(payload)},
            )
    except Exception as exc:
        error_message = str(exc)
        try:
            with get_conn() as conn:
                with conn.cursor() as cur:
                    if order:
                        cur.execute(
                            """
                            UPDATE payment_orders
                            SET fulfillment_status = CASE WHEN status = 'PAID' THEN 'FAILED' ELSE fulfillment_status END,
                                last_error = %s,
                                updated_at = now()
                            WHERE id = %s
                            """,
                            (error_message, order["id"]),
                        )
                    cur.execute(
                        """
                        UPDATE payment_webhook_events
                        SET processing_status = 'FAILED',
                            error_message = %s,
                            processed_at = now()
                        WHERE id = %s
                        """,
                        (error_message, webhook_event_id),
                    )
        except Exception as update_exc:
            print(f"PayMongo webhook failure update failed: {update_exc}")
        create_paymongo_admin_notification(
            "PayMongo webhook processing failed",
            error_message,
            related_id=(order or {}).get("public_order_id") or event_id or str(webhook_event_id),
            metadata={"event_type": event_type, "order": (order or {}).get("public_order_id")},
        )


