def attach_discounts_to_categories(categories: list[dict], active_only: bool = False) -> list[dict]:
    category_ids = [category["id"] for category in categories if category.get("id")]
    discounts = product_category_discount_rows(category_ids, active_only=active_only)
    discount_map: dict[str, list[dict]] = {}
    for discount in discounts:
        discount_map.setdefault(discount["category_id"], []).append(discount)
    for category in categories:
        category["discounts"] = discount_map.get(category.get("id"), [])
        category["discount_count"] = len(category["discounts"])
    return categories


def product_category_discounts_for_product(product: dict, active_only: bool = True) -> list[dict]:
    category_id = product.get("category_id")
    if not category_id:
        return []
    return product_category_discount_rows([str(category_id)], active_only=active_only)


def product_applicable_category_discount(product: dict, total_duration_seconds: int) -> Optional[dict]:
    if product.get("use_category_discounts") is False:
        return None
    enabled_discount_ids = product.get("enabled_category_discount_ids")
    if enabled_discount_ids is not None:
        enabled_discount_ids = {str(discount_id) for discount_id in enabled_discount_ids if discount_id}
        if not enabled_discount_ids:
            return None
    eligible = []
    for discount in product.get("category_discounts") or []:
        if not discount.get("enabled"):
            continue
        if enabled_discount_ids is not None and str(discount.get("id")) not in enabled_discount_ids:
            continue
        threshold_seconds = int(discount.get("threshold_seconds") or discount_threshold_seconds(discount.get("threshold_value") or 0, discount.get("threshold_unit") or "days"))
        if total_duration_seconds >= threshold_seconds:
            eligible.append({**discount, "threshold_seconds": threshold_seconds})
    if not eligible:
        return None
    return sorted(eligible, key=lambda item: (int(item.get("threshold_seconds") or 0), int(item.get("sort_order") or 0)))[-1]


def product_applicable_item_discount(product: dict, total_duration_seconds: int) -> Optional[dict]:
    eligible = []
    for discount in product.get("discounts") or product.get("product_discounts") or []:
        if not discount.get("enabled"):
            continue
        threshold_seconds = int(discount.get("threshold_seconds") or discount_threshold_seconds(discount.get("threshold_value") or 0, discount.get("threshold_unit") or "days"))
        if total_duration_seconds >= threshold_seconds:
            eligible.append({**discount, "threshold_seconds": threshold_seconds})
    if not eligible:
        return None
    return sorted(eligible, key=lambda item: (int(item.get("threshold_seconds") or 0), int(item.get("sort_order") or 0)))[-1]


def product_checkout_amount(product: dict, purchase_quantity: int) -> dict:
    quantity = max(1, min(int(purchase_quantity or 1), 365))
    unit_amount = payment_amount_centavos(product["price"])
    base_amount = unit_amount * quantity
    discount_amount = 0
    duration_unit = normalize_product_duration_unit(product.get("duration_unit"))
    total_duration_seconds = product_duration_seconds(product.get("duration_value"), duration_unit) * quantity
    selected_discount = product_applicable_item_discount(product, total_duration_seconds)
    discount_type = normalize_product_discount_type((selected_discount or {}).get("discount_type"))
    discount_value = Decimal(str((selected_discount or {}).get("discount_value") or 0))
    discount_applied = bool(selected_discount and discount_type and discount_value > 0)
    if discount_applied:
        if discount_type == "PERCENT":
            discount_amount = int((Decimal(base_amount) * (discount_value / Decimal("100"))).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        else:
            discount_amount = payment_amount_centavos(discount_value)
        discount_amount = max(0, min(discount_amount, base_amount))
    return {
        "quantity": quantity,
        "unit_amount_centavos": unit_amount,
        "base_amount_centavos": base_amount,
        "discount_amount_centavos": discount_amount,
        "amount_centavos": max(1, base_amount - discount_amount),
        "discount_type": discount_type if discount_applied else None,
        "discount_value": discount_value if discount_applied else Decimal("0"),
        "discount_applied": discount_applied,
        "discount_tier_id": selected_discount.get("id") if selected_discount else None,
        "discount_label": selected_discount.get("display_label") if selected_discount else None,
        "discount_threshold_seconds": selected_discount.get("threshold_seconds") if selected_discount else None,
    }


def product_duration_seconds(duration_value: int, duration_unit: str) -> int:
    multipliers = {"minutes": 60, "hours": 3600, "days": 86400}
    return int(duration_value or 0) * multipliers[duration_unit]


def product_duration_label(duration_value: int, duration_unit: str) -> str:
    value = int(duration_value or 0)
    unit = duration_unit[:-1] if value == 1 and duration_unit.endswith("s") else duration_unit
    return f"{value} {unit}"


def format_seconds_human(seconds: int) -> str:
    total = max(0, int(seconds or 0))
    days = total // 86400
    hours = (total % 86400) // 3600
    minutes = (total % 3600) // 60
    if days:
        return f"{days}d {hours}h {minutes}m"
    if hours:
        return f"{hours}h {minutes}m"
    return f"{minutes}m"


def serialize_product_category(row, product_count: Optional[int] = None) -> dict:
    if not row:
        return {}
    access_scope = normalize_product_access_scope(row.get("access_scope"))
    allowed_barangay = normalize_barangay_label(row.get("allowed_barangay"))
    discounts = row.get("discounts") if isinstance(row.get("discounts"), list) else []
    return {
        "id": str(row["id"]),
        "name": row["name"],
        "description": row.get("description") or "",
        "image_url": row.get("image_url") or "",
        "more_info_enabled": bool(row.get("more_info_enabled")),
        "more_info_text": row.get("more_info_text") or "",
        "access_scope": access_scope,
        "access_scope_label": "Barangay only" if access_scope == "BARANGAY_ONLY" else "All Locations",
        "allowed_barangay": allowed_barangay,
        "restriction_label": "Barangay only" if access_scope == "BARANGAY_ONLY" else "All locations",
        "status": row["status"],
        "sort_order": row["sort_order"],
        "product_count": int(product_count if product_count is not None else row.get("product_count") or 0),
        "discounts": discounts,
        "discount_count": len(discounts),
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


def product_category_rows(active_only: bool = False) -> list[dict]:
    where = "WHERE c.status = 'ACTIVE'" if active_only else ""
    rows = fetch_all(
        f"""
        SELECT c.*,
               COALESCE(
                   COUNT(pcia.item_id) FILTER (
                       WHERE pcia.status = 'ACTIVE'
                         AND p.status = 'ACTIVE'
                   ),
                   0
               ) AS product_count
        FROM product_categories c
        LEFT JOIN product_category_item_assignments pcia ON pcia.category_id = c.id
        LEFT JOIN product_items p ON p.id = pcia.item_id
        {where}
        GROUP BY c.id
        ORDER BY c.sort_order ASC, c.name ASC, c.created_at DESC
        """
    )
    return attach_discounts_to_categories([serialize_product_category(row) for row in rows], active_only=active_only)


def product_category_for_payload(cur, category_id: Optional[str], active_only: bool = False) -> Optional[dict]:
    normalized_id = normalize_product_category_id(category_id)
    if not normalized_id:
        return None
    status_clause = "AND status = 'ACTIVE'" if active_only else ""
    cur.execute(f"SELECT * FROM product_categories WHERE id = %s {status_clause}", (normalized_id,))
    category = cur.fetchone()
    if not category:
        raise HTTPException(status_code=400, detail="Product category was not found or is disabled.")
    return category


def normalize_product_category_item_ids(item_ids: list[str]) -> list[str]:
    clean_ids: list[str] = []
    seen = set()
    for item_id in item_ids or []:
        if not item_id:
            continue
        try:
            clean_id = str(uuid.UUID(str(item_id)))
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="One selected product item is invalid.") from exc
        if clean_id not in seen:
            seen.add(clean_id)
            clean_ids.append(clean_id)
    return clean_ids


def replace_product_category_item_assignments(cur, category_id: str, item_ids: list[str]) -> None:
    clean_item_ids = normalize_product_category_item_ids(item_ids)
    cur.execute("DELETE FROM product_category_item_assignments WHERE category_id = %s", (category_id,))
    if not clean_item_ids:
        return
    cur.execute("SELECT id FROM product_items WHERE id = ANY(%s::uuid[])", (clean_item_ids,))
    found_ids = {str(row["id"]) for row in cur.fetchall()}
    missing = [item_id for item_id in clean_item_ids if item_id not in found_ids]
    if missing:
        raise HTTPException(status_code=400, detail="One selected product item no longer exists.")
    for index, item_id in enumerate(clean_item_ids, start=1):
        cur.execute(
            """
            INSERT INTO product_category_item_assignments(category_id, item_id, status, sort_order)
            VALUES (%s, %s, 'ACTIVE', %s)
            ON CONFLICT (category_id, item_id) DO UPDATE
            SET status = 'ACTIVE',
                sort_order = EXCLUDED.sort_order,
                updated_at = now()
            """,
            (category_id, item_id, index),
        )


def serialize_product_item(row) -> dict:
    if not row:
        return {}
    duration_unit = normalize_product_duration_unit(row["duration_unit"])
    price = float(row["price"] or 0)
    category_access_scope = normalize_product_access_scope(row.get("category_access_scope")) if row.get("category_id") or row.get("category_access_scope") else "ALL_LOCATIONS"
    category_barangay = normalize_barangay_label(row.get("category_allowed_barangay"))
    category_discounts = row.get("category_discounts") if isinstance(row.get("category_discounts"), list) else []
    product_discounts = row.get("discounts") if isinstance(row.get("discounts"), list) else []
    use_category_discounts = row.get("use_category_discounts")
    if use_category_discounts is None:
        use_category_discounts = True
    enabled_category_discount_ids = row.get("enabled_category_discount_ids")
    if enabled_category_discount_ids is not None and not isinstance(enabled_category_discount_ids, list):
        enabled_category_discount_ids = []
    product_kind = normalize_product_kind(row.get("product_kind"))
    iptv_enabled = product_kind_requires_iptv(product_kind)
    color = serialize_item_color(row)
    return {
        "id": str(row["id"]),
        "category_id": str(row["category_id"]) if row.get("category_id") else None,
        "assigned_category_id": str(row["assigned_category_id"]) if row.get("assigned_category_id") else None,
        "assignment_status": row.get("assignment_status") or None,
        "assignment_sort_order": int(row.get("assignment_sort_order") or 0),
        "assigned_category_count": int(row.get("assigned_category_count") or 0),
        "category_name": row.get("category_name") or "Uncategorized",
        "category_description": row.get("category_description") or "",
        "category_image_url": row.get("category_image_url") or "",
        "category_access_scope": category_access_scope,
        "category_access_scope_label": "Barangay only" if category_access_scope == "BARANGAY_ONLY" else "All Locations",
        "category_allowed_barangay": category_barangay,
        "category_restriction_label": "Barangay only" if category_access_scope == "BARANGAY_ONLY" else "All locations",
        "category_restricted": category_access_scope == "BARANGAY_ONLY",
        "name": row["name"],
        "description": row.get("description") or "",
        **color,
        "price": price,
        "price_display": f"PHP {price:,.2f}",
        "duration_value": row["duration_value"],
        "duration_unit": duration_unit,
        "duration_seconds": product_duration_seconds(row["duration_value"], duration_unit),
        "duration_label": product_duration_label(row["duration_value"], duration_unit),
        "product_kind": product_kind,
        "product_kind_label": product_kind_label(product_kind),
        "iptv_enabled": iptv_enabled,
        "iptv_package_label": row.get("iptv_package_label") or "",
        "iptv_xui_package_id": row.get("iptv_xui_package_id") or "",
        "iptv_auto_provision": bool(row.get("iptv_auto_provision")),
        "iptv_notes": row.get("iptv_notes") or "",
        **public_speed_limit(row),
        "use_category_discounts": bool(use_category_discounts),
        "enabled_category_discount_ids": enabled_category_discount_ids,
        "category_discounts": category_discounts,
        "discounts": product_discounts,
        "discount_count": len([discount for discount in product_discounts if discount.get("enabled")]),
        "discount_enabled": bool(row.get("discount_enabled")),
        "discount_min_quantity": int(row["discount_min_quantity"]) if row.get("discount_min_quantity") else None,
        "discount_type": row.get("discount_type"),
        "discount_value": float(row.get("discount_value") or 0),
        "status": row["status"],
        "sort_order": row["sort_order"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


def product_item_rows(active_only: bool = False) -> list[dict]:
    where = "WHERE p.status = 'ACTIVE'" if active_only else ""
    rows = fetch_all(
        f"""
        SELECT p.*,
               NULL::uuid AS assigned_category_id,
               NULL::text AS assignment_status,
               0::int AS assignment_sort_order,
               COALESCE(assigned.category_count, 0)::int AS assigned_category_count
        FROM product_items p
        LEFT JOIN (
            SELECT item_id, COUNT(*)::int AS category_count
            FROM product_category_item_assignments
            WHERE status = 'ACTIVE'
            GROUP BY item_id
        ) assigned ON assigned.item_id = p.id
        {where}
        ORDER BY p.sort_order ASC, p.price ASC, p.name ASC, p.created_at DESC
        """
    )
    item_ids = sorted({str(row["id"]) for row in rows if row.get("id")})
    discount_map: dict[str, list[dict]] = {}
    for discount in product_item_discount_rows(item_ids, active_only=active_only):
        discount_map.setdefault(discount["product_item_id"], []).append(discount)
    serialized = []
    for row in rows:
        row["discounts"] = discount_map.get(str(row["id"]), [])
        row["category_discounts"] = []
        serialized.append(serialize_product_item(row))
    return serialized


def product_category_item_rows(category_ids: Optional[list[str]] = None, active_only: bool = False) -> dict[str, list[dict]]:
    if category_ids is not None:
        ids = [str(category_id) for category_id in category_ids if category_id]
        if not ids:
            return {}
        active_clause = "AND p.status = 'ACTIVE' AND pcia.status = 'ACTIVE' AND c.status = 'ACTIVE'" if active_only else ""
        rows = fetch_all(
            f"""
            SELECT p.*,
                   c.id AS category_id,
                   c.id AS assigned_category_id,
                   c.name AS category_name,
                   c.description AS category_description,
                   c.image_url AS category_image_url,
                   c.access_scope AS category_access_scope,
                   c.allowed_barangay AS category_allowed_barangay,
                   c.status AS category_status,
                   c.sort_order AS category_sort_order,
                   pcia.status AS assignment_status,
                   pcia.sort_order AS assignment_sort_order,
                   COALESCE(assigned.category_count, 0)::int AS assigned_category_count
            FROM product_category_item_assignments pcia
            JOIN product_items p ON p.id = pcia.item_id
            JOIN product_categories c ON c.id = pcia.category_id
            LEFT JOIN (
                SELECT item_id, COUNT(*)::int AS category_count
                FROM product_category_item_assignments
                WHERE status = 'ACTIVE'
                GROUP BY item_id
            ) assigned ON assigned.item_id = p.id
            WHERE pcia.category_id = ANY(%s::uuid[])
              {active_clause}
            ORDER BY c.sort_order ASC, pcia.sort_order ASC, p.sort_order ASC, p.price ASC, p.name ASC, p.created_at DESC
            """,
            (ids,),
        )
        item_ids = sorted({str(row["id"]) for row in rows if row.get("id")})
        discount_map: dict[str, list[dict]] = {}
        for discount in product_item_discount_rows(item_ids, active_only=active_only):
            discount_map.setdefault(discount["product_item_id"], []).append(discount)
        grouped: dict[str, list[dict]] = {}
        for row in rows:
            row["discounts"] = discount_map.get(str(row["id"]), [])
            row["category_discounts"] = []
            grouped.setdefault(str(row["assigned_category_id"]), []).append(serialize_product_item(row))
        return grouped
    return {"catalog": product_item_rows(active_only=active_only)}


def attach_product_items_to_categories(categories: list[dict], active_only: bool = False) -> list[dict]:
    category_ids = [category["id"] for category in categories if category.get("id")]
    item_map = product_category_item_rows(category_ids, active_only=active_only)
    attached = []
    for category in categories:
        items = item_map.get(category["id"], [])
        attached.append({
            **category,
            "items": items,
            "item_ids": [item["id"] for item in items],
            "product_count": len(items),
        })
    return attached


def group_product_items_by_category(items: list[dict], categories: Optional[list[dict]] = None) -> list[dict]:
    category_map = {}
    ordered_groups = []
    for category in categories or []:
        group = {**category, "items": []}
        category_map[category["id"]] = group
        ordered_groups.append(group)
    uncategorized = {
        "id": None,
        "name": "Available Packages",
        "description": "",
        "image_url": "",
        "access_scope": "ALL_LOCATIONS",
        "access_scope_label": "All Locations",
        "allowed_barangay": None,
        "restriction_label": "All locations",
        "status": "ACTIVE",
        "sort_order": 999999,
        "product_count": 0,
        "items": [],
    }
    for item in items:
        category_id = item.get("category_id")
        group = category_map.get(category_id)
        if not group:
            if category_id:
                group = {
                    "id": category_id,
                    "name": item.get("category_name") or "Category",
                    "description": item.get("category_description") or "",
                    "image_url": item.get("category_image_url") or "",
                    "access_scope": item.get("category_access_scope") or "ALL_LOCATIONS",
                    "access_scope_label": item.get("category_access_scope_label") or "All Locations",
                    "allowed_barangay": item.get("category_allowed_barangay"),
                    "restriction_label": item.get("category_restriction_label") or "All locations",
                    "status": "ACTIVE",
                    "sort_order": 0,
                    "product_count": 0,
                    "items": [],
                }
                category_map[category_id] = group
                ordered_groups.append(group)
            else:
                group = uncategorized
        group["items"].append(item)
        group["product_count"] = len(group["items"])
    if uncategorized["items"]:
        ordered_groups.append(uncategorized)
    return [group for group in ordered_groups if group.get("items")]


def normalize_site_deployment_ids(site_ids: Optional[list[str]]) -> list[str]:
    cleaned = []
    seen = set()
    for value in site_ids or []:
        text = str(value or "").strip()
        if not text:
            continue
        try:
            clean_id = str(uuid.UUID(text))
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="One selected site id is invalid.") from exc
        if clean_id not in seen:
            cleaned.append(clean_id)
            seen.add(clean_id)
    return cleaned


def normalize_optional_uuid(value: Optional[str], message: str = "Invalid id.") -> Optional[str]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return str(uuid.UUID(text))
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=message) from exc


def store_site_rows(store_ids: Optional[list[str]] = None) -> dict[str, list[dict]]:
    params = []
    where = ""
    if store_ids is not None:
        ids = [str(store_id) for store_id in store_ids if store_id]
        if not ids:
            return {}
        where = "WHERE pss.store_id = ANY(%s::uuid[])"
        params.append(ids)
    rows = fetch_all(
        f"""
        SELECT pss.store_id,
               sd.id AS site_deployment_id,
               sd.site_name,
               sd.omada_site_id,
               sd.barangay,
               sd.municipality,
               sd.latitude,
               sd.longitude
        FROM physical_store_sites pss
        JOIN site_deployments sd ON sd.id = pss.site_deployment_id
        {where}
        ORDER BY sd.site_name ASC
        """,
        tuple(params),
    )
    grouped: dict[str, list[dict]] = {}
    for row in rows:
        grouped.setdefault(str(row["store_id"]), []).append({
            "site_deployment_id": str(row["site_deployment_id"]),
            "site_name": row.get("site_name"),
            "omada_site_id": row.get("omada_site_id"),
            "barangay": row.get("barangay"),
            "municipality": row.get("municipality"),
            "latitude": float(row["latitude"]) if row.get("latitude") is not None else None,
            "longitude": float(row["longitude"]) if row.get("longitude") is not None else None,
        })
    return grouped


def serialize_physical_store(row, site_map: Optional[dict[str, list[dict]]] = None, item_map: Optional[dict[str, list[dict]]] = None) -> dict:
    if not row:
        return {}
    store_id = str(row["id"])
    sites = (site_map or {}).get(store_id, [])
    items = (item_map or {}).get(store_id, [])
    distance_meters = row.get("distance_meters") if isinstance(row, dict) else None
    commission_type = normalize_physical_store_commission_type(row.get("commission_type"))
    commission_value = normalize_physical_store_commission_value(commission_type, row.get("commission_value"))
    return {
        "id": store_id,
        "store_name": row.get("store_name") or "",
        "location_id": str(row["location_id"]) if row.get("location_id") else None,
        "location_name": row.get("location_name") or "",
        "description": row.get("description") or "",
        "image_url": row.get("image_url") or "",
        "address": row.get("address") or "",
        "municipality": row.get("municipality") or "",
        "barangay": row.get("barangay") or "",
        "latitude": float(row["latitude"]) if row.get("latitude") is not None else None,
        "longitude": float(row["longitude"]) if row.get("longitude") is not None else None,
        "contact_name": row.get("contact_name") or "",
        "contact_phone": row.get("contact_phone") or "",
        "commission_type": commission_type,
        "commission_type_label": store_commission_type_label(commission_type),
        "commission_value": float(commission_value),
        "commission_value_display": store_commission_value_display(commission_type, commission_value),
        "status": row.get("status") or "ACTIVE",
        "notes": row.get("notes") or "",
        "owner": {
            "id": str(row["owner_id"]) if row.get("owner_id") else None,
            "username": row.get("owner_username") or "",
            "display_name": row.get("owner_display_name") or row.get("contact_name") or "",
            "contact_number": row.get("owner_contact_number") or row.get("contact_phone") or "",
            "contact_hint": mask_a2p_destination(row.get("owner_normalized_contact") or row.get("owner_contact_number") or ""),
            "status": row.get("owner_status") or "SETUP",
            "owner_notes": row.get("owner_notes") or row.get("notes") or "",
            "must_change_password": bool(row.get("owner_must_change_password")),
            "activated_at": row.get("owner_activated_at"),
            "activation_sms_sent_at": row.get("owner_activation_sms_sent_at"),
            "activation_sms_status": row.get("owner_activation_sms_status_json") or {},
            "last_login_at": row.get("owner_last_login_at"),
        } if row.get("owner_id") else None,
        "sites": sites,
        "site_ids": [site["site_deployment_id"] for site in sites],
        "site_count": len(sites),
        "items": items,
        "item_ids": [item["id"] for item in items],
        "item_count": len(items),
        "distance_meters": int(distance_meters) if distance_meters is not None else None,
        "distance_km": round(float(distance_meters) / 1000, 2) if distance_meters is not None else None,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def physical_store_rows(active_only: bool = False) -> list[dict]:
    where = "WHERE ps.status = 'ACTIVE'" if active_only else ""
    rows = fetch_all(
        f"""
        SELECT ps.*, loc.location_name,
               so.id AS owner_id,
               so.username AS owner_username,
               so.display_name AS owner_display_name,
               so.contact_number AS owner_contact_number,
               so.normalized_contact AS owner_normalized_contact,
               so.status AS owner_status,
               so.owner_notes AS owner_notes,
               so.must_change_password AS owner_must_change_password,
               so.activated_at AS owner_activated_at,
               so.activation_sms_sent_at AS owner_activation_sms_sent_at,
               so.activation_sms_status_json AS owner_activation_sms_status_json,
               so.last_login_at AS owner_last_login_at
        FROM physical_stores ps
        LEFT JOIN locations loc ON loc.id = ps.location_id
        LEFT JOIN physical_store_owners so ON so.store_id = ps.id
        {where}
        ORDER BY ps.status ASC, ps.store_name ASC, ps.created_at DESC
        """
    )
    site_map = store_site_rows([str(row["id"]) for row in rows])
    item_map = physical_store_item_rows([str(row["id"]) for row in rows], active_only=False)
    return [serialize_physical_store(row, site_map, item_map) for row in rows]


def physical_store_row_by_id(store_id: str) -> dict:
    row = fetch_one(
        """
        SELECT ps.*, loc.location_name,
               so.id AS owner_id,
               so.username AS owner_username,
               so.display_name AS owner_display_name,
               so.contact_number AS owner_contact_number,
               so.normalized_contact AS owner_normalized_contact,
               so.status AS owner_status,
               so.owner_notes AS owner_notes,
               so.must_change_password AS owner_must_change_password,
               so.activated_at AS owner_activated_at,
               so.activation_sms_sent_at AS owner_activation_sms_sent_at,
               so.activation_sms_status_json AS owner_activation_sms_status_json,
               so.last_login_at AS owner_last_login_at
        FROM physical_stores ps
        LEFT JOIN locations loc ON loc.id = ps.location_id
        LEFT JOIN physical_store_owners so ON so.store_id = ps.id
        WHERE ps.id = %s
        """,
        (store_id,),
    )
    if not row:
        return {}
    site_map = store_site_rows([str(row["id"])])
    item_map = physical_store_item_rows([str(row["id"])], active_only=False)
    return serialize_physical_store(row, site_map, item_map)


def replace_physical_store_sites(cur, store_id: str, site_ids: list[str]) -> None:
    clean_site_ids = normalize_site_deployment_ids(site_ids)
    cur.execute("DELETE FROM physical_store_sites WHERE store_id = %s", (store_id,))
    if not clean_site_ids:
        return
    cur.execute("SELECT id FROM site_deployments WHERE id = ANY(%s::uuid[])", (clean_site_ids,))
    found_ids = {str(row["id"]) for row in cur.fetchall()}
    missing = [site_id for site_id in clean_site_ids if site_id not in found_ids]
    if missing:
        raise HTTPException(status_code=400, detail="One selected site no longer exists.")
    for site_id in clean_site_ids:
        cur.execute(
            """
            INSERT INTO physical_store_sites(store_id, site_deployment_id)
            VALUES (%s, %s)
            ON CONFLICT (store_id, site_deployment_id) DO NOTHING
            """,
            (store_id, site_id),
        )


def normalize_physical_store_item_ids(item_ids: list[str]) -> list[str]:
    clean_ids: list[str] = []
    seen = set()
    for item_id in item_ids or []:
        if not item_id:
            continue
        try:
            clean_id = str(uuid.UUID(str(item_id)))
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="One selected store item is invalid.") from exc
        if clean_id not in seen:
            seen.add(clean_id)
            clean_ids.append(clean_id)
    return clean_ids


def replace_physical_store_item_assignments(cur, store_id: str, item_ids: list[str]) -> None:
    clean_item_ids = normalize_physical_store_item_ids(item_ids)
    cur.execute("DELETE FROM physical_store_item_assignments WHERE store_id = %s", (store_id,))
    if not clean_item_ids:
        return
    cur.execute("SELECT id FROM physical_store_items WHERE id = ANY(%s::uuid[])", (clean_item_ids,))
    found_ids = {str(row["id"]) for row in cur.fetchall()}
    missing = [item_id for item_id in clean_item_ids if item_id not in found_ids]
    if missing:
        raise HTTPException(status_code=400, detail="One selected store item no longer exists.")
    for index, item_id in enumerate(clean_item_ids, start=1):
        cur.execute(
            """
            INSERT INTO physical_store_item_assignments(store_id, item_id, status, sort_order)
            VALUES (%s, %s, 'ACTIVE', %s)
            ON CONFLICT (store_id, item_id) DO UPDATE
            SET status = 'ACTIVE',
                sort_order = EXCLUDED.sort_order,
                updated_at = now()
            """,
            (store_id, item_id, index),
        )


def store_owner_payload_values(payload: PhysicalStoreOwnerPayload, store: dict, existing: Optional[dict] = None, require_password: bool = False, generated_password: Optional[str] = None) -> dict:
    normalized_contact, _ = normalize_portal_contact_number(payload.contact_number)
    display_contact = portal_contact_display_number(payload.contact_number)
    username = display_contact
    display_name = normalize_payment_text(payload.display_name, 160)
    if not display_name:
        raise HTTPException(status_code=400, detail="Store owner display name is required.")
    status = store_owner_status(payload.status)
    raw_password = generated_password or payload.password
    if require_password and not raw_password and not existing:
        raise HTTPException(status_code=400, detail="Owner password is required.")
    return {
        "username": username,
        "display_name": display_name,
        "contact_number": display_contact,
        "normalized_contact": normalized_contact,
        "status": status,
        "owner_notes": normalize_payment_text(payload.owner_notes, 2000) or None,
        "password_hash": hash_password(raw_password) if raw_password else (existing or {}).get("password_hash"),
        "temporary_password": raw_password,
    }


def upsert_physical_store_owner(cur, store_id: str, payload: PhysicalStoreOwnerPayload, store: dict, admin_id, status_override: Optional[str] = None, generated_password: Optional[str] = None, must_change_password: Optional[bool] = None) -> dict:
    cur.execute("SELECT * FROM physical_store_owners WHERE store_id = %s FOR UPDATE", (store_id,))
    existing = cur.fetchone()
    effective_payload = payload.model_copy(update={"status": status_override or payload.status})
    values = store_owner_payload_values(effective_payload, store, existing, generated_password=generated_password)
    cur.execute(
        """
        SELECT store_id
        FROM physical_store_owners
        WHERE username = %s
          AND store_id <> %s
        LIMIT 1
        """,
        (values["username"], store_id),
    )
    if cur.fetchone():
        raise HTTPException(status_code=400, detail="Store owner username is already used by another physical store.")
    cur.execute(
        """
        SELECT store_id
        FROM physical_store_owners
        WHERE normalized_contact = %s
          AND store_id <> %s
        LIMIT 1
        """,
        (values["normalized_contact"], store_id),
    )
    if cur.fetchone():
        raise HTTPException(status_code=400, detail="Store owner contact number is already used by another physical store.")
    if not values["password_hash"]:
        values["password_hash"] = hash_password(generated_password or generate_store_owner_temporary_password())
        if generated_password is None:
            values["temporary_password"] = ""
    next_must_change = bool(must_change_password) if must_change_password is not None else bool((existing or {}).get("must_change_password"))
    cur.execute(
        """
        INSERT INTO physical_store_owners(
            store_id, username, password_hash, display_name, contact_number,
            normalized_contact, status, owner_notes, must_change_password, created_by_admin_id
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (store_id) DO UPDATE
        SET username = EXCLUDED.username,
            password_hash = EXCLUDED.password_hash,
            display_name = EXCLUDED.display_name,
            contact_number = EXCLUDED.contact_number,
            normalized_contact = EXCLUDED.normalized_contact,
            status = EXCLUDED.status,
            owner_notes = EXCLUDED.owner_notes,
            must_change_password = EXCLUDED.must_change_password,
            updated_at = now()
        RETURNING *
        """,
        (
            store_id,
            values["username"],
            values["password_hash"],
            values["display_name"],
            values["contact_number"],
            values["normalized_contact"],
            values["status"],
            values["owner_notes"],
            next_must_change,
            admin_id,
        ),
    )
    owner = cur.fetchone()
    owner["_temporary_password"] = values.get("temporary_password") or ""
    return owner


def activate_physical_store_owner(cur, store: dict, owner_payload: PhysicalStoreOwnerPayload, admin_id, request: Request) -> dict:
    temporary_password = generate_store_owner_temporary_password()
    owner = upsert_physical_store_owner(
        cur,
        str(store["id"]),
        owner_payload,
        store,
        admin_id,
        status_override="ACTIVE",
        generated_password=temporary_password,
        must_change_password=True,
    )
    sms_result = send_store_owner_activation_sms(cur, owner, store, temporary_password, request)
    cur.execute(
        """
        UPDATE physical_store_owners
        SET activated_at = COALESCE(activated_at, now()),
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (owner["id"],),
    )
    activated_owner = cur.fetchone()
    activated_owner["_activation_sms"] = sms_result
    return activated_owner


def resend_physical_store_owner_activation_sms(cur, store: dict, owner: dict, request: Request) -> dict:
    if store.get("status") != "ACTIVE":
        raise HTTPException(status_code=400, detail="Set the physical store status to ACTIVE before resending owner activation SMS.")
    if owner.get("status") != "ACTIVE":
        raise HTTPException(status_code=400, detail="Store owner must be ACTIVE before activation SMS can be resent.")
    if owner.get("last_login_at"):
        raise HTTPException(status_code=400, detail="Activation SMS resend is disabled because this store owner has already logged in. Use store owner password reset instead.")
    temporary_password = generate_store_owner_temporary_password()
    cur.execute(
        """
        UPDATE physical_store_owners
        SET password_hash = %s,
            must_change_password = true,
            activated_at = COALESCE(activated_at, now()),
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (hash_password(temporary_password), owner["id"]),
    )
    updated_owner = cur.fetchone()
    sms_result = send_store_owner_activation_sms(cur, updated_owner, store, temporary_password, request)
    cur.execute("SELECT * FROM physical_store_owners WHERE id = %s", (owner["id"],))
    resent_owner = cur.fetchone()
    resent_owner["_activation_sms"] = sms_result
    return resent_owner


def serialize_physical_store_item(row) -> dict:
    if not row:
        return {}
    duration_unit = normalize_product_duration_unit(row.get("duration_unit") or "hours")
    access_scope = normalize_product_access_scope(row.get("access_scope") or "ALL_LOCATIONS")
    allowed_barangay = normalize_barangay_label(row.get("allowed_barangay"))
    price = float(row.get("price") or 0)
    color = serialize_item_color(row)
    return {
        "id": str(row["id"]),
        "store_id": str(row["store_id"]) if row.get("store_id") else None,
        "assigned_store_id": str(row["assigned_store_id"]) if row.get("assigned_store_id") else None,
        "assignment_status": row.get("assignment_status") or None,
        "name": row.get("name") or "",
        "description": row.get("description") or "",
        **color,
        "price": price,
        "price_display": f"PHP {price:,.2f}",
        "duration_value": int(row.get("duration_value") or 1),
        "duration_unit": duration_unit,
        "duration_seconds": product_duration_seconds(int(row.get("duration_value") or 1), duration_unit),
        "duration_label": product_duration_label(int(row.get("duration_value") or 1), duration_unit),
        **public_speed_limit(row),
        "access_scope": access_scope,
        "access_scope_label": "Barangay only" if access_scope == "BARANGAY_ONLY" else "All Locations",
        "allowed_barangay": allowed_barangay,
        "restriction_label": "Barangay only" if access_scope == "BARANGAY_ONLY" else "All locations",
        "more_info_enabled": bool(row.get("more_info_enabled")),
        "more_info_text": row.get("more_info_text") or "",
        "status": row.get("status") or "ACTIVE",
        "sort_order": int(row.get("sort_order") or 0),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def physical_store_item_rows(store_ids: Optional[list[str]] = None, active_only: bool = False) -> dict[str, list[dict]]:
    if store_ids is not None:
        ids = [str(store_id) for store_id in store_ids if store_id]
        if not ids:
            return {}
        active_clause = "AND psi.status = 'ACTIVE' AND psia.status = 'ACTIVE'" if active_only else ""
        rows = fetch_all(
            f"""
            SELECT psi.*,
                   psia.store_id AS assigned_store_id,
                   psia.status AS assignment_status,
                   psia.sort_order AS assignment_sort_order
            FROM physical_store_item_assignments psia
            JOIN physical_store_items psi ON psi.id = psia.item_id
            WHERE psia.store_id = ANY(%s::uuid[])
              {active_clause}
            ORDER BY psia.sort_order ASC, psi.sort_order ASC, psi.price ASC, psi.name ASC, psi.created_at DESC
            """,
            (ids,),
        )
        grouped: dict[str, list[dict]] = {}
        for row in rows:
            grouped.setdefault(str(row["assigned_store_id"]), []).append(serialize_physical_store_item(row))
        return grouped
    active_clause = "WHERE status = 'ACTIVE'" if active_only else ""
    rows = fetch_all(
        f"""
        SELECT *
        FROM physical_store_items
        {active_clause}
        ORDER BY sort_order ASC, price ASC, name ASC, created_at DESC
        """
    )
    return {"catalog": [serialize_physical_store_item(row) for row in rows]}


def physical_store_item_catalog_rows(active_only: bool = False) -> list[dict]:
    return physical_store_item_rows(None, active_only=active_only).get("catalog", [])


def physical_store_item_payload_values(payload: PhysicalStoreItemPayload, current: Optional[dict] = None) -> dict:
    duration_unit = normalize_product_duration_unit(payload.duration_unit)
    access_scope = normalize_product_access_scope(payload.access_scope)
    name = re.sub(r"\s+", " ", payload.name.strip())
    if not name:
        raise HTTPException(status_code=400, detail="Store item name is required.")
    allowed_barangay = normalize_barangay_label(payload.allowed_barangay)
    if access_scope == "BARANGAY_ONLY" and not allowed_barangay:
        raise HTTPException(status_code=400, detail="Choose the Barangay where this store item is allowed.")
    color = item_color_values(payload, "physical_store_items", current)
    speed = {"speed_limit_enabled": False, "speed_download_mbps": None, "speed_upload_mbps": None} if product_kind_is_iptv_only(product_kind) else speed_limit_values(payload)
    return {
        "name": name,
        "description": normalize_payment_text(payload.description, 500) or None,
        **color,
        "price": payload.price,
        "duration_value": int(payload.duration_value),
        "duration_unit": duration_unit,
        **speed,
        "access_scope": access_scope,
        "allowed_barangay": allowed_barangay if access_scope == "BARANGAY_ONLY" else None,
        "more_info_enabled": bool(payload.more_info_enabled),
        "more_info_text": normalize_payment_text(payload.more_info_text, 4000) or None,
        "status": normalize_product_status(payload.status),
        "sort_order": int(payload.sort_order or 0),
    }


def physical_stores_for_site(site_row: Optional[dict], customer_lat: Optional[float] = None, customer_lng: Optional[float] = None) -> list[dict]:
    if not site_row or not site_row.get("id"):
        return []
    rows = fetch_all(
        """
        SELECT ps.*
        , loc.location_name
        FROM physical_stores ps
        JOIN physical_store_sites pss ON pss.store_id = ps.id
        LEFT JOIN locations loc ON loc.id = ps.location_id
        WHERE ps.status = 'ACTIVE'
          AND pss.site_deployment_id = %s
        ORDER BY ps.store_name ASC, ps.created_at DESC
        """,
        (site_row["id"],),
    )
    for row in rows:
        if customer_lat is not None and customer_lng is not None and row.get("latitude") is not None and row.get("longitude") is not None:
            row["distance_meters"] = portal_distance_meters(float(customer_lat), float(customer_lng), float(row["latitude"]), float(row["longitude"]))
        else:
            row["distance_meters"] = None
    rows = sorted(
        rows,
        key=lambda row: (
            row.get("distance_meters") is None,
            float(row.get("distance_meters") or 0),
            str(row.get("store_name") or "").lower(),
        ),
    )
    site_map = store_site_rows([str(row["id"]) for row in rows])
    item_map = physical_store_item_rows([str(row["id"]) for row in rows], active_only=True)
    return [serialize_physical_store(row, site_map, item_map) for row in rows]


def store_purchase_request_items(cur, request_ids: list[str]) -> dict[str, list[dict]]:
    ids = [str(request_id) for request_id in request_ids if request_id]
    if not ids:
        return {}
    cur.execute(
        """
        SELECT *
        FROM store_purchase_request_items
        WHERE request_id = ANY(%s::uuid[])
        ORDER BY created_at ASC
        """,
        (ids,),
    )
    grouped: dict[str, list[dict]] = {}
    for row in cur.fetchall():
        request_id = str(row["request_id"])
        grouped.setdefault(request_id, []).append({
            "id": str(row["id"]),
            "request_id": request_id,
            "store_item_id": str(row["store_item_id"]) if row.get("store_item_id") else None,
            "item_name": row.get("item_name") or "",
            "item_description": row.get("item_description") or "",
            "price_centavos": int(row.get("price_centavos") or 0),
            "price_display": money_display_from_centavos(int(row.get("price_centavos") or 0)),
            "quantity": int(row.get("quantity") or 1),
            "duration_seconds": int(row.get("duration_seconds") or 0),
            **public_speed_limit(row),
            "access_scope": normalize_product_access_scope(row.get("access_scope") or "ALL_LOCATIONS"),
            "allowed_barangay": row.get("allowed_barangay"),
            "metadata": row.get("metadata_json") or {},
        })
    return grouped


def serialize_store_purchase_request(row: dict, items: Optional[list[dict]] = None) -> dict:
    if not row:
        return {}
    status = row.get("status") or "PENDING"
    expires_at = aware_utc(row.get("expires_at"))
    now = datetime.now(timezone.utc)
    expires_remaining_seconds = max(0, int((expires_at - now).total_seconds())) if expires_at else 0
    if status == "PENDING" and expires_at and expires_at <= now:
        status = "EXPIRED"
        expires_remaining_seconds = 0
    return {
        "id": str(row["id"]),
        "public_id": row.get("public_id"),
        "store_id": str(row["store_id"]) if row.get("store_id") else None,
        "store_name": row.get("store_name") or "",
        "store_image_url": row.get("store_image_url") or "",
        "store_barangay": row.get("store_barangay") or "",
        "store_municipality": row.get("store_municipality") or "",
        "request_method": row.get("request_method") or "SUBMITTED",
        "display_code": row.get("display_code") if status == "PENDING" else None,
        "qr_payload": row.get("qr_payload") if status == "PENDING" else None,
        "status": status,
        "auto_activate_if_no_time": bool(row.get("auto_activate_if_no_time")),
        "amount_centavos": int(row.get("amount_centavos") or 0),
        "amount_display": money_display_from_centavos(int(row.get("amount_centavos") or 0), row.get("currency") or "PHP"),
        "currency": row.get("currency") or "PHP",
        "total_duration_seconds": int(row.get("total_duration_seconds") or 0),
        "purchase_quantity": int(row.get("purchase_quantity") or 1),
        "customer_name": row.get("customer_name") or "",
        "customer_contact_number": row.get("customer_contact_number") or "",
        "customer_device_label": row.get("customer_device_label") or "",
        "rejection_reason": row.get("rejection_reason") or "",
        "expires_at": row.get("expires_at"),
        "expires_remaining_seconds": expires_remaining_seconds,
        "expired": status == "EXPIRED",
        "approved_at": row.get("approved_at"),
        "rejected_at": row.get("rejected_at"),
        "cancelled_at": row.get("cancelled_at"),
        "fulfilled_bag_item_id": str(row["fulfilled_bag_item_id"]) if row.get("fulfilled_bag_item_id") else None,
        "metadata": row.get("metadata_json") or {},
        "items": items or [],
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def store_purchase_request_rows(cur, where_sql: str, params: tuple, limit: int = 100, offset: int = 0) -> list[dict]:
    cur.execute(
        f"""
        SELECT spr.*,
               ps.store_name,
               ps.image_url AS store_image_url,
               ps.barangay AS store_barangay,
               ps.municipality AS store_municipality
        FROM store_purchase_requests spr
        JOIN physical_stores ps ON ps.id = spr.store_id
        {where_sql}
        ORDER BY spr.created_at DESC
        LIMIT %s
        OFFSET %s
        """,
        (*params, limit, offset),
    )
    rows = cur.fetchall()
    item_map = store_purchase_request_items(cur, [str(row["id"]) for row in rows])
    return [serialize_store_purchase_request(row, item_map.get(str(row["id"]), [])) for row in rows]


STORE_PORTAL_PAGE_SIZE_OPTIONS = {20, 50, 100, 500, 1000}


def normalize_store_portal_page_size(value: int) -> int:
    try:
        requested = int(value or 20)
    except (TypeError, ValueError):
        requested = 20
    return requested if requested in STORE_PORTAL_PAGE_SIZE_OPTIONS else 20


def store_owner_site_scope(cur, owner: dict) -> dict:
    cur.execute(
        """
        SELECT sd.id, sd.site_name, sd.omada_site_id, sd.barangay, sd.municipality
        FROM physical_store_sites pss
        JOIN site_deployments sd ON sd.id = pss.site_deployment_id
        WHERE pss.store_id = %s
        ORDER BY sd.site_name
        """,
        (owner["store_id"],),
    )
    sites = cur.fetchall()
    site_names = {normalize_payment_text(row.get("site_name"), 160).lower() for row in sites if row.get("site_name")}
    site_ids = {str(row.get("omada_site_id") or "").strip().lower() for row in sites if row.get("omada_site_id")}
    return {
        "sites": [
            {
                "id": str(row["id"]),
                "site_name": row.get("site_name"),
                "omada_site_id": row.get("omada_site_id"),
                "barangay": row.get("barangay"),
                "municipality": row.get("municipality"),
            }
            for row in sites
        ],
        "site_names": site_names,
        "omada_site_ids": site_ids,
    }


def customer_matches_store_scope(customer: dict, site_scope: dict) -> tuple[bool, list[dict]]:
    site_names = site_scope.get("site_names") or set()
    if not site_names:
        return False, []
    matched_devices = []
    for device in customer.get("devices") or []:
        device_site = normalize_payment_text(device.get("site"), 160).lower()
        if device_site and device_site in site_names:
            matched_devices.append(device)
    return bool(matched_devices), matched_devices


def store_owner_customer_rows(cur, owner: dict, tab: str, search: Optional[str], page: int, page_size: int) -> dict:
    site_scope = store_owner_site_scope(cur, owner)
    customers_payload = connected_devices(include_test=False, admin={"id": owner.get("id")})
    cur.execute(
        """
        SELECT user_id
        FROM store_owner_suki_customers
        WHERE store_id = %s
          AND status = 'ACTIVE'
        """,
        (owner["store_id"],),
    )
    suki_rows = cur.fetchall()
    suki_user_ids = {str(row["user_id"]) for row in suki_rows}
    rows = []
    now = datetime.now(timezone.utc)
    no_time_cutoff = now - timedelta(days=7)
    for customer in (customers_payload.get("customers") or []) + (customers_payload.get("without_profiles") or []):
        user_id = customer.get("user_id")
        if not user_id:
            continue
        matches_scope, matched_devices = customer_matches_store_scope(customer, site_scope)
        if not matches_scope:
            continue
        customer = {**customer, "devices": matched_devices}
        active_device_count = len([device for device in matched_devices if device.get("active")])
        remaining_seconds = int(customer.get("remaining_time_seconds") or 0)
        latest_seen = aware_utc(customer.get("latest_seen"))
        is_connected = active_device_count > 0
        is_suki = str(user_id) in suki_user_ids
        if remaining_seconds <= 0 and not is_connected and latest_seen and latest_seen < no_time_cutoff:
            include_no_time = False
        else:
            include_no_time = remaining_seconds <= 0
        row = {
            "customer_key": customer.get("customer_key"),
            "user_id": str(user_id),
            "profile_id": customer.get("profile_id"),
            "name": customer.get("name") or "Customer",
            "email": customer.get("email") or "",
            "contact_number": customer.get("contact_number") or "",
            "remaining_time_seconds": remaining_seconds,
            "remaining_time_display": format_seconds_human(remaining_seconds),
            "active_device_count": active_device_count,
            "device_count": len(matched_devices),
            "mac_count": sum(len(device.get("mac_addresses") or []) for device in matched_devices),
            "latest_seen": customer.get("latest_seen"),
            "is_connected": is_connected,
            "is_suki": is_suki,
            "devices": matched_devices,
            "site_names": sorted({device.get("site") for device in matched_devices if device.get("site")}),
            "_include_active": remaining_seconds > 0 and is_connected,
            "_include_inactive": remaining_seconds > 0 and not is_connected,
            "_include_no_time": include_no_time,
            "_include_suki": is_suki,
        }
        rows.append(row)

    clean_search = normalize_payment_text(search, 160).lower()
    if clean_search:
        rows = [
            row for row in rows
            if clean_search in " ".join([
                row.get("name") or "",
                row.get("contact_number") or "",
                row.get("email") or "",
                " ".join(row.get("site_names") or []),
                " ".join(device.get("device_name") or "" for device in row.get("devices") or []),
                " ".join(mac for device in row.get("devices") or [] for mac in (device.get("mac_addresses") or [])),
            ]).lower()
        ]

    summary = {
        "active": len([row for row in rows if row["_include_active"]]),
        "inactive": len([row for row in rows if row["_include_inactive"]]),
        "no_time": len([row for row in rows if row["_include_no_time"]]),
        "suki": len([row for row in rows if row["_include_suki"]]),
        "all": len(rows),
    }
    tab_key = str(tab or "ACTIVE").strip().upper()
    if tab_key == "INACTIVE":
        filtered = [row for row in rows if row["_include_inactive"]]
    elif tab_key == "NO_TIME":
        filtered = [row for row in rows if row["_include_no_time"]]
        filtered.sort(key=lambda item: (not item.get("is_connected"), str(item.get("latest_seen") or "")), reverse=False)
    elif tab_key == "SUKI":
        filtered = [row for row in rows if row["_include_suki"]]
    else:
        filtered = [row for row in rows if row["_include_active"]]
    if tab_key != "NO_TIME":
        filtered.sort(key=lambda item: (not item.get("is_connected"), -int(item.get("remaining_time_seconds") or 0), str(item.get("name") or "")))
    total = len(filtered)
    safe_page = max(int(page or 1), 1)
    safe_page_size = normalize_store_portal_page_size(page_size)
    start = (safe_page - 1) * safe_page_size
    paginated = filtered[start:start + safe_page_size]
    for row in paginated:
        for key in ["_include_active", "_include_inactive", "_include_no_time", "_include_suki"]:
            row.pop(key, None)
    items = physical_store_item_rows([str(owner["store_id"])], active_only=True).get(str(owner["store_id"]), [])
    return {
        "customers": paginated,
        "summary": summary,
        "items": items,
        "site_scope": {
            "sites": site_scope["sites"],
            "site_count": len(site_scope["sites"]),
        },
        "pagination": {
            "page": safe_page,
            "page_size": safe_page_size,
            "total": total,
            "total_pages": max(1, math.ceil(total / safe_page_size)),
        },
    }


def store_purchase_visible_store(cur, store_id: str, session: dict) -> dict:
    try:
        clean_store_id = str(uuid.UUID(str(store_id)))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="Invalid store.") from exc
    cur.execute(
        """
        SELECT ps.*, loc.location_name
        FROM physical_stores ps
        LEFT JOIN locations loc ON loc.id = ps.location_id
        WHERE ps.id = %s AND ps.status = 'ACTIVE'
        """,
        (clean_store_id,),
    )
    store = cur.fetchone()
    if not store:
        raise HTTPException(status_code=404, detail="Store not found or disabled.")
    site_row = site_deployment_for_portal_context(session, None)
    if site_row and site_row.get("id"):
        cur.execute(
            "SELECT 1 FROM physical_store_sites WHERE store_id = %s AND site_deployment_id = %s LIMIT 1",
            (clean_store_id, site_row["id"]),
        )
        if not cur.fetchone():
            raise HTTPException(status_code=400, detail="This store is not available in your connected site.")
    return store


def store_purchase_selection(cur, store: dict, payload_items: list[PortalStorePurchaseItemRequest], session: dict) -> dict:
    if not payload_items:
        raise HTTPException(status_code=400, detail="Choose at least one store item.")
    requested: dict[str, int] = {}
    for item in payload_items:
        try:
            item_id = str(uuid.UUID(str(item.item_id)))
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="One selected store item is invalid.") from exc
        requested[item_id] = requested.get(item_id, 0) + max(1, min(int(item.quantity or 1), 365))
    ids = list(requested.keys())
    cur.execute(
        """
        SELECT psi.*
        FROM physical_store_item_assignments psia
        JOIN physical_store_items psi ON psi.id = psia.item_id
        WHERE psia.store_id = %s
          AND psia.status = 'ACTIVE'
          AND psi.status = 'ACTIVE'
          AND psi.id = ANY(%s::uuid[])
        """,
        (store["id"], ids),
    )
    rows = cur.fetchall()
    found = {str(row["id"]): row for row in rows}
    if len(found) != len(ids):
        raise HTTPException(status_code=400, detail="One selected store item is no longer available.")
    lines = []
    amount_centavos = 0
    total_duration_seconds = 0
    total_quantity = 0
    access_scope = "ALL_LOCATIONS"
    allowed_barangay = None
    current_barangay = portal_current_barangay(session, None)
    for item_id, quantity in requested.items():
        row = found[item_id]
        item = serialize_physical_store_item(row)
        if item["access_scope"] == "BARANGAY_ONLY":
            if item.get("allowed_barangay") and current_barangay and barangay_key(item["allowed_barangay"]) != barangay_key(current_barangay):
                raise HTTPException(status_code=400, detail=f"{item['name']} is only available in {item['allowed_barangay']}.")
            access_scope = "BARANGAY_ONLY"
            allowed_barangay = item.get("allowed_barangay") or current_barangay
        line_amount = payment_amount_centavos(item["price"]) * quantity
        line_duration = int(item["duration_seconds"] or 0) * quantity
        amount_centavos += line_amount
        total_duration_seconds += line_duration
        total_quantity += quantity
        lines.append({
            "row": row,
            "item": item,
            "quantity": quantity,
            "price_centavos": payment_amount_centavos(item["price"]),
            "line_amount_centavos": line_amount,
            "duration_seconds": line_duration,
        })
    if not lines or amount_centavos <= 0 or total_duration_seconds <= 0:
        raise HTTPException(status_code=400, detail="Selected store items must have price and time.")
    return {
        "lines": lines,
        "amount_centavos": amount_centavos,
        "total_duration_seconds": total_duration_seconds,
        "total_quantity": total_quantity,
        "access_scope": access_scope,
        "allowed_barangay": allowed_barangay,
    }


def create_customer_bag_item_from_store_purchase(cur, purchase: dict, items: list[dict], session: dict, user: dict, owner: Optional[dict], request: Request) -> dict:
    if purchase.get("fulfilled_bag_item_id"):
        cur.execute("SELECT * FROM customer_bag_items WHERE id = %s", (purchase["fulfilled_bag_item_id"],))
        existing = cur.fetchone()
        if existing:
            return existing
    ensure_customer_bag_settings(cur, user["id"])
    cur.execute(
        """
        SELECT COALESCE(MAX(priority), 0) + 100 AS next_priority
        FROM customer_bag_items
        WHERE user_id = %s AND status = 'QUEUED'
        """,
        (user["id"],),
    )
    priority = int((cur.fetchone() or {}).get("next_priority") or 100)
    primary_name = items[0]["item_name"] if len(items) == 1 else f"{len(items)} store items"
    quantity = int(purchase.get("purchase_quantity") or 1)
    speed = strongest_speed_limit(items)
    color = serialize_item_color(items[0] if items else None)
    metadata = {
        "store_purchase_request_id": purchase.get("public_id"),
        "request_method": purchase.get("request_method"),
        "store_id": str(purchase.get("store_id")),
        "store_name": purchase.get("store_name"),
        "approved_by_owner_id": str((owner or {}).get("id")) if owner else None,
        "items": sanitize_summary(items),
    }
    cur.execute(
        """
        INSERT INTO customer_bag_items(
            user_id, portal_session_id, product_name, product_category_name, source, status, priority,
            duration_seconds, remaining_seconds, access_scope, allowed_barangay,
            purchase_quantity, amount_centavos, currency,
            item_color_key, item_color_hex,
            speed_limit_enabled, speed_download_mbps, speed_upload_mbps, speed_limit_status,
            metadata_json
        )
        VALUES (%s, %s, %s, %s, 'STORE_PURCHASE', 'QUEUED', %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        RETURNING *
        """,
        (
            user["id"],
            session["id"] if session else purchase.get("portal_session_id"),
            primary_name,
            purchase.get("store_name") or "Store Purchase",
            priority,
            int(purchase.get("total_duration_seconds") or 0),
            int(purchase.get("total_duration_seconds") or 0),
            normalize_product_access_scope((purchase.get("metadata_json") or {}).get("access_scope") or "ALL_LOCATIONS"),
            (purchase.get("metadata_json") or {}).get("allowed_barangay"),
            quantity,
            int(purchase.get("amount_centavos") or 0),
            purchase.get("currency") or "PHP",
            color["item_color_key"],
            color["item_color_hex"],
            speed["speed_limit_enabled"],
            speed["speed_download_mbps"],
            speed["speed_upload_mbps"],
            "PENDING" if speed["speed_limit_enabled"] else "NOT_REQUIRED",
            Json(metadata),
        ),
    )
    item = cur.fetchone()
    create_customer_bag_event(cur, user["id"], item["id"], session["id"] if session else None, "STORE_PURCHASE_APPROVED", "Store purchase added to My WiFi Bag.", metadata=metadata)
    return item


def physical_store_sales_stats(store_ids: list[str]) -> dict[str, dict]:
    ids = [str(store_id) for store_id in store_ids if store_id]
    if not ids:
        return {}
    rows = fetch_all(
        """
        SELECT
            physical_store_id,
            COALESCE(SUM(amount_centavos), 0)::bigint AS total_sales_centavos,
            COALESCE(SUM(
                CASE
                    WHEN COALESCE(paid_at, updated_at, created_at) >= date_trunc('month', now())
                    THEN amount_centavos
                    ELSE 0
                END
            ), 0)::bigint AS monthly_sales_centavos,
            COUNT(*)::int AS order_count,
            COUNT(DISTINCT COALESCE(user_id::text, NULLIF(customer_contact_number, ''), NULLIF(client_mac, ''), public_order_id))::int AS customer_count,
            MAX(COALESCE(paid_at, updated_at, created_at)) AS last_sale_at
        FROM payment_orders
        WHERE status = 'PAID'
          AND physical_store_id = ANY(%s::uuid[])
        GROUP BY physical_store_id
        """,
        (ids,),
    )
    stats = {}
    for row in rows:
        store_id = str(row["physical_store_id"])
        total_sales_centavos = int(row.get("total_sales_centavos") or 0)
        monthly_sales_centavos = int(row.get("monthly_sales_centavos") or 0)
        stats[store_id] = {
            "total_sales_centavos": total_sales_centavos,
            "total_sales_display": money_display_from_centavos(total_sales_centavos),
            "monthly_sales_centavos": monthly_sales_centavos,
            "monthly_sales_display": money_display_from_centavos(monthly_sales_centavos),
            "order_count": int(row.get("order_count") or 0),
            "customer_count": int(row.get("customer_count") or 0),
            "last_sale_at": row.get("last_sale_at"),
        }
    return stats


def physical_store_map_payload(stores: list[dict], include_sales: bool = False) -> dict:
    store_ids = [store["id"] for store in stores if store.get("id")]
    stats_map = physical_store_sales_stats(store_ids) if include_sales else {}
    rows = []
    for store in stores:
        mapped = store.get("latitude") is not None and store.get("longitude") is not None
        stats = stats_map.get(store["id"], {
            "total_sales_centavos": 0,
            "total_sales_display": money_display_from_centavos(0),
            "monthly_sales_centavos": 0,
            "monthly_sales_display": money_display_from_centavos(0),
            "order_count": 0,
            "customer_count": 0,
            "last_sale_at": None,
        })
        row = {
            **store,
            "mapped": mapped,
            "map_latitude": store.get("latitude"),
            "map_longitude": store.get("longitude"),
            "display_name": store.get("store_name") or "Physical Store",
            "name": store.get("store_name") or "Physical Store",
            "state": store.get("status") or "ACTIVE",
            "sales": stats,
            "total_sales_centavos": stats["total_sales_centavos"],
            "total_sales_display": stats["total_sales_display"],
            "monthly_sales_centavos": stats["monthly_sales_centavos"],
            "monthly_sales_display": stats["monthly_sales_display"],
            "order_count": stats["order_count"],
            "customer_count": stats["customer_count"],
            "last_sale_at": stats["last_sale_at"],
        }
        rows.append(row)
    summary_sales = sum(int((store.get("sales") or {}).get("total_sales_centavos") or 0) for store in rows)
    summary_monthly_sales = sum(int((store.get("sales") or {}).get("monthly_sales_centavos") or 0) for store in rows)
    return {
        "stores": rows,
        "mapped": [store for store in rows if store.get("mapped")],
        "summary": {
            "total": len(rows),
            "active": len([store for store in rows if store.get("status") == "ACTIVE"]),
            "disabled": len([store for store in rows if store.get("status") == "DISABLED"]),
            "mapped": len([store for store in rows if store.get("mapped")]),
            "with_coordinates": len([store for store in rows if store.get("mapped")]),
            "total_sales_centavos": summary_sales,
            "total_sales_display": money_display_from_centavos(summary_sales),
            "monthly_sales_centavos": summary_monthly_sales,
            "monthly_sales_display": money_display_from_centavos(summary_monthly_sales),
            "order_count": sum(int((store.get("sales") or {}).get("order_count") or 0) for store in rows),
            "customer_count": sum(int((store.get("sales") or {}).get("customer_count") or 0) for store in rows),
        },
    }


PHYSICAL_STORE_IMAGE_MAX_BYTES = 2 * 1024 * 1024
PHYSICAL_STORE_IMAGE_TYPES = {
    "image/png": ".png",
    "image/jpeg": ".jpg",
    "image/webp": ".webp",
}


def save_physical_store_image(file: UploadFile, store_id: str) -> str:
    suffix = PHYSICAL_STORE_IMAGE_TYPES.get(file.content_type or "")
    if not suffix:
        filename_suffix = Path(file.filename or "").suffix.lower()
        if filename_suffix in {".png", ".jpg", ".jpeg", ".webp"}:
            suffix = ".jpg" if filename_suffix == ".jpeg" else filename_suffix
    if not suffix:
        raise HTTPException(status_code=400, detail="Upload a PNG, JPG, or WebP image.")

    key = f"physical-store-{store_id}"
    tmp_path = UPLOAD_DIR / f"{key}.tmp"
    final_path = UPLOAD_DIR / f"{key}{suffix}"
    size = 0
    try:
        with tmp_path.open("wb") as out:
            while True:
                chunk = file.file.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > PHYSICAL_STORE_IMAGE_MAX_BYTES:
                    raise HTTPException(status_code=400, detail="Store image is too large. Use WebP, JPG, or PNG up to 2 MB.")
                out.write(chunk)
        for old_path in UPLOAD_DIR.glob(f"{key}.*"):
            if old_path != tmp_path:
                old_path.unlink(missing_ok=True)
        tmp_path.replace(final_path)
    except HTTPException:
        tmp_path.unlink(missing_ok=True)
        raise
    except Exception as exc:
        tmp_path.unlink(missing_ok=True)
        raise HTTPException(status_code=400, detail=f"Image upload failed: {exc}") from exc
    return f"/api/uploads/{final_path.name}"


def money_display_from_centavos(value: int, currency: str = "PHP") -> str:
    amount = (int(value or 0) / 100)
    return f"{currency} {amount:,.2f}"


def serialize_sales_order(row: dict) -> dict:
    amount_centavos = int(row.get("amount_centavos") or 0)
    commission_centavos = int(row.get("commission_centavos") or 0)
    net_amount_centavos = max(0, amount_centavos - commission_centavos)
    commission_type = row.get("commission_type") or None
    mac = normalize_mac_if_valid(row.get("client_mac"))
    device_name = (
        preferred_device_name(row.get("device_name"))
        or preferred_device_name(row.get("omada_device_name"))
        or preferred_device_name(infer_device_name_from_user_agent(row.get("user_agent")))
        or preferred_device_name(mac)
        or "Unprofiled device"
    )
    profile_name = preferred_device_name(row.get("profile_display_name")) or ""
    customer_name = preferred_device_name(row.get("customer_name")) or profile_name or ""
    profile_contact = row.get("profile_contact_number") or ""
    profile_email = row.get("profile_email") or ""
    return {
        "id": str(row["id"]),
        "public_order_id": row["public_order_id"],
        "sale_channel": row.get("sale_channel") or ("PHYSICAL_STORE" if row.get("physical_store_id") else "ONLINE"),
        "sale_channel_label": "Physical Store" if (row.get("sale_channel") == "PHYSICAL_STORE" or row.get("physical_store_id")) else "Online",
        "physical_store_id": str(row["physical_store_id"]) if row.get("physical_store_id") else None,
        "physical_store_name": row.get("physical_store_name") or "",
        "buyer_user_id": str(row["user_id"]) if row.get("user_id") else None,
        "customer_profile_id": str(row["customer_profile_id"]) if row.get("customer_profile_id") else None,
        "profile_display_name": profile_name,
        "profile_contact_number": profile_contact,
        "profile_email": profile_email,
        "sale_at": row.get("sale_at"),
        "status": row["status"],
        "fulfillment_status": row["fulfillment_status"],
        "payment_method": row["payment_method"],
        "amount_centavos": amount_centavos,
        "amount_display": money_display_from_centavos(amount_centavos, row.get("currency") or "PHP"),
        "gross_amount_centavos": amount_centavos,
        "gross_amount_display": money_display_from_centavos(amount_centavos, row.get("currency") or "PHP"),
        "commission_type": commission_type,
        "commission_type_label": store_commission_type_label(commission_type) if commission_type else "",
        "commission_value": float(row.get("commission_value") or 0),
        "commission_centavos": commission_centavos,
        "commission_display": money_display_from_centavos(commission_centavos, row.get("currency") or "PHP"),
        "net_amount_centavos": net_amount_centavos,
        "net_amount_display": money_display_from_centavos(net_amount_centavos, row.get("currency") or "PHP"),
        "currency": row.get("currency") or "PHP",
        "product_name": row.get("product_name"),
        "product_category_name": row.get("product_category_name") or "",
        "product_category_access_scope": row.get("product_category_access_scope") or "ALL_LOCATIONS",
        "product_category_barangay": row.get("product_category_barangay") or "",
        "duration_seconds": int(row.get("duration_seconds") or 0),
        "site_name": row.get("site_name") or "Unknown Site",
        "barangay": row.get("barangay") or "Unknown Barangay",
        "customer_name": customer_name,
        "device_name": device_name,
        "customer_display_name": customer_name or device_name,
        "customer_contact_number": row.get("customer_contact_number") or profile_contact,
        "customer_email": row.get("customer_email") or profile_email,
        "client_mac": mac or row.get("client_mac") or "",
        "client_ip": str(row.get("client_ip") or ""),
    }


SALES_REPORTING_DEFAULT_SETTINGS = {
    "telegram_enabled": False,
    "telegram_bot_token_encrypted": None,
    "telegram_chat_id": "",
    "daily_report_enabled": False,
    "report_time": "20:00",
    "include_site_breakdown": True,
    "include_barangay_breakdown": True,
    "last_test_status": None,
    "last_test_at": None,
    "last_test_error": None,
}


def sales_reporting_store() -> dict:
    row = fetch_one("SELECT value FROM app_settings WHERE key = 'sales_reporting'")
    value = row["value"] if row and isinstance(row["value"], dict) else {}
    store = {**SALES_REPORTING_DEFAULT_SETTINGS, **value}
    store["telegram_enabled"] = bool(store.get("telegram_enabled"))
    store["daily_report_enabled"] = bool(store.get("daily_report_enabled"))
    store["telegram_chat_id"] = normalize_payment_text(store.get("telegram_chat_id"), 120)
    store["report_time"] = normalize_payment_text(store.get("report_time") or "20:00", 20)
    store["include_site_breakdown"] = bool(store.get("include_site_breakdown", True))
    store["include_barangay_breakdown"] = bool(store.get("include_barangay_breakdown", True))
    return store


def save_sales_reporting_store(store: dict):
    existing = sales_reporting_store()
    token = normalize_payment_text(store.get("telegram_bot_token"), 300)
    encrypted_token = encrypt_secret(token) if token else existing.get("telegram_bot_token_encrypted")
    if store.get("clear_telegram_bot_token"):
        encrypted_token = None
    clean = {
        "telegram_enabled": bool(store.get("telegram_enabled")),
        "telegram_bot_token_encrypted": encrypted_token,
        "telegram_chat_id": normalize_payment_text(store.get("telegram_chat_id"), 120),
        "daily_report_enabled": bool(store.get("daily_report_enabled")),
        "report_time": normalize_payment_text(store.get("report_time") or "20:00", 20),
        "include_site_breakdown": bool(store.get("include_site_breakdown", True)),
        "include_barangay_breakdown": bool(store.get("include_barangay_breakdown", True)),
        "last_test_status": store.get("last_test_status", existing.get("last_test_status")),
        "last_test_at": store.get("last_test_at", existing.get("last_test_at")),
        "last_test_error": store.get("last_test_error", existing.get("last_test_error")),
    }
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO app_settings(key, value, updated_at)
                VALUES ('sales_reporting', %s, now())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
                """,
                (Json(clean),),
            )


def public_sales_reporting_settings(store: Optional[dict] = None) -> dict:
    store = store or sales_reporting_store()
    token = decrypt_secret(store.get("telegram_bot_token_encrypted"))
    return {
        "telegram_enabled": bool(store.get("telegram_enabled")),
        "telegram_bot_token_configured": bool(token),
        "telegram_bot_token_hint": mask_payment_secret(token),
        "telegram_chat_id": store.get("telegram_chat_id") or "",
        "daily_report_enabled": bool(store.get("daily_report_enabled")),
        "report_time": store.get("report_time") or "20:00",
        "include_site_breakdown": bool(store.get("include_site_breakdown", True)),
        "include_barangay_breakdown": bool(store.get("include_barangay_breakdown", True)),
        "last_test_status": store.get("last_test_status"),
        "last_test_at": store.get("last_test_at"),
        "last_test_error": store.get("last_test_error"),
    }


def sales_telegram_report_text(sales_payload: dict, settings: dict) -> str:
    kpis = sales_payload.get("kpis") or {}
    lines = [
        "3JCentralPisowifi Sales Report",
        f"Range: last {sales_payload.get('range_days')} days",
        f"Gross sales: {kpis.get('gross_sales_display') or 'PHP 0.00'}",
        f"Commission: {kpis.get('commission_display') or 'PHP 0.00'}",
        f"Net income: {kpis.get('net_income_display') or 'PHP 0.00'}",
        f"Paid orders: {kpis.get('paid_orders') or 0}",
        f"Today: {kpis.get('today_sales_display') or 'PHP 0.00'}",
        f"This month: {kpis.get('month_sales_display') or 'PHP 0.00'}",
    ]
    if settings.get("include_site_breakdown") and sales_payload.get("sales_by_site"):
        lines.append("")
        lines.append("Top sites:")
        for row in (sales_payload.get("sales_by_site") or [])[:5]:
            lines.append(f"- {row.get('label')}: {row.get('amount_display')} ({row.get('order_count')} orders)")
    if settings.get("include_barangay_breakdown") and sales_payload.get("sales_by_barangay"):
        lines.append("")
        lines.append("Top barangays:")
        for row in (sales_payload.get("sales_by_barangay") or [])[:5]:
            lines.append(f"- {row.get('label')}: {row.get('amount_display')} ({row.get('order_count')} orders)")
    return "\n".join(lines)


def send_sales_telegram_report(store: dict, message: str):
    token = decrypt_secret(store.get("telegram_bot_token_encrypted"))
    chat_id = normalize_payment_text(store.get("telegram_chat_id"), 120)
    if not token or not chat_id:
        raise HTTPException(status_code=400, detail="Telegram bot token and chat id are required.")
    response = requests.post(
        f"https://api.telegram.org/bot{token}/sendMessage",
        json={"chat_id": chat_id, "text": message, "disable_web_page_preview": True},
        timeout=15,
    )
    if response.status_code >= 400:
        raise HTTPException(status_code=400, detail=f"Telegram send failed: HTTP {response.status_code} {response.text[:300]}")
    return sanitize_summary(response.json())


def build_sales_payload(range_days: int = 30) -> dict:
    days = max(1, min(int(range_days or 30), 365))
    params = (days,)
    base_cte = """
        WITH sales_range AS (
            SELECT %s::int AS days
        ),
        store_item_summary AS (
            SELECT
                request_id,
                string_agg(
                    CASE
                        WHEN quantity > 1 THEN quantity::text || 'x ' || item_name
                        ELSE item_name
                    END,
                    ', ' ORDER BY created_at ASC
                ) AS item_names
            FROM store_purchase_request_items
            GROUP BY request_id
        ),
        sale_rows AS (
            SELECT
                po.id,
                po.public_order_id,
                po.user_id,
                po.status,
                po.fulfillment_status,
                po.payment_method,
                po.amount_centavos,
                po.currency,
                po.product_name,
                po.product_category_name,
                po.product_category_access_scope,
                po.product_category_barangay,
                po.duration_seconds,
                po.client_mac,
                po.client_ip,
                po.user_agent,
                COALESCE(po.paid_at, po.updated_at, po.created_at) AS sale_at,
                COALESCE(sd.site_name, ps.omada_site_name, ps.site, 'Unknown Site') AS site_name,
                COALESCE(sd.barangay, loc.barangay, 'Unknown Barangay') AS barangay,
                po.customer_name,
                po.customer_contact_number,
                po.customer_email,
                p.id AS customer_profile_id,
                p.display_name AS profile_display_name,
                p.email AS profile_email,
                p.contact_number AS profile_contact_number,
                po.physical_store_id,
                po_store.store_name AS physical_store_name,
                po_store.commission_type,
                COALESCE(po_store.commission_value, 0)::numeric AS commission_value,
                CASE
                    WHEN po_store.id IS NOT NULL AND po_store.commission_type = 'PERCENT_OF_SALES'
                    THEN GREATEST(0, ROUND(po.amount_centavos * COALESCE(po_store.commission_value, 0) / 100.0)::bigint)
                    ELSE 0
                END AS commission_centavos,
                CASE WHEN po.physical_store_id IS NOT NULL THEN 'PHYSICAL_STORE' ELSE 'ONLINE' END AS sale_channel
            FROM payment_orders po
            LEFT JOIN portal_sessions ps ON ps.id = po.portal_session_id
            LEFT JOIN portal_customer_profiles p ON p.user_id = po.user_id
            LEFT JOIN physical_stores po_store ON po_store.id = po.physical_store_id
            LEFT JOIN LATERAL (
                SELECT sd.*
                FROM site_deployments sd
                WHERE (
                    COALESCE(ps.omada_site_id, '') <> ''
                    AND COALESCE(sd.omada_site_id, '') = COALESCE(ps.omada_site_id, '')
                ) OR (
                    COALESCE(ps.omada_site_name, ps.site, '') <> ''
                    AND lower(sd.site_name) = lower(COALESCE(ps.omada_site_name, ps.site, ''))
                )
                ORDER BY sd.updated_at DESC
                LIMIT 1
            ) sd ON true
            LEFT JOIN locations loc ON loc.id = sd.location_id
            WHERE po.status = 'PAID'
              AND COALESCE(po.paid_at, po.updated_at, po.created_at) >= now() - ((SELECT days FROM sales_range) * interval '1 day')
            UNION ALL
            SELECT
                spr.id,
                spr.public_id AS public_order_id,
                spr.user_id,
                'PAID'::text AS status,
                CASE WHEN spr.fulfilled_bag_item_id IS NOT NULL THEN 'FULFILLED' ELSE 'PENDING' END AS fulfillment_status,
                lower(spr.request_method)::text AS payment_method,
                spr.amount_centavos,
                spr.currency,
                COALESCE(NULLIF(store_items.item_names, ''), ps_store.store_name || ' Store Purchase') AS product_name,
                ps_store.store_name AS product_category_name,
                COALESCE((spr.metadata_json ->> 'access_scope'), 'ALL_LOCATIONS') AS product_category_access_scope,
                spr.metadata_json ->> 'allowed_barangay' AS product_category_barangay,
                spr.total_duration_seconds AS duration_seconds,
                COALESCE(session_row.omada_client_mac, session_row.mikrotik_client_mac, session_row.client_mac) AS client_mac,
                session_row.client_ip,
                session_row.user_agent,
                COALESCE(spr.approved_at, spr.updated_at, spr.created_at) AS sale_at,
                COALESCE(sd_store.site_name, session_row.omada_site_name, session_row.site, ps_store.store_name, 'Unknown Site') AS site_name,
                COALESCE(ps_store.barangay, sd_store.barangay, loc_store.barangay, 'Unknown Barangay') AS barangay,
                spr.customer_name,
                spr.customer_contact_number,
                NULL::text AS customer_email,
                p_store.id AS customer_profile_id,
                p_store.display_name AS profile_display_name,
                p_store.email AS profile_email,
                p_store.contact_number AS profile_contact_number,
                spr.store_id AS physical_store_id,
                ps_store.store_name AS physical_store_name,
                ps_store.commission_type,
                COALESCE(ps_store.commission_value, 0)::numeric AS commission_value,
                CASE
                    WHEN ps_store.commission_type = 'PERCENT_OF_SALES'
                    THEN GREATEST(0, ROUND(spr.amount_centavos * COALESCE(ps_store.commission_value, 0) / 100.0)::bigint)
                    ELSE 0
                END AS commission_centavos,
                'PHYSICAL_STORE'::text AS sale_channel
            FROM store_purchase_requests spr
            JOIN physical_stores ps_store ON ps_store.id = spr.store_id
            LEFT JOIN store_item_summary store_items ON store_items.request_id = spr.id
            LEFT JOIN portal_sessions session_row ON session_row.id = spr.portal_session_id
            LEFT JOIN portal_customer_profiles p_store ON p_store.user_id = spr.user_id
            LEFT JOIN LATERAL (
                SELECT sd.*
                FROM site_deployments sd
                WHERE EXISTS (
                    SELECT 1
                    FROM physical_store_sites psa
                    WHERE psa.store_id = spr.store_id
                      AND psa.site_deployment_id = sd.id
                )
                ORDER BY sd.updated_at DESC
                LIMIT 1
            ) sd_store ON true
            LEFT JOIN locations loc_store ON loc_store.id = sd_store.location_id
            WHERE spr.status = 'APPROVED'
              AND COALESCE(spr.approved_at, spr.updated_at, spr.created_at) >= now() - ((SELECT days FROM sales_range) * interval '1 day')
        ),
        fixed_commission_rows AS (
            SELECT
                physical_store_id,
                date_trunc('month', sale_at) AS month_start,
                MAX(ROUND(COALESCE(commission_value, 0) * 100)::bigint) AS fixed_commission_centavos
            FROM sale_rows
            WHERE sale_channel = 'PHYSICAL_STORE'
              AND commission_type = 'FIXED_MONTHLY'
              AND physical_store_id IS NOT NULL
            GROUP BY physical_store_id, date_trunc('month', sale_at)
        )
    """
    kpi_row = fetch_one(
        base_cte
        + """
        SELECT
            COALESCE(SUM(amount_centavos), 0)::bigint AS gross_sales_centavos,
            COALESCE(SUM(commission_centavos), 0)::bigint AS percent_commission_centavos,
            COALESCE((SELECT SUM(fixed_commission_centavos) FROM fixed_commission_rows), 0)::bigint AS fixed_commission_centavos,
            COUNT(*)::int AS paid_orders,
            COUNT(*) FILTER (WHERE fulfillment_status = 'FULFILLED')::int AS fulfilled_orders,
            COUNT(*) FILTER (WHERE fulfillment_status = 'FAILED')::int AS failed_fulfillments,
            COALESCE(ROUND(AVG(amount_centavos)), 0)::bigint AS average_order_centavos,
            COALESCE(SUM(amount_centavos) FILTER (WHERE sale_at >= date_trunc('day', now())), 0)::bigint AS today_sales_centavos,
            COALESCE(SUM(commission_centavos) FILTER (WHERE sale_at >= date_trunc('day', now())), 0)::bigint AS today_percent_commission_centavos,
            COALESCE(SUM(amount_centavos) FILTER (WHERE sale_at >= date_trunc('month', now())), 0)::bigint AS month_sales_centavos,
            COALESCE(SUM(commission_centavos) FILTER (WHERE sale_at >= date_trunc('month', now())), 0)::bigint AS month_percent_commission_centavos,
            COALESCE((SELECT SUM(fixed_commission_centavos) FROM fixed_commission_rows WHERE month_start = date_trunc('month', now())), 0)::bigint AS month_fixed_commission_centavos
        FROM sale_rows
        """,
        params,
    ) or {}
    daily_rows = fetch_all(
        base_cte
        + """
        SELECT to_char(date_trunc('day', sale_at), 'YYYY-MM-DD') AS label,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos,
               COUNT(*)::int AS order_count
        FROM sale_rows
        GROUP BY 1
        ORDER BY 1
        """,
        params,
    )
    site_rows = fetch_all(
        base_cte
        + """
        SELECT site_name AS label,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos,
               COUNT(*)::int AS order_count
        FROM sale_rows
        GROUP BY 1
        ORDER BY amount_centavos DESC, order_count DESC, label ASC
        LIMIT 20
        """,
        params,
    )
    barangay_rows = fetch_all(
        base_cte
        + """
        SELECT barangay AS label,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos,
               COUNT(*)::int AS order_count
        FROM sale_rows
        GROUP BY 1
        ORDER BY amount_centavos DESC, order_count DESC, label ASC
        LIMIT 20
        """,
        params,
    )
    store_rows = fetch_all(
        base_cte
        + """
        SELECT COALESCE(physical_store_name, 'Unknown Store') AS label,
               physical_store_id,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos,
               COUNT(*)::int AS order_count
        FROM sale_rows
        WHERE sale_channel = 'PHYSICAL_STORE'
        GROUP BY 1, 2
        ORDER BY amount_centavos DESC, order_count DESC, label ASC
        """,
        params,
    )
    site_daily_rows = fetch_all(
        base_cte
        + """
        SELECT to_char(date_trunc('day', sale_at), 'YYYY-MM-DD') AS date,
               site_name AS label,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos
        FROM sale_rows
        GROUP BY 1, 2
        ORDER BY 1, 2
        """,
        params,
    )
    store_daily_rows = fetch_all(
        base_cte
        + """
        SELECT to_char(date_trunc('day', sale_at), 'YYYY-MM-DD') AS date,
               COALESCE(physical_store_name, 'Unknown Store') AS label,
               physical_store_id,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos
        FROM sale_rows
        WHERE sale_channel = 'PHYSICAL_STORE'
        GROUP BY 1, 2, 3
        ORDER BY 1, 2
        """,
        params,
    )
    barangay_daily_rows = fetch_all(
        base_cte
        + """
        SELECT to_char(date_trunc('day', sale_at), 'YYYY-MM-DD') AS date,
               barangay AS label,
               COALESCE(SUM(amount_centavos), 0)::bigint AS amount_centavos
        FROM sale_rows
        GROUP BY 1, 2
        ORDER BY 1, 2
        """,
        params,
    )
    order_rows = fetch_all(
        base_cte
        + """
        SELECT *
        FROM sale_rows
        ORDER BY sale_at DESC
        LIMIT 200
        """,
        params,
    )
    omada_name_by_mac = fetch_omada_client_name_map()
    for row in order_rows:
        mac = normalize_mac_if_valid(row.get("client_mac"))
        row["device_name"] = omada_name_by_mac.get(mac) if mac else None

    def series_rows(rows):
        values = []
        for row in rows:
            mapped = dict(row)
            if mapped.get("physical_store_id"):
                mapped["physical_store_id"] = str(mapped["physical_store_id"])
            mapped["amount_centavos"] = int(row.get("amount_centavos") or 0)
            mapped["amount_display"] = money_display_from_centavos(int(row.get("amount_centavos") or 0))
            values.append(mapped)
        return values

    gross = int(kpi_row.get("gross_sales_centavos") or 0)
    percent_commission = int(kpi_row.get("percent_commission_centavos") or 0)
    fixed_commission = int(kpi_row.get("fixed_commission_centavos") or 0)
    commission = percent_commission + fixed_commission
    net = max(0, gross - commission)
    average = int(kpi_row.get("average_order_centavos") or 0)
    today = int(kpi_row.get("today_sales_centavos") or 0)
    today_commission = int(kpi_row.get("today_percent_commission_centavos") or 0)
    today_net = max(0, today - today_commission)
    month = int(kpi_row.get("month_sales_centavos") or 0)
    month_commission = int(kpi_row.get("month_percent_commission_centavos") or 0) + int(kpi_row.get("month_fixed_commission_centavos") or 0)
    month_net = max(0, month - month_commission)
    return {
        "range_days": days,
        "kpis": {
            "gross_sales_centavos": gross,
            "gross_sales_display": money_display_from_centavos(gross),
            "commission_centavos": commission,
            "commission_display": money_display_from_centavos(commission),
            "percent_commission_centavos": percent_commission,
            "percent_commission_display": money_display_from_centavos(percent_commission),
            "fixed_commission_centavos": fixed_commission,
            "fixed_commission_display": money_display_from_centavos(fixed_commission),
            "net_income_centavos": net,
            "net_income_display": money_display_from_centavos(net),
            "paid_orders": int(kpi_row.get("paid_orders") or 0),
            "fulfilled_orders": int(kpi_row.get("fulfilled_orders") or 0),
            "failed_fulfillments": int(kpi_row.get("failed_fulfillments") or 0),
            "average_order_centavos": average,
            "average_order_display": money_display_from_centavos(average),
            "today_sales_centavos": today,
            "today_sales_display": money_display_from_centavos(today),
            "today_commission_centavos": today_commission,
            "today_commission_display": money_display_from_centavos(today_commission),
            "today_net_income_centavos": today_net,
            "today_net_income_display": money_display_from_centavos(today_net),
            "month_sales_centavos": month,
            "month_sales_display": money_display_from_centavos(month),
            "month_commission_centavos": month_commission,
            "month_commission_display": money_display_from_centavos(month_commission),
            "month_net_income_centavos": month_net,
            "month_net_income_display": money_display_from_centavos(month_net),
        },
        "daily_sales": series_rows(daily_rows),
        "sales_by_site": series_rows(site_rows),
        "sales_by_barangay": series_rows(barangay_rows),
        "sales_by_store": series_rows(store_rows),
        "daily_sales_by_site": series_rows(site_daily_rows),
        "daily_sales_by_barangay": series_rows(barangay_daily_rows),
        "daily_sales_by_store": series_rows(store_daily_rows),
        "orders": [serialize_sales_order(row) for row in order_rows],
    }


@app.get("/api/sales")
def get_sales(range_days: int = 30, admin=Depends(current_admin)):
    return build_sales_payload(range_days)


@app.get("/api/sales/settings")
def get_sales_settings(admin=Depends(current_admin)):
    return public_sales_reporting_settings()


@app.put("/api/sales/settings")
def update_sales_settings(payload: SalesReportingSettingsUpdate, admin=Depends(current_admin)):
    save_sales_reporting_store(payload.model_dump())
    audit(admin["id"], "update_sales_reporting_settings", "sales_reporting", None, {"telegram_enabled": payload.telegram_enabled, "daily_report_enabled": payload.daily_report_enabled})
    return public_sales_reporting_settings()


@app.post("/api/sales/telegram-test")
def test_sales_telegram_report(admin=Depends(current_admin)):
    store = sales_reporting_store()
    report = build_sales_payload(30)
    message = sales_telegram_report_text(report, store)
    try:
        result = send_sales_telegram_report(store, message)
        store["last_test_status"] = "SUCCESS"
        store["last_test_at"] = datetime.now(timezone.utc).isoformat()
        store["last_test_error"] = None
        save_sales_reporting_store(store)
        audit(admin["id"], "test_sales_telegram_report", "sales_reporting", None, {"status": "SUCCESS"})
        return {"status": "SUCCESS", "message": "Telegram sales test report sent.", "result": result, "settings": public_sales_reporting_settings()}
    except HTTPException as exc:
        store["last_test_status"] = "FAILED"
        store["last_test_at"] = datetime.now(timezone.utc).isoformat()
        store["last_test_error"] = str(exc.detail)
        save_sales_reporting_store(store)
        raise


@app.post("/api/sales/clear")
def clear_sales(payload: SalesClearRequest, admin=Depends(current_admin)):
    if (payload.confirmation or "").strip().upper() != "CLEAR SALES":
        raise HTTPException(status_code=400, detail="Type CLEAR SALES to confirm clearing local sales records.")
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM payment_orders RETURNING id")
            deleted_count = cur.rowcount
    audit(admin["id"], "clear_sales_records", "payment_orders", None, {"deleted_count": deleted_count})
    return {"status": "CLEARED", "deleted_count": deleted_count}


def current_configured_customer_ssid_names() -> set[str]:
    names: set[str] = set()

    def add_from_wifi_config(row: Optional[dict]):
        if not row:
            return
        if row.get("use_same_ssid"):
            value = str(row.get("same_ssid_name") or "").strip()
            if value:
                names.add(value)
            return
        for field in ("ssid_2g", "ssid_5g"):
            value = str(row.get(field) or "").strip()
            if value:
                names.add(value)

    try:
        config = fetch_one("SELECT * FROM ap_deployment_configuration WHERE id = 1")
        if config and (config.get("ssid_scope") or "GLOBAL") == "PER_SITE":
            site_rows = fetch_all(
                """
                SELECT sw.*
                FROM ap_site_wifi_configuration sw
                JOIN site_deployments sd ON sd.id = sw.site_id
                WHERE sd.deployment_status <> 'INACTIVE'
                """
            )
            for row in site_rows:
                add_from_wifi_config(row)
            if not names:
                add_from_wifi_config(config)
        else:
            add_from_wifi_config(config)
    except Exception:
        return set()
    return names


def session_ssid_if_current(value: Optional[str], configured_ssids: Optional[set[str]] = None) -> Optional[str]:
    ssid = str(value or "").strip()
    if not ssid:
        return None
    configured = {str(item or "").strip().lower() for item in (configured_ssids or set()) if str(item or "").strip()}
    if configured and ssid.lower() not in configured:
        return None
    return ssid


def omada_client_by_session_network(client_mac: Optional[str], client_ip: Optional[str], omada_client_by_mac: Optional[dict]) -> Optional[dict]:
    clients = omada_client_by_mac or {}
    mac = normalize_mac_if_valid(client_mac)
    if mac and clients.get(mac):
        return clients[mac]
    ip = str(client_ip or "").strip()
    if not ip:
        return None
    matches = [row for row in clients.values() if str(row.get("client_ip") or "").strip() == ip]
    active_matches = [row for row in matches if row.get("active")]
    if len(active_matches) == 1:
        return active_matches[0]
    if len(matches) == 1:
        return matches[0]
    return None


def apply_current_network_to_access_row(row: dict, omada_client_by_mac: Optional[dict], configured_ssids: Optional[set[str]]) -> dict:
    current_client = omada_client_by_session_network(row.get("client_mac"), row.get("client_ip"), omada_client_by_mac)
    stale_session_ssid = row.get("ssid")
    if current_client:
        for field, source_field in [
            ("client_mac", "client_mac"),
            ("client_ip", "client_ip"),
            ("ap_mac", "ap_mac"),
            ("ap_name", "ap_name"),
            ("ssid", "ssid"),
            ("site", "site"),
        ]:
            if current_client.get(source_field):
                row[field] = current_client[source_field]
        row["network_source"] = "OMADA_CURRENT"
        row["stale_session_ssid"] = None
        return row
    row["ssid"] = session_ssid_if_current(row.get("ssid"), configured_ssids)
    row["network_source"] = "PORTAL_SESSION" if row.get("ssid") else "STALE_SESSION_HIDDEN"
    if stale_session_ssid and not row.get("ssid"):
        row["stale_session_ssid"] = stale_session_ssid
    return row


def customer_access_source_label(source: Optional[str], voucher_code: Optional[str] = None) -> str:
    clean_source = str(source or "").strip().upper()
    code = str(voucher_code or "").strip().upper()
    if clean_source == "PAYMENT":
        return "Product"
    if clean_source == "WELCOME_GIFT" or code.startswith("GIFT-"):
        return "Welcome Gift"
    if clean_source == "VOUCHER":
        return "Voucher"
    return "Voucher" if code and not code.startswith("BAG-") else "Product"


def active_access_rows(omada_client_by_mac: Optional[dict] = None) -> list[dict]:
    if omada_client_by_mac is None:
        omada_client_by_mac = fetch_omada_client_snapshot_map()
    configured_ssids = current_configured_customer_ssid_names()
    rows: list[dict] = []
    bag_rows = fetch_all(
        """
        SELECT i.id AS bag_item_id,
               i.user_id,
               p.id AS customer_profile_id,
               p.display_name AS customer_name,
               p.email AS customer_email,
               p.contact_number AS customer_contact_number,
               i.portal_session_id,
               s.public_session_id,
               i.voucher_id,
               v.code AS voucher_code,
               i.product_name,
               i.product_category_name,
               i.source AS item_source,
               i.status AS item_status,
               i.activated_at,
               i.active_until,
               GREATEST(EXTRACT(EPOCH FROM (i.active_until - now()))::int, 0) AS remaining_time_seconds,
               s.source AS portal_source,
               s.status AS session_status,
               COALESCE(s.omada_client_mac, s.mikrotik_client_mac, s.client_mac) AS client_mac,
               host(s.client_ip) AS client_ip,
               COALESCE(s.omada_ap_mac, s.ap_mac) AS ap_mac,
               s.ssid,
               COALESCE(s.omada_site_name, s.site) AS site,
               s.user_agent,
               s.omada_authorization_status,
               s.mikrotik_authorization_status
        FROM customer_bag_items i
        LEFT JOIN portal_sessions s ON s.id = i.portal_session_id
        LEFT JOIN vouchers v ON v.id = i.voucher_id
        LEFT JOIN portal_customer_profiles p ON p.user_id = i.user_id
        WHERE i.status = 'ACTIVE'
          AND i.active_until IS NOT NULL
          AND i.active_until > now()
        ORDER BY i.active_until ASC, i.activated_at DESC NULLS LAST
        LIMIT 500
        """
    )
    for row in bag_rows:
        row = dict(row)
        row["access_id"] = f"bag:{row['bag_item_id']}"
        row["access_kind"] = "BAG_ITEM"
        row["access_source"] = customer_access_source_label(row.get("item_source"), row.get("voucher_code"))
        row["display_voucher_code"] = row.get("voucher_code") if row["access_source"] != "Product" else None
        apply_current_network_to_access_row(row, omada_client_by_mac, configured_ssids)
        mac = normalize_mac_if_valid(row.get("client_mac"))
        current_client = omada_client_by_session_network(row.get("client_mac"), row.get("client_ip"), omada_client_by_mac)
        row["device_name"] = (
            preferred_device_name((current_client or {}).get("device_name"))
            or preferred_device_name(infer_device_name_from_user_agent(row.get("user_agent")))
            or preferred_device_name(row.get("customer_name"))
            or "Unknown device"
        )
        row["client_mac"] = mac or row.get("client_mac")
        row["remaining_time_seconds"] = int(row.get("remaining_time_seconds") or 0)
        rows.append(row)

    manual_rows = fetch_all(
        """
        SELECT s.id AS portal_session_id,
               s.public_session_id,
               s.user_id,
               p.id AS customer_profile_id,
               p.display_name AS customer_name,
               p.email AS customer_email,
               p.contact_number AS customer_contact_number,
               s.voucher_id,
               v.code AS voucher_code,
               COALESCE(v.note, 'Voucher access') AS product_name,
               NULL::text AS product_category_name,
               'VOUCHER' AS item_source,
               s.status AS session_status,
               COALESCE(s.omada_client_mac, s.mikrotik_client_mac, s.client_mac) AS client_mac,
               host(s.client_ip) AS client_ip,
               COALESCE(s.omada_ap_mac, s.ap_mac) AS ap_mac,
               s.ssid,
               COALESCE(s.omada_site_name, s.site) AS site,
               s.user_agent,
               s.source AS portal_source,
               s.access_granted_at AS activated_at,
               s.access_expires_at AS active_until,
               GREATEST(EXTRACT(EPOCH FROM (s.access_expires_at - now()))::int, 0) AS remaining_time_seconds,
               s.omada_authorization_status,
               s.mikrotik_authorization_status
        FROM portal_sessions s
        JOIN vouchers v ON v.id = s.voucher_id
        LEFT JOIN portal_customer_profiles p ON p.user_id = s.user_id
        WHERE s.voucher_id IS NOT NULL
          AND s.status IN ('VOUCHER_REDEEMED', 'ACCESS_GRANTED')
          AND s.access_expires_at IS NOT NULL
          AND s.access_expires_at > now()
          AND v.code NOT ILIKE %s
          AND NOT EXISTS (
              SELECT 1
              FROM customer_bag_items i
              WHERE i.status = 'ACTIVE'
                AND i.active_until IS NOT NULL
                AND i.active_until > now()
                AND (i.portal_session_id = s.id OR i.voucher_id = s.voucher_id)
          )
        ORDER BY s.access_expires_at ASC, s.updated_at DESC
        LIMIT 500
        """,
        ("BAG-%",),
    )
    for row in manual_rows:
        row = dict(row)
        row["access_id"] = f"voucher:{row['portal_session_id']}"
        row["access_kind"] = "VOUCHER_SESSION"
        row["access_source"] = customer_access_source_label("VOUCHER", row.get("voucher_code"))
        row["display_voucher_code"] = row.get("voucher_code")
        apply_current_network_to_access_row(row, omada_client_by_mac, configured_ssids)
        mac = normalize_mac_if_valid(row.get("client_mac"))
        current_client = omada_client_by_session_network(row.get("client_mac"), row.get("client_ip"), omada_client_by_mac)
        row["device_name"] = (
            preferred_device_name((current_client or {}).get("device_name"))
            or preferred_device_name(infer_device_name_from_user_agent(row.get("user_agent")))
            or preferred_device_name(row.get("customer_name"))
            or "Unknown device"
        )
        row["client_mac"] = mac or row.get("client_mac")
        row["remaining_time_seconds"] = int(row.get("remaining_time_seconds") or 0)
        rows.append(row)

    user_pass_counts: dict[str, int] = {}
    device_pass_counts: dict[str, int] = {}
    for row in rows:
        user_key = str(row.get("user_id") or "")
        if user_key:
            user_pass_counts[user_key] = user_pass_counts.get(user_key, 0) + 1
        device_key = normalize_mac_if_valid(row.get("client_mac")) or str(row.get("client_ip") or "")
        if device_key:
            device_pass_counts[device_key] = device_pass_counts.get(device_key, 0) + 1
    for row in rows:
        user_key = str(row.get("user_id") or "")
        device_key = normalize_mac_if_valid(row.get("client_mac")) or str(row.get("client_ip") or "")
        row["active_pass_count_for_customer"] = user_pass_counts.get(user_key, 1) if user_key else 1
        row["active_pass_count_for_device"] = device_pass_counts.get(device_key, 1) if device_key else row["active_pass_count_for_customer"]

    return sorted(rows, key=lambda item: item.get("active_until") or datetime.max.replace(tzinfo=timezone.utc))


def active_voucher_rows(omada_name_by_mac: Optional[dict] = None, omada_client_by_mac: Optional[dict] = None):
    if omada_client_by_mac is None:
        omada_client_by_mac = fetch_omada_client_snapshot_map()
    if omada_name_by_mac is None:
        omada_name_by_mac = {
            mac: snapshot.get("device_name")
            for mac, snapshot in (omada_client_by_mac or {}).items()
            if snapshot.get("device_name")
        } or fetch_omada_client_name_map()
    configured_ssids = current_configured_customer_ssid_names()
    rows = fetch_all(
        """
        SELECT DISTINCT ON (s.id)
               s.id AS portal_session_id,
               s.public_session_id,
               s.status AS session_status,
               s.source AS portal_source,
               COALESCE(s.omada_client_mac, s.mikrotik_client_mac, s.client_mac) AS client_mac,
               host(s.client_ip) AS client_ip,
               COALESCE(s.omada_ap_mac, s.ap_mac) AS ap_mac,
               s.ssid,
               COALESCE(s.omada_site_name, s.site) AS site,
               s.user_agent,
               s.access_granted_at,
               s.access_expires_at,
               GREATEST(EXTRACT(EPOCH FROM (s.access_expires_at - now()))::int, 0) AS remaining_time_seconds,
               v.id AS voucher_id,
               v.code AS voucher_code,
               v.voucher_type,
               v.status AS voucher_status,
               v.created_at AS voucher_created_at,
               v.redeemed_at,
               u.id AS user_id,
               u.username,
               p.id AS customer_profile_id,
               p.display_name AS customer_name,
               p.email AS customer_email,
               p.contact_number AS customer_contact_number
        FROM portal_sessions s
        JOIN vouchers v ON v.id = s.voucher_id
        LEFT JOIN users u ON u.id = s.user_id
        LEFT JOIN portal_customer_profiles p ON p.user_id = s.user_id
        WHERE s.voucher_id IS NOT NULL
          AND s.status IN ('VOUCHER_REDEEMED', 'ACCESS_GRANTED')
          AND s.access_expires_at IS NOT NULL
          AND s.access_expires_at > now()
          AND v.code NOT ILIKE %s
        ORDER BY s.id, s.access_expires_at DESC
        LIMIT 500
        """,
        ("BAG-%",),
    )
    for row in rows:
        row["client_mac"] = normalize_mac_if_valid(row.get("client_mac")) or row.get("client_mac")
        mac = normalize_mac_if_valid(row.get("client_mac"))
        current_client = (omada_client_by_mac or {}).get(mac) if mac else None
        stale_session_ssid = row.get("ssid")
        if current_client:
            for field, source_field in [
                ("client_ip", "client_ip"),
                ("ap_mac", "ap_mac"),
                ("ssid", "ssid"),
                ("site", "site"),
            ]:
                if current_client.get(source_field):
                    row[field] = current_client[source_field]
            if current_client.get("ssid"):
                row["ssid_source"] = "OMADA_CURRENT"
        if row.get("ssid_source") != "OMADA_CURRENT":
            row["ssid"] = session_ssid_if_current(row.get("ssid"), configured_ssids)
            row["ssid_source"] = "PORTAL_SESSION" if row.get("ssid") else "UNKNOWN"
        if stale_session_ssid and not row.get("ssid"):
            row["stale_session_ssid"] = stale_session_ssid
        row["device_name"] = (
            preferred_device_name((current_client or {}).get("device_name"))
            or preferred_device_name(omada_name_by_mac.get(mac) if mac else None)
            or preferred_device_name(infer_device_name_from_user_agent(row.get("user_agent")))
            or preferred_device_name(row.get("username"))
            or "Unknown device"
        )
        row["remaining_time_seconds"] = int(row.get("remaining_time_seconds") or 0)
    return sorted(rows, key=lambda item: item.get("access_expires_at") or datetime.max.replace(tzinfo=timezone.utc))


def portal_previous_mac_values(value) -> list[str]:
    items = value if isinstance(value, list) else []
    macs = []
    for item in items:
        raw_mac = item.get("mac") if isinstance(item, dict) else item
        mac = normalize_mac_if_valid(raw_mac)
        if mac and mac not in macs:
            macs.append(mac)
    return macs


def portal_device_mac_values(*values) -> list[str]:
    macs = []
    for value in values:
        if isinstance(value, list):
            for mac in portal_previous_mac_values(value):
                if mac not in macs:
                    macs.append(mac)
            continue
        mac = normalize_mac_if_valid(value)
        if mac and mac not in macs:
            macs.append(mac)
    return macs


def customer_device_group_key(value: Optional[str]) -> str:
    text = normalize_payment_text(value, 120).lower()
    text = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return text or "unknown-device"


def customer_device_verified_mac_links() -> set[tuple[str, str]]:
    links: set[tuple[str, str]] = set()

    def add_link(mac_a, mac_b):
        normalized_a = normalize_mac_if_valid(mac_a)
        normalized_b = normalize_mac_if_valid(mac_b)
        if not normalized_a or not normalized_b or normalized_a == normalized_b:
            return
        links.add((normalized_a, normalized_b))
        links.add((normalized_b, normalized_a))

    try:
        for row in fetch_all(
            """
            SELECT old_client_mac, new_client_mac
            FROM portal_mac_rebind_events
            WHERE status IN ('SUCCESS', 'SKIPPED')
              AND old_client_mac IS NOT NULL
              AND new_client_mac IS NOT NULL
            ORDER BY created_at DESC
            LIMIT 2000
            """
        ):
            add_link(row.get("old_client_mac"), row.get("new_client_mac"))
    except Exception:
        pass

    return links


def customer_device_groups(device_rows: list[dict]) -> dict:
    customers = {}
    unprofiled_customers = {}
    verified_mac_links = customer_device_verified_mac_links()

    def has_verified_mac_link(source_macs: list[str], target_macs: list[str]) -> bool:
        source_set = {normalize_mac_if_valid(mac) for mac in source_macs or []}
        target_set = {normalize_mac_if_valid(mac) for mac in target_macs or []}
        source_set.discard(None)
        target_set.discard(None)
        if source_set & target_set:
            return True
        return any((source_mac, target_mac) in verified_mac_links for source_mac in source_set for target_mac in target_set)

    def upsert_group(bucket: dict, row: dict):
        profile_id = row.get("customer_profile_id")
        user_id = row.get("user_id")
        has_profile = bool(profile_id)
        customer_key = f"profile:{profile_id}" if has_profile else (f"user:{user_id}" if user_id else "no-profile")
        if not has_profile:
            customer_key = f"{customer_key}:{row.get('device_group_key') or row.get('client_mac') or row.get('client_ip') or row.get('portal_session_id') or row.get('id')}"
        customer = bucket.setdefault(customer_key, {
            "customer_key": customer_key,
            "has_profile": has_profile,
            "profile_id": str(profile_id) if profile_id else None,
            "user_id": str(user_id) if user_id else None,
            "name": row.get("customer_name") or "",
            "email": row.get("customer_email") or "",
            "contact_number": row.get("customer_contact_number") or "",
            "contact_verified_at": row.get("contact_verified_at"),
            "marketing_sms_consent": bool(row.get("marketing_sms_consent")),
            "welcome_gift_status": row.get("welcome_gift_status"),
            "devices": [],
            "device_count": 0,
            "mac_count": 0,
            "active_device_count": 0,
            "remaining_time_seconds": 0,
            "latest_seen": None,
        })
        for field, key in [
            ("customer_name", "name"),
            ("customer_email", "email"),
            ("customer_contact_number", "contact_number"),
            ("contact_verified_at", "contact_verified_at"),
            ("welcome_gift_status", "welcome_gift_status"),
        ]:
            if row.get(field) and not customer.get(key):
                customer[key] = row[field]
        if row.get("marketing_sms_consent"):
            customer["marketing_sms_consent"] = True
        if row.get("profile_only"):
            customer["remaining_time_seconds"] = max(int(customer.get("remaining_time_seconds") or 0), int(row.get("remaining_time_seconds") or 0))
            if row.get("last_seen") and (not customer.get("latest_seen") or str(row["last_seen"]) > str(customer["latest_seen"])):
                customer["latest_seen"] = row["last_seen"]
            return

        device_key = row.get("device_group_key") or customer_device_group_key(row.get("device_name") or row.get("hostname") or row.get("client_mac") or row.get("client_ip"))
        device = next((item for item in customer["devices"] if item["device_key"] == device_key), None)
        if not device:
            device = {
                "device_key": device_key,
                "device_name": row.get("device_name") or row.get("hostname") or "Unknown device",
                "source": row.get("source"),
                "status": row.get("status"),
                "active": bool(row.get("active")),
                "client_ip": row.get("client_ip"),
                "ap_name": row.get("ap_name"),
                "ap_mac": row.get("ap_mac"),
                "ssid": row.get("ssid"),
                "site": row.get("site"),
                "last_seen": row.get("last_seen"),
                "portal_session_id": row.get("portal_session_id"),
                "public_session_id": row.get("public_session_id"),
                "voucher_code": row.get("voucher_code"),
                "remaining_time_seconds": int(row.get("remaining_time_seconds") or 0),
                "mac_addresses": [],
                "sessions": [],
            }
            customer["devices"].append(device)
        else:
            for field in ["device_name", "client_ip", "ap_name", "ap_mac", "ssid", "site", "portal_session_id", "public_session_id", "voucher_code"]:
                if row.get(field) and not device.get(field):
                    device[field] = row[field]
            device["active"] = bool(device.get("active") or row.get("active"))
            if row.get("status") == "ACTIVE" or device["active"]:
                device["status"] = "ACTIVE"
            device["remaining_time_seconds"] = max(int(device.get("remaining_time_seconds") or 0), int(row.get("remaining_time_seconds") or 0))
            if row.get("last_seen") and (not device.get("last_seen") or str(row["last_seen"]) > str(device["last_seen"])):
                device["last_seen"] = row["last_seen"]

        for mac in row.get("mac_addresses") or []:
            if mac not in device["mac_addresses"]:
                device["mac_addresses"].append(mac)
        device["sessions"].append({
            "portal_session_id": row.get("portal_session_id"),
            "public_session_id": row.get("public_session_id"),
            "client_mac": row.get("client_mac"),
            "client_ip": row.get("client_ip"),
            "last_seen": row.get("last_seen"),
            "status": row.get("status"),
            "voucher_code": row.get("voucher_code"),
        })
        customer["active_device_count"] += 1 if row.get("active") else 0
        customer["remaining_time_seconds"] = max(int(customer.get("remaining_time_seconds") or 0), int(row.get("remaining_time_seconds") or 0))
        if row.get("last_seen") and (not customer.get("latest_seen") or str(row["last_seen"]) > str(customer["latest_seen"])):
            customer["latest_seen"] = row["last_seen"]

    for row in device_rows:
        upsert_group(customers if row.get("customer_profile_id") else unprofiled_customers, row)

    profiled_device_index = {}
    for customer in customers.values():
        for device in customer.get("devices") or []:
            profiled_device_index.setdefault(device.get("device_key"), device)

    for customer_key, customer in list(unprofiled_customers.items()):
        remaining_devices = []
        for device in customer.get("devices") or []:
            profiled_device = profiled_device_index.get(device.get("device_key"))
            is_stale_omada_only = bool(
                profiled_device
                and has_verified_mac_link(device.get("mac_addresses") or [], profiled_device.get("mac_addresses") or [])
                and not device.get("active")
                and not device.get("portal_session_id")
                and not device.get("public_session_id")
                and not device.get("voucher_code")
                and device.get("source") == "OMADA"
            )
            if not is_stale_omada_only:
                remaining_devices.append(device)
                continue
            for mac in device.get("mac_addresses") or []:
                if mac not in profiled_device["mac_addresses"]:
                    profiled_device["mac_addresses"].append(mac)
            for session in device.get("sessions") or []:
                profiled_device["sessions"].append(session)
        if remaining_devices:
            customer["devices"] = remaining_devices
        else:
            unprofiled_customers.pop(customer_key, None)

    def finalize(bucket: dict) -> list[dict]:
        rows = []
        for customer in bucket.values():
            for device in customer["devices"]:
                device["mac_count"] = len(device["mac_addresses"])
                device["mac_addresses"] = sorted(device["mac_addresses"])
            customer["devices"] = sorted(customer["devices"], key=lambda item: (not item.get("active"), str(item.get("device_name") or "")))
            customer["device_count"] = len(customer["devices"])
            customer["mac_count"] = sum(len(device.get("mac_addresses") or []) for device in customer["devices"])
            rows.append(customer)
        return sorted(rows, key=lambda item: (not item.get("active_device_count"), str(item.get("name") or item.get("latest_seen") or "")))

    return {
        "customers": finalize(customers),
        "without_profiles": finalize(unprofiled_customers),
    }


def fetch_portal_session_for_admin(cur, session_id: str):
    cur.execute(
        """
        SELECT s.*, v.code AS voucher_code, v.voucher_type, v.time_value_seconds, v.valid_until, v.unlimited_expires_at,
               u.username
        FROM portal_sessions s
        LEFT JOIN vouchers v ON v.id = s.voucher_id
        LEFT JOIN users u ON u.id = s.user_id
        WHERE s.id::text = %s OR s.public_session_id = %s
        FOR UPDATE OF s
        """,
        (str(session_id), str(session_id)),
    )
    row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Portal session not found")
    return row


def sync_short_omada_expiry(cur, session: dict, admin, seconds: int = 1):
    if session.get("source") != "OMADA" or not session.get("user_id"):
        return None
    voucher = fetch_one("SELECT * FROM vouchers WHERE id = %s", (session["voucher_id"],)) if session.get("voucher_id") else None
    if not voucher:
        voucher = {"id": session.get("voucher_id"), "code": session.get("voucher_code") or "ACCESS"}
    user = {"id": session["user_id"], "username": session.get("username") or "portal"}
    duration = max(int(seconds), 1)
    expires_at = datetime.now(timezone.utc) + timedelta(seconds=duration)
    cur.execute(
        """
        SELECT DISTINCT ON (COALESCE(client_mac, ''), COALESCE(site_id, ''), COALESCE(ssid, ''))
               *
        FROM omada_portal_authorizations
        WHERE portal_session_id = %s
          AND status = 'SUCCESS'
          AND COALESCE(client_mac, '') <> ''
          AND (access_expires_at IS NULL OR access_expires_at > now())
        ORDER BY COALESCE(client_mac, ''), COALESCE(site_id, ''), COALESCE(ssid, ''), created_at DESC
        """,
        (session["id"],),
    )
    authorizations = cur.fetchall()
    if not authorizations:
        authorizations = [{
            "client_mac": session.get("omada_client_mac") or session.get("client_mac"),
            "ap_mac": session.get("omada_ap_mac") or session.get("ap_mac"),
            "gateway_mac": session.get("omada_gateway_mac") or session.get("gateway_mac"),
            "ssid": session.get("ssid"),
            "site_id": session.get("omada_site_id"),
            "site_name": session.get("omada_site_name") or session.get("site"),
            "omada_request_summary": {},
        }]

    results = []
    for authorization in authorizations:
        request_summary = authorization.get("omada_request_summary") if isinstance(authorization.get("omada_request_summary"), dict) else {}
        payload = PortalRedeemRequest(
            portal_session_id=session.get("public_session_id"),
            voucher_code=voucher.get("code") or "ADMIN",
            client_mac=authorization.get("client_mac"),
            ap_mac=authorization.get("ap_mac"),
            gateway_mac=authorization.get("gateway_mac"),
            ssid=authorization.get("ssid"),
            site_id=authorization.get("site_id"),
            site=authorization.get("site_name"),
            radio_id=request_summary.get("radio_id"),
            raw_query_params={},
        )
        if not payload.client_mac:
            continue
        result = attempt_omada_authorization(cur, session, voucher, user, duration, expires_at, payload)
        results.append({
            "client_mac": mask_mac(payload.client_mac),
            "ssid": payload.ssid,
            "site_id": payload.site_id,
            "status": result.get("status"),
            "error": result.get("error"),
        })
    return {
        "status": "SUCCESS" if results and all(item.get("status") == "SUCCESS" for item in results) else ("SKIPPED" if not results else "PARTIAL"),
        "synced_authorization_count": len(results),
        "results": results,
    }


def revoke_omada_authorized_clients(cur, session: dict, admin=None) -> dict:
    if session.get("source") != "OMADA":
        return {"status": "SKIPPED", "message": "Session is not an Omada portal session."}
    cur.execute(
        """
        SELECT DISTINCT ON (COALESCE(site_id, ''), COALESCE(client_mac, ''), COALESCE(ssid, ''))
               site_id, site_name, client_mac, ssid
        FROM omada_portal_authorizations
        WHERE portal_session_id = %s
          AND status = 'SUCCESS'
          AND COALESCE(client_mac, '') <> ''
        ORDER BY COALESCE(site_id, ''), COALESCE(client_mac, ''), COALESCE(ssid, ''), created_at DESC
        """,
        (session["id"],),
    )
    rows = cur.fetchall()
    candidates = []
    for row in rows:
        candidates.append({
            "site_id": row.get("site_id"),
            "site_name": row.get("site_name"),
            "client_mac": row.get("client_mac"),
            "ssid": row.get("ssid"),
        })
    if session.get("omada_client_mac") or session.get("client_mac"):
        candidates.append({
            "site_id": session.get("omada_site_id"),
            "site_name": session.get("omada_site_name"),
            "client_mac": session.get("omada_client_mac") or session.get("client_mac"),
            "ssid": session.get("ssid"),
        })

    settings = ensure_captive_portal_settings()
    _, selected_site_id, selected_site_name = omada_selected_site(settings)
    grouped = {}
    for item in candidates:
        site_id = (item.get("site_id") or selected_site_id or "").strip()
        if not site_id:
            continue
        grouped.setdefault(site_id, {"site_id": site_id, "site_name": item.get("site_name") or selected_site_name, "macs": set(), "ssids": set()})
        if item.get("client_mac"):
            grouped[site_id]["macs"].add(item["client_mac"])
        if item.get("ssid"):
            grouped[site_id]["ssids"].add(item["ssid"])

    if not grouped:
        return {"status": "SKIPPED", "message": "No Omada client authorization record was found for this session."}

    _, client = omada_api_client_from_settings()
    results = []
    for site_id, group in grouped.items():
        try:
            result = client.disconnect_hotspot_authorized_clients(
                site_id,
                client_macs=sorted(group["macs"]),
                ssids=sorted(group["ssids"]),
            )
            results.append({
                "site_id": site_id,
                "site_name": group.get("site_name"),
                "client_macs": [mask_mac(mac) for mac in sorted(group["macs"])],
                "status": "SUCCESS" if result.get("error_count") == 0 else "PARTIAL",
                "matched_count": result.get("matched_count", 0),
                "disconnected_count": result.get("disconnected_count", 0),
                "error_count": result.get("error_count", 0),
                "details": sanitize_summary(result),
            })
        except Exception as exc:
            response_summary = exc.response_summary if isinstance(exc, OmadaApiError) else {}
            results.append({
                "site_id": site_id,
                "site_name": group.get("site_name"),
                "client_macs": [mask_mac(mac) for mac in sorted(group["macs"])],
                "status": "FAILED",
                "error": str(exc),
                "details": sanitize_summary(response_summary),
            })

    now = datetime.now(timezone.utc)
    cur.execute(
        """
        UPDATE omada_portal_authorizations
        SET access_expires_at = %s, updated_at = now()
        WHERE portal_session_id = %s
          AND status = 'SUCCESS'
        """,
        (now, session["id"]),
    )
    disconnected_count = sum(int(item.get("disconnected_count") or 0) for item in results)
    failed = [item for item in results if item.get("status") == "FAILED" or int(item.get("error_count") or 0) > 0]
    status = "SUCCESS" if disconnected_count > 0 and not failed else ("PARTIAL" if disconnected_count > 0 else ("FAILED" if failed else "SKIPPED"))
    log_captive_portal_test(
        "REVOKE_OMADA_CLIENT",
        "SUCCESS" if status in {"SUCCESS", "SKIPPED"} else "FAILED",
        "Omada authorized client revoke completed." if status != "SKIPPED" else "No active Omada authorized client needed revoke.",
        {"session_id": str(session["id"]), "results": results},
    )
    return {
        "status": status,
        "disconnected_count": disconnected_count,
        "results": results,
    }


def adjust_portal_session_time(
    cur,
    session_id: str,
    amount_seconds: int,
    admin,
    note: Optional[str] = None,
    bag_item_id: Optional[str] = None,
    affect_all_session_items: bool = False,
):
    session = fetch_portal_session_for_admin(cur, session_id)
    now = datetime.now(timezone.utc)
    requested_delta = int(amount_seconds or 0)

    target_bag_items: list[dict] = []
    if session.get("user_id"):
        if bag_item_id:
            cur.execute(
                """
                SELECT *
                FROM customer_bag_items
                WHERE id = %s
                  AND user_id = %s
                  AND status = 'ACTIVE'
                FOR UPDATE
                """,
                (bag_item_id, session["user_id"]),
            )
            target_bag_items = cur.fetchall()
            if not target_bag_items:
                raise HTTPException(status_code=404, detail="Active product item was not found for this customer.")
        elif affect_all_session_items:
            cur.execute(
                """
                SELECT *
                FROM customer_bag_items
                WHERE user_id = %s
                  AND portal_session_id = %s
                  AND status = 'ACTIVE'
                ORDER BY active_until ASC NULLS LAST, updated_at ASC
                FOR UPDATE
                """,
                (session["user_id"], session["id"]),
            )
            target_bag_items = cur.fetchall()
        else:
            cur.execute(
                """
                SELECT *
                FROM customer_bag_items
                WHERE user_id = %s
                  AND portal_session_id = %s
                  AND status = 'ACTIVE'
                  AND active_until IS NOT NULL
                  AND active_until > now()
                ORDER BY active_until DESC, updated_at DESC
                LIMIT 1
                FOR UPDATE
                """,
                (session["user_id"], session["id"]),
            )
            target_bag_items = cur.fetchall()

    if not target_bag_items and not session.get("voucher_id"):
        raise HTTPException(status_code=400, detail="This device has no active voucher or product item to manage.")

    affected_bag_item_ids = []
    iptv_line_results = []
    actual_delta_seconds = 0
    if target_bag_items:
        for item in target_bag_items:
            current_until = aware_utc(item.get("active_until"))
            current_remaining = max(int((current_until - now).total_seconds()), 0) if current_until else max(int(item.get("remaining_seconds") or 0), 0)
            base = current_until if current_until and current_until > now else now
            new_until = now if affect_all_session_items and requested_delta < 0 else base + timedelta(seconds=requested_delta)
            new_remaining = max(int((new_until - now).total_seconds()), 0)
            actual_delta_seconds += new_remaining - current_remaining
            finished = new_until <= now
            next_status = "CANCELLED" if finished and affect_all_session_items else ("CONSUMED" if finished else "ACTIVE")
            cur.execute(
                """
                UPDATE customer_bag_items
                SET status = %s,
                    remaining_seconds = %s,
                    active_until = %s,
                    consumed_at = CASE WHEN %s THEN COALESCE(consumed_at, now()) ELSE consumed_at END,
                    updated_at = now()
                WHERE id = %s
                RETURNING *
                """,
                (next_status, new_remaining, now if finished else new_until, finished, item["id"]),
            )
            updated_item = cur.fetchone()
            affected_bag_item_ids.append(str(updated_item["id"]))
            if finished and product_kind_requires_iptv(updated_item.get("product_kind")):
                iptv_line_results.append(sanitize_summary(schedule_iptv_line_deletion_for_bag_item(cur, updated_item, "ADMIN_ACCESS_REMOVED")))
            create_customer_bag_event(
                cur,
                item["user_id"],
                item["id"],
                session["id"],
                "ADMIN_TIME_ADJUST",
                note or ("Access removed by operator." if affect_all_session_items else "Time adjusted by operator."),
                metadata={
                    "amount_seconds": requested_delta,
                    "actual_delta_seconds": new_remaining - current_remaining,
                    "old_remaining_seconds": current_remaining,
                    "new_remaining_seconds": new_remaining,
                    "admin_id": str(admin["id"]),
                },
            )
        cur.execute(
            """
            SELECT max(active_until) AS access_until
            FROM customer_bag_items
            WHERE portal_session_id = %s
              AND status = 'ACTIVE'
              AND active_until IS NOT NULL
              AND active_until > now()
            """,
            (session["id"],),
        )
        new_expiry = aware_utc((cur.fetchone() or {}).get("access_until")) or now
    else:
        current_expiry = aware_utc(session.get("access_expires_at")) or now
        current_remaining = max(int((current_expiry - now).total_seconds()), 0)
        base = current_expiry if current_expiry > now else now
        new_expiry = base + timedelta(seconds=requested_delta)
        new_remaining = max(int((new_expiry - now).total_seconds()), 0)
        actual_delta_seconds = new_remaining - current_remaining

    expired = new_expiry <= now
    stored_expiry = now if expired else new_expiry
    new_status = "EXPIRED" if expired else "ACCESS_GRANTED"
    cur.execute(
        """
        UPDATE portal_sessions
        SET access_expires_at = %s,
            status = %s,
            last_error = CASE WHEN %s THEN 'Access removed by operator.' ELSE NULL END,
            updated_at = now()
        WHERE id = %s
        RETURNING *
        """,
        (stored_expiry, new_status, expired, session["id"]),
    )
    updated = cur.fetchone()
    omada_sync = None
    if updated.get("source") == "OMADA":
        try:
            if expired:
                omada_sync = revoke_omada_authorized_clients(cur, updated, admin)
            else:
                remaining = max(int((aware_utc(updated.get("access_expires_at")) - now).total_seconds()), 1)
                omada_sync = sync_short_omada_expiry(cur, updated, admin, remaining)
        except Exception as exc:
            omada_sync = {"status": "FAILED", "error": str(exc)}
        if expired:
            cur.execute(
                """
                UPDATE omada_portal_authorizations
                SET access_expires_at = now(), updated_at = now()
                WHERE portal_session_id = %s
                  AND status = 'SUCCESS'
                  AND (access_expires_at IS NULL OR access_expires_at > now())
                """,
                (session["id"],),
            )
            cur.execute(
                "UPDATE portal_sessions SET status = 'EXPIRED', access_expires_at = %s, updated_at = now() WHERE id = %s RETURNING *",
                (now, session["id"]),
            )
            updated = cur.fetchone()
    speed_limit = safe_reconcile_portal_speed_limit_for_session(cur, updated, None, "ADMIN_TIME_ADJUST")
    return {
        "status": "ok",
        "session": updated,
        "remaining_time_seconds": max(int((aware_utc(updated.get("access_expires_at")) - now).total_seconds()), 0),
        "actual_delta_seconds": actual_delta_seconds,
        "affected_bag_item_ids": affected_bag_item_ids,
        "iptv_line_results": iptv_line_results,
        "omada_sync": sanitize_summary(omada_sync),
        "speed_limit": sanitize_summary(speed_limit),
    }


def log_failed_redemption(cur, voucher, payload: VoucherRedeemTest, reason: str, source="ADMIN_TEST", request: Request = None):
    cur.execute(
        """
        INSERT INTO voucher_redemptions(voucher_id, user_id, username, device_identifier, source, result, failure_reason, ip_address, user_agent)
        VALUES (%s, NULL, %s, %s, %s, 'FAILED', %s, NULLIF(%s, '')::inet, %s)
        """,
        (
            voucher["id"] if voucher else None,
            payload.username,
            payload.device_identifier,
            source,
            reason,
            request.client.host if request and request.client else "",
            request.headers.get("user-agent") if request else None,
        ),
    )


def redeem_voucher(cur, payload: VoucherRedeemTest, admin_id: str, request: Request = None, source="ADMIN_TEST"):
    normalized = normalize_voucher_code(payload.voucher_code)
    cur.execute("SELECT * FROM vouchers WHERE normalized_code = %s FOR UPDATE", (normalized,))
    voucher = cur.fetchone()
    if not voucher:
        return {"status": "FAILED", "reason": "Voucher not found"}

    user = None
    if payload.user_id:
        cur.execute("SELECT u.* FROM users u WHERE u.id = %s", (payload.user_id,))
        user = cur.fetchone()
    elif payload.username:
        cur.execute("SELECT u.* FROM users u WHERE lower(u.username) = lower(%s)", (payload.username,))
        user = cur.fetchone()
    if not user:
        log_failed_redemption(cur, voucher, payload, "User not found", source, request)
        return {"status": "FAILED", "reason": "User not found", "voucher_id": voucher["id"]}

    failure = None
    if voucher["status"] == "USED":
        failure = "Voucher already used"
    elif voucher["status"] == "EXPIRED" or (voucher["expires_at"] and voucher["expires_at"] <= datetime.now(timezone.utc)):
        failure = "Voucher expired"
    elif voucher["status"] == "DISABLED":
        failure = "Voucher disabled"
    elif voucher["status"] == "VOIDED":
        failure = "Voucher voided"
    elif voucher["redemption_count"] >= voucher["max_redemptions"]:
        failure = "Voucher redemption limit reached"
    elif voucher["voucher_type"] not in VOUCHER_TYPES:
        failure = "Invalid voucher type"
    if failure:
        if failure == "Voucher expired" and voucher["status"] == "UNUSED":
            cur.execute("UPDATE vouchers SET status = 'EXPIRED', updated_at = now() WHERE id = %s", (voucher["id"],))
        log_failed_redemption(cur, voucher, payload, failure, source, request)
        return {"status": "FAILED", "reason": failure, "voucher_id": voucher["id"]}

    redeemed_time = voucher["time_value_seconds"] if voucher["voucher_type"] == "TIME_BASED" else 0
    redeemed_valid_until = voucher["valid_until"] if voucher["voucher_type"] == "DATE_BASED" else (voucher["unlimited_expires_at"] if voucher["voucher_type"] == "UNLIMITED" else None)
    redeemed_unlimited = voucher["voucher_type"] == "UNLIMITED"
    cur.execute(
        """
        INSERT INTO voucher_redemptions(voucher_id, user_id, username, device_identifier, source,
                                        result, redeemed_time_seconds, redeemed_valid_until, redeemed_unlimited, ip_address, user_agent)
        VALUES (%s, %s, %s, %s, %s, 'SUCCESS', %s, %s, %s, NULLIF(%s, '')::inet, %s)
        RETURNING id
        """,
        (
            voucher["id"],
            user["id"],
            user["username"],
            payload.device_identifier,
            source,
            redeemed_time,
            redeemed_valid_until,
            redeemed_unlimited,
            request.client.host if request and request.client else "",
            request.headers.get("user-agent") if request else None,
        ),
    )
    redemption_id = cur.fetchone()["id"]
    next_count = voucher["redemption_count"] + 1
    next_status = "USED" if next_count >= voucher["max_redemptions"] else voucher["status"]
    cur.execute(
        """
        UPDATE vouchers
        SET redemption_count = %s,
            redeemed_by_user_id = %s,
            redeemed_at = now(),
            status = %s,
            updated_at = now()
        WHERE id = %s
        """,
        (next_count, user["id"], next_status, voucher["id"]),
    )
    return {
        "status": "SUCCESS",
        "message": "Voucher accepted",
        "voucher_id": voucher["id"],
        "voucher_code": voucher["code"],
        "user_id": user["id"],
        "username": user["username"],
        "redemption_id": redemption_id,
        "time_added_seconds": redeemed_time,
        "valid_until": redeemed_valid_until,
        "unlimited": redeemed_unlimited,
    }


@app.get("/api/physical-stores")
def get_physical_stores(admin=Depends(current_admin)):
    stores = physical_store_rows(active_only=False)
    active = [store for store in stores if store.get("status") == "ACTIVE"]
    setup = [store for store in stores if store.get("status") == "SETUP"]
    disabled = [store for store in stores if store.get("status") == "DISABLED"]
    items = physical_store_item_catalog_rows(active_only=False)
    assigned_counts = fetch_all(
        """
        SELECT item_id, COUNT(*)::int AS store_count
        FROM physical_store_item_assignments
        GROUP BY item_id
        """
    )
    count_map = {str(row["item_id"]): int(row.get("store_count") or 0) for row in assigned_counts}
    for item in items:
        item["assigned_store_count"] = count_map.get(item["id"], 0)
    return {
        "stores": stores,
        "items": items,
        "locations": list_locations(admin),
        "sites": local_site_deployments_for_ap_inventory(),
        "summary": {
            "total": len(stores),
            "active": len(active),
            "setup": len(setup),
            "disabled": len(disabled),
            "assigned_sites": len({site["site_deployment_id"] for store in stores for site in store.get("sites", [])}),
            "with_coordinates": len([store for store in stores if store.get("latitude") is not None and store.get("longitude") is not None]),
        },
    }


