@app.post("/api/omada/payment-auth-free/abuse/remove")
def remove_omada_payment_auth_free_abuse(payload: OmadaPaymentAuthFreeAbuseRemoveRequest, admin=Depends(current_admin)):
    identity = omada_payment_auth_free_abuse_identity(payload.model_dump(exclude_none=True))
    if not any(identity.get(key) for key in ("user_id", "client_mac", "device_token_hash", "profile_contact_number")):
        raise HTTPException(status_code=400, detail="Customer, MAC, device token, or contact number is required.")
    override = add_omada_payment_auth_free_abuse_override(identity, admin["id"])
    with get_conn() as conn:
        with conn.cursor() as cur:
            clauses = []
            params = []
            if identity.get("user_id"):
                clauses.append("user_id::text = %s")
                params.append(identity["user_id"])
            if identity.get("client_mac"):
                clauses.append("client_mac = %s")
                params.append(identity["client_mac"])
            if identity.get("device_token_hash"):
                clauses.append("device_token_hash = %s")
                params.append(identity["device_token_hash"])
            if identity.get("profile_contact_number"):
                clauses.append("profile_contact_number = %s")
                params.append(identity["profile_contact_number"])
            cur.execute(
                f"""
                UPDATE omada_payment_auth_free_abuse_blocks
                SET block_until = now(),
                    reason = 'ADMIN_REMOVED',
                    updated_at = now()
                WHERE block_until > now()
                  AND ({' OR '.join(clauses)})
                """,
                tuple(params),
            )
            audit(
                admin["id"],
                "remove_omada_payment_auth_free_abuse",
                "omada_controller",
                identity.get("user_id") or identity.get("client_mac") or identity.get("device_token_hash") or identity.get("profile_contact_number"),
                {"identity": identity, "override": sanitize_summary(override)},
            )
            conn.commit()
            return omada_payment_auth_free_dashboard_payload(cur)


@app.post("/api/omada/payment-auth-free/remote/remove")
def remove_remote_omada_payment_auth_free(payload: OmadaPaymentAuthFreeRemoteRemoveRequest, admin=Depends(current_admin)):
    site_id = normalize_payment_text(payload.site_id, 160)
    client_mac = normalize_mac_if_valid(payload.client_mac)
    client_ip = host_ip(payload.client_ip)
    if not site_id:
        raise HTTPException(status_code=400, detail="Omada site ID is required.")
    if not client_mac and not client_ip:
        raise HTTPException(status_code=400, detail="Client MAC or IP is required.")
    try:
        _, client = omada_api_client_from_settings()
        result = client.remove_auth_free_client(site_id, client_mac=client_mac, client_ip=client_ip)
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Could not remove Omada Authentication-Free Client: {exc}")
    with get_conn() as conn:
        with conn.cursor() as cur:
            clauses = ["site_id = %s", "status IN ('ACTIVE', 'PAID_GRACE', 'REMOVE_FAILED')"]
            params = [site_id]
            match_clauses = []
            if client_mac:
                match_clauses.append("client_mac = %s")
                params.append(client_mac)
            if client_ip:
                match_clauses.append("client_ip = NULLIF(%s, '')::inet")
                params.append(client_ip)
            if match_clauses:
                cur.execute(
                    f"""
                    UPDATE omada_payment_auth_free_grants
                    SET status = 'REMOVED',
                        removed_at = now(),
                        removal_response_summary = %s,
                        last_error = NULL,
                        updated_at = now()
                    WHERE {' AND '.join(clauses)}
                      AND ({' OR '.join(match_clauses)})
                    """,
                    (Json(sanitize_summary(result)), *params),
                )
            audit(
                admin["id"],
                "remove_remote_omada_payment_auth_free",
                "omada_controller",
                site_id,
                {"site_id": site_id, "client_mac": client_mac, "client_ip": client_ip, "result": sanitize_summary(result)},
            )
            conn.commit()
            return omada_payment_auth_free_dashboard_payload(cur)


